COLLDATA("asabahur","ur",[[3379,"§۳۳۸۵ ۔ سلمہ بن ابی سلمہ(1)\nالجرمی۔ وہی ابن نفیع ہیں، تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۷۲)"}],[3380,"§۳۳۸۶ ۔ سلمہ بن ابی سلمہ الہذلی\nبقول بعض: الکندی۔ ابو یعلی(1) کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قیس بن مالک کی طرف لکھا: اما بعد!","",{"fn":"(1) مسند ابی یعلی (۹۱۲/۲)"}],[3381,"§۳۳۸۷ ۔ سلمہ بن صخر(1)\nبن سلمان بن الصمہ بن حارث بن زید مناۃ بن حبیب بن عبد حارثہ بن مالک بن غضب بن جشم بن خزرج خزرجی۔ انہیں بیاضی اس وجہ سے کہا جاتا ہے کہ ان کے حلیف تھے۔ بقول بعض: ان کا نام سلمان ہے، جبکہ سلمہ زیادہ صحیح ہے۔(2) انہوں نے ہی اپنی بیوی سے ظہار کیا تھا۔ بغوی فرماتے ہیں: مجھے ان کی کوئی مستند حدیث سوائے حدیث ظہار کے نہیں ملی۔ جسے ان سے سعید بن المسیب، سلیمان بن سیارہ ابو سلمہ، سماک بن عبد الرحمن اور محمد بن عبد الرحمن بن ثوبان نقل کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۷۵) استیعاب (۱۰۲۸) تجرید (۲۳۲/۱)\n(2) ترمذی کتاب الطلاق (۱۱۹۸)"}],[3382,"§۳۳۸۸ ۔ سلمہ بن صخر\nبقول بعض: الحیق کا نام صحر ہے، تذکرہ ہوگا۔"],[3383,"§۳۳۸۹ ۔ سلمہ بن عرادہ(1)\nبن مالک الضعی، صفوان کے والد۔ دار قطنی کتاب النسب العقیق سے اخبار بنی ضبہ کے متعلق لکھا ہے کہ سلمہ بن عرادہ کا عیینہ بن حصن سے نبی صلی اللہ علیہ وسلم کے وضو سے بچے ہوئے پانی کے بارے میں جھگڑا ہو گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: “لڑکے کو وضو کرنے دو”۔(2) چنانچہ انہوں نے وضو کیا اور بقیہ پانی پی لیا۔ آپ صلی اللہ علیہ وسلم نے ان کے سر اور چہرہ پر اپنا دست مبارک پھیرا۔","",{"fn":"(1) اسد الغابہ (۲۱۷۷)\n(2) جامع المسانید (۴۷۷/۵)"}],[3384,"§۳۳۹۰ ۔ سلمہ بن عمرو(1)\nبن الاکوع۔ اکوع کا نام سنان بن عبد اللہ تھا۔ ان کا بقیہ نسب عامر بن اکوع میں بیان ہوگا۔ ان کے والد کا نام وہیب بھی بتایا جاتا ہے۔ سب سے پہلے حدیبیہ کے معرکہ میں شریک ہوئے۔ بہادروں میں شمار ہوتا تھا۔ دوڑ کی رفتار اتنی تیز تھی کہ گھوڑے سے آگے نکل جاتے۔ نبی کریم صلی اللہ علیہ وسلم کے ہاتھ پر درخت کے پاس موت کی بیعت کی۔ امام بخاری رحمہ اللہ نے ان کی حدیث نقل کی ہے۔ انہوں نے حضرات شیخین رضی اللہ عنہما سے بھی روایت لی ہے۔ جبکہ ان سے ان کا بیٹا الیاس، حسن بن محمد بن الحنفیہ، زید بن اسلم اور ان کے مولا یزید بن ابی عبید روایت کرتے ہیں۔ مدینہ فروکش ہوئے۔ پھر سیدنا عثمان رضی اللہ عنہ کی شہادت کے بعد وہاں سے تین میل دور بمقام الربذہ(2) منتقل ہو گئے۔ وہیں شادی کی اور اولاد ہوئی۔ وفات سے کچھ روز پہلے مدینہ آئے اور بقول امام بخاری رحمہ اللہ وہیں چوہتر (۷۴ھ) میں جو صحیح قول ہے فوت ہوئے، ایک قول ہے: چونسٹھ (۶۴ھ) میں وفات پائی۔ واقدی اور ان کے متبعین کا گمان ہے کہ وہ اسی(۸۰) سال زندہ رہے۔ جو پہلے قول کی بنا پر غلط ہے۔ اس سے تو یہ لازم آتا ہے کہ حدیبیہ میں وہ دس برس کے تھے اور جو اس عمر میں ہوگا وہ موت کی بیعت کیسے کر سکتا ہے۔ پھر مجھے ابن سعد کی کتاب میں یہ روایت ملی کہ وہ امیر معاویہ کی خلافت کے آخری دور میں فوت ہوئے۔(3) ایسا ہی بلاذری نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۷۸)\n(2) جگہ کا نام ہے۔\n(3) الطبقات (۳۰۵/۴)"}],[3385,"§۳۳۹۱ ۔ سلمہ بن عیاد\nعائذ بن سلمہ میں تذکرہ ہوگا۔"],[3386,"§۳۳۹۲ ۔ سلمہ بن عیاض الاسدی\nرشاطی نے ان کا ذکر کیا ہے کہ وہ اور جارود عبدی نبی صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم نے ان دونوں کو ان کی بات پوچھنے سے پہلے بتا دیا تھا کہ وہ کیا پوچھنا چاہتے ہیں جس کا لمبا قصہ ہے۔ تو سلمہ نے بے ساختہ کہا: ط “اے تمام مخلوق سے بہتر انسان! میں نے دیکھا کہ آپ نے اس کتاب کو جو حق سے پر ہے پھیلا دی ہے جبکہ ہم لوگ حق سے برگشتہ ہو چکے اور دین (ابراہیمی) گمراہیوں کی تاریکیوں میں چھپ گیا تھا، آپ نے ہمارے لیے راہ ہدایت کی بنیاد رکھی۔”"],[3387,"§۳۳۹۳ ۔ سلمہ بن قیس الاشجعی الغطفانی(1)\nانہیں شرف صحابیت حاصل ہے۔ بقول بعض: کوفہ فروکش ہوئے۔ نبی صلی اللہ علیہ وسلم سے ان کی روایت بھی ہے۔ ان سے ہلال بن یساف(2) روایت کرتے ہیں۔ ایک قول ہے یہ ان سے روایت کرنے میں منفرد ہیں۔ اسی پر ابو الفتوح ازدی اور ان کے متبعین نے اعتماد کیا ہے۔ ان کی ایک روایت بطریق ابو اسحاق سبیعی مروی ہے۔ بغوی فرماتے ہیں: انہوں نے تین احادیث نقل کی ہیں۔ سعید بن منصور نے صحیح سند سے روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے فارس کی کسی جنگ کا انہیں امیر بنایا تھا۔","",{"fn":"(1) اسد الغابہ (۲۱۷۹) استیعاب (۱۰۲۹)\n(2) مسند احمد (۳۱۳/۴)"}],[3388,"§۳۳۹۴ ۔ سلمہ بن قیصر\nسلامہ میں تذکرہ ہوا ہے۔"],[3389,"§۳۳۹۵ ۔ سلمہ بن مالک سلمی(1)\nباوردی کی روایت ہے کہ سیدنا عمار بن یاسر رضی اللہ عنہ نے فرمایا نبی صلی اللہ علیہ وسلم نے سلمہ بن مالک سلمی کو ایک رقبہ زمین عطا کیا اور ان کے لیے یہ تحریر لکھوائی: «بسم اللہ الرحمن الرحیم۔ یہ اس زمین کی سند ہے جو محمد رسول اللہ صلی اللہ علیہ وسلم نے سلمہ بن مالک کو دی ہے»۔(2) پھر اسے ذکر کیا۔ ابن مندہ کا قول ہے: یہ روایت غریب ہے، جسے ہم اسی سند سے پہچانتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۸۱)\n(2) اسد الغابہ (۲۹۹/۲)"}],[3390,"§۳۳۹۶ ۔ سلمہ بن المحبق الہذلی(1)\nمحبق کا نام صحر بھی بتایا جاتا ہے۔ بعض نے ربیعہ اور عبید بھی لکھا ہے۔ ایک قول ہے: محق ان کے دادا ہیں۔ مشہور اس نام میں باء کا زبر ہے عمر بن شبہ نے باء کے زیر کی وجہ سے اس کا انکار کیا ہے۔ عسکری لکھتے ہیں: میں نے ان کے شاگرد احمد بن عبد العزیز الجوہری سے کہا: تمام محدثین اسے زبر کے ساتھ محبق پڑھتے ہیں، تو وہ کہنے لگے: بھلا لفظ محبق کا لغت میں کیا معنیٰ ہے۔ میں نے کہا: گوز مروانے والا۔ کہنے لگے: انہیں محبق اس وجہ سے کہا جاتا ہے کہ وہ اپنے دشمنوں کو گوز مارنے پر مجبور کر دیتے تو تفاؤلا انہیں ایسا کہا جاتا ہے جیسا کہ لوگ عمرو بن ہند کو مضرط الحجارہ کہتے ہیں۔ کنیت ابو سنان تھی۔ ان کی ایک روایت بھی ہے، بصرہ کے رہائشی تھے۔ ان سے ان کا بیٹا سنان، جون بن قتادہ قبیصہ بن حریث اور حسن بصری وغیرہ روایت کرتے ہیں۔ ابو سلیمان بن زبر نے الصحابہ میں لکھا ہے۔ سلمہ کو جب ان کے بیٹے سنان کی خوشخبری ملی تو اس وقت وہ حنین میں تھے۔ تو فرمانے لگے: “وہ تیر جو میں رسول اللہ صلی اللہ علیہ وسلم کے دفاع میں چلا رہا ہوں اس سے کئی گنا زیادہ عزیز ہے جس کی تم نے مجھے خوشخبری دی ہے”۔(2)","",{"fn":"(1) استیعاب (۱۰۳۱) تجرید (۳۲/۱)\n(2) مسند احمد (۲۴۶/۷)"}],[3391,"§۳۳۹۷ ۔ سلمہ بن مسعود(1)\nبن سنان انصاری از بنی غنم بن کعب۔ بقول ابو عمر:(2) یمامہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۸۳) استیعاب (۱۰۳۲)\n(2) استیعاب (۲۰۲/۲)"}],[3392,"§۳۳۹۸ ۔ سلمہ بن معاویہ\nبن وہب بن قیس بن حجر بن وہب بن ربیعہ بن معاویہ۔ ابو قرہ کندی۔ بقول ابن سعد اور طبری: انہیں آنے کی سعادت حاصل ہے۔"],[3393,"§۳۳۹۹ ۔ سلمہ بن میلاء الجہنی(1)\nبقول بعض: ملیاء۔ ابن شاہین کا قول ہے۔ فتح مکہ کے روز سیدنا خالد بن ولید رضی اللہ عنہ کے دستہ میں شہید ہوئے۔ کیونکہ وہ راستہ بھول گئے۔ اس لیے قتل ہو گئے تھے۔","",{"fn":"(1) اسد الغابہ (۲۱۸۴) استیعاب (۱۰۳۳)"}],[3394,"§۳۴۰۰ ۔ سلمہ بن نعیم(1)\nبن مسعود اشجعی۔ امام بخاری رحمہ اللہ اور ابو حاتم کا قول ہے: یہ اور ان کے والد صحابی ہیں۔ امام احمد(2) کی روایت ہے صحابی رسول صلی اللہ علیہ وسلم تھے۔ فرماتے ہیں، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “جس کی اس حال میں اللہ تعالیٰ سے ملاقات ہوئی کہ اس نے اللہ کے ساتھ کسی کو شریک نہیں کیا تو جنت میں جائے گا خواہ اس سے زنا ہو گیا یا چوری ہو گئی۔ ابو داؤد نے ان کی روایت سے ان کے والد کے حوالہ سے ایک حدیث مسیلمہ کذاب کے قاصد کے بارے میں نقل کی ہے۔ بغوی فرماتے ہیں: مجھے اس کے علاوہ ان کی کوئی حدیث معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۸۶) استیعاب (۱۰۳۴) تجرید (۲۳۳/۱)\n(2) مسند احمد (۳۵۷/۶)"}],[3395,"§۳۴۰۱ ۔ سلمہ بن نضر\nبن غانم بن عامر بن عبد اللہ بن عبید بن عویج بن عدی بن کعب قرشی عدوی، زبیر کا قول ہے: غانم بن عامر کے گھر نضر بن غانم اور نضر بن غانم کے ہاں سلمہ کی ولادت ہوئی۔ ان کی والدہ بنی فراس سے تھیں، نضر اور ان کا بیٹا طاعون میں فوت ہوئے۔ اس کا تقاضا ہے کہ سلمہ اور ان کے بیٹے صحابی ہوں۔ کیونکہ مکہ میں فتح کے بعد جو قریشی بھی زندہ رہا وہ اسلام لا کر حجتہ الوداع میں شریک ہوا، جیسا کہ پہلے بتایا جا چکا ہے۔"],[3396,"§۳۴۰۲ ۔ سلمہ بن نفیع الجرمی(1)\nطبری نے ان کا ذکر سلمہ سے علیحدہ کیا ہے جو عمرو جرمی کے والد ہیں۔ ایسا ہی ابن عبد البر(2) نے کہا ہے کہ جابر جرمی ان سے روایت کرتے ہیں۔ جبکہ ابن مندہ کا خیال ہے یہی عمرو کے والد ہیں۔ حالانکہ درست اس کے برعکس ہے۔ اس واسطے کہ عمرو بن سلمہ کے والد کا نام لام کے زیر سے ہی زیادہ صحیح ہے۔ اور ان کے والد کا نام قیس ہے نہ کہ نفیع۔","",{"fn":"(1) اسد الغابہ (۲۱۸۷) استیعاب (۱۰۳۵)\n(2) استیعاب (۲۰۲/۲)"}],[3397,"§۳۴۰۳ ۔ سلمہ بن نفیل السکونی(1)(5)\nثم التراغمی۔ بقول ابو حاتم(2) اور امام بخاری(3)، انہیں شرف صحابیت حاصل ہے۔ ان سے ضمرہ بن حبیب اور جبیر بن نفیر روایت کرتے ہیں۔ حمص فروکش ہوئے نسائی میں ان کی ایک حدیث ہے۔ بقول بعض: اس کے علاوہ ان کی کوئی حدیث نہیں۔ وہ بھی ضمرہ بن حبیب کی روایت سے ہے۔ فرماتے ہیں: میں نے سلمہ بن نفیل سکونی کو فرماتے سنا: ہم لوگ نبی صلی اللہ علیہ وسلم کے پاس بیٹھے تھے ایک شخص کہنے لگا: اللہ کے رسول! آپ کے پاس جنت کا کھانا آیا ہے۔۔۔ (حدیث) اس میں ہے: “میں نے تم لوگوں میں تھوڑا عرصہ ہی رہنا ہے۔ اسی میں ہے: “قیامت سے پہلے سخت قحط سالی ہو گئی، اس کے بعد زلزلوں کے سال ہوں گے”۔(4) یہی روایت بحوالہ ان کے ابن حبان نے انہترویں (۶۹ ویں) نوع کے تیسرے حصہ میں نقل کی ہے کہ “میں تم لوگوں میں تھوڑا ہی عرصہ رہوں گا”۔ اس کا پہلا حصہ نہیں ذکر کیا۔ اس کو طحاوی نے نقل کیا ہے یہ حدیث صحیح ابو عوانہ کی زیادات میں ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۸۸) استیعاب (۱۰۳۶) تجرید (۲۳۳/۱)\n(2) الجرح والتعدیل (۱۷۳/۴)\n(3) التاریخ الکبیر (۷۰/۲)\n(4) مسند احمد (۱۰۶/۶)\n(5) المستدرک (۹۴۷/۴)"}],[3398,"§۳۴۰۴ ۔ سلمہ بن ہشام(1)\nبن المغیرہ بن عبد اللہ بن عمر بن مخزوم المخزومی۔ ابو جہل اور حارث کے بھائی۔ کنیت ابو ہاشم تھی۔ اسلام کی طرف سبقت کرنے والوں میں سے تھے۔ صحیح میں حدیث ابو ہریرہ میں ان سے ان کا ذکر ثابت ہے کہ نبی صلی اللہ علیہ وسلم نے جب رکوع سے سر اٹھایا تو کفار سے ان کی نجات کے لیے دعا کی۔(2) کفار نے انہیں ہجرت سے باز رکھا اور انہیں اذیت پہنچائی۔ چنانچہ عبد الرزاق کی روایت ہے کہ عیاش بن ابی ربیعہ سلمہ بن ہشام اور ولید بن ولید مشرکین سے جان بچا کر بھاگ نکلے۔ نبی صلی اللہ علیہ وسلم کو ان کی اطلاع ملی تو آپ صلی اللہ علیہ وسلم نے رکوع سے سر اٹھاتے ہوئے ان کے حق میں دعا کی۔ ابن اسحاق کی حدیث ام سلمہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے سلمہ بن ہشام کی بیوی سے کہا: کیا بات ہے؟ مجھے سلمہ نبی صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے نظر نہیں آتے؟ وہ کہنے لگیں: وہ جب بھی باہر نکلتے، لوگ کہتے: اے بھگوڑے! یہ غزوہ موتہ کے بعد کا واقعہ ہے۔ یہی روایت واقدی نے دوسری سند سے نقل کی ہے جس میں یہ اضافہ ہے نبی صلی اللہ علیہ وسلم نے فرمایا نہیں بلکہ یہ لوٹنے والے ہیں۔ ابن سعد(3) کی روایت ہے کہ جب سلمہ قریش سے بھاگ نکلے تو ان کی والدہ ضباعہ نے کہا: ط\nلاہم ربّ الکعبۃ المحرمۃ اظہر علی کل عدو سلمۃ\n“اے اللہ! کعبہ معظمہ کے رب! سلمہ کو ہر کافر پر غلبہ عطا فرما۔”\nفرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم کا انتقال ہوا تو یہ شام چلے گئے اور مرج صفر میں محرم چودہ (۱۴ھ) میں شہید ہوئے۔ عروہ اور موسیٰ بن عقبہ کا بیان ہے: اجنادین میں شہید ہوئے۔ اسی پر ابو زرعہ دمشقی نے اعتماد کیا ہے اور امام احمد نے اسے درست کہا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۸۹) استیعاب (۱۰۳۷)\n(2) بخاری کتاب الاذان (۸۰۶) مسلم کتاب المساجد باب استحباب القنوت فی جمیع الصلاۃ (۲۹۵)\n(3) الطبقات (۹۶/۴)"}],[3399,"§۳۴۰۵ ۔ سلمہ بن وہب بن الاکوع\nاپنے دادا کی نسبت سے مشہور ہیں۔ مشہور یہ ہے کہ سلمہ بن عمرو ہیں، جیسے پہلے گزر گیا اور جعلیات میں ہے: سلمہ بن وہب۔"],[3400,"§۳۴۰۶ ۔ سلمہ بن یزید(1)\nبن مشجعہ بن المجمع بن مالک بن کعب بن سعد بن عوف بن حریم بن جعفی، الجعفنی کوفہ فروکش ہوئے۔ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ سے حدیث کی روایت بھی کی ہے ان سے ایک حدیث مروی ہے کہ میں نے عرض کی: اللہ کے رسول! ہماری والدہ ملیکہ صلہ رحمی (رشتہ داروں کا پاس لحاظ) کیا کرتی تھیں۔۔۔۔ (حدیث)(2) صحیح مسلم میں حدیث وائل بن حجر سے مروی ہے کہ سلمہ بن یزید(3) بعضی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا، پھر وہ حدیث ذکر کی۔ بقول ابن کلبی ان کا بیٹا کریب بن سلمہ انتہائی صاحب شرافت انسان تھے اور انہیں یزید بن سلمہ بھی کہا جاتا ہے۔ مرزبانی لکھتے ہیں: یہ اور ان کے ماں شریک بھائی قیس بن سلمہ بن شراحیل بارگاہ نبوت میں آکر اسلام لائے۔ آپ صلی اللہ علیہ وسلم نے قیس کو بنی مروان کا نگران مقرر کیا اور انہیں تحریر لکھ کر دی۔ یہی سلمہ بن یزید ہی اپنے سگے بھائی قیس بن یزید کا مرثیہ کہتے ہیں: ط “تو نہیں جانتی کہ جب تک میں زندہ ہوں اپنے بھائی سے نہیں مل سکتا میری اور اس کی ملاقات میں قبر حائل ہے۔ اور اس بات سے میرا غم ہلکا ہو گیا کہ ایک دن میں نے بھی اسی کے نقش قدم پر چلنا ہے، اگر چہ عمر لمبی ہو جائے۔ وہ ایسا نو جوان تھا کہ مالداری اسے اس کے دوست کے قریب کرتی تھی جب وہ مستغنی ہوتا اور محتاجی اسے دور کرتی تھی۔”","",{"fn":"(1) اسد الغابہ (۲۱۹۰) استیعاب (۱۰۳۸) تجرید (۲۳۴/۱)\n(2) مسند احمد (۴۷۸/۳)\n(3) مسند احمد (۴۸۷/۳)"}],[3401,"§۳۴۰۷ ۔ سلمہ بن یزید الاشجعی\nان لوگوں میں سے ہیں جنہوں نے ابن مسعود رضی اللہ عنہ کو بروع بنت واشق کا واقعہ سنایا تھا۔ ابن عساکر سے بھول ہوئی اور انہوں نے اطراف میں انہیں بھی لکھ دیا ہے۔ مجھے انتہائی عالی سند سے ان کی حدیث پہنچی ہے جو ابن صاعد کی دوسری جلد میں حدیث ابن مسعود سے بروایت زائدہ بحوالہ منصور مروی ہے۔ اس میں ہے: پھر اشجع کا ایک شخص اٹھا، منصور نے کہا: جہاں تک میرا خیال ہے یہ سلمہ بن یزید اشجعی ہیں۔ فرمایا: اسی طرح کا فیصلہ نبی کریم صلی اللہ علیہ وسلم نے ہماری قوم کی ایک عورت کے بارے میں کیا تھا۔ ایسی ہی روایت امام احمد(1) نے بطریق زائدہ نقل کی ہے۔ اسی طرح نسائی نے ابن صاعد کے شیخ سے اپنی سند سے یہ روایت نقل کی ہے اور ان کا نام نہیں لیا۔ اور بطریق داؤد بواسطہ شعبی بحوالہ علقمہ روایت کی ہے۔ اس میں ہے پھر اشجع کے کچھ لوگ اٹھے، جراح اشجعی کے حالات میں اس حدیث کا دوسرا طریق پہلے بیان ہو چکا ہے۔","",{"fn":"(1) مند احمد (الحدیث: ۴۸۷/۳)"}],[3402,"§۳۴۰۸ ۔ سلمہ (اصیل بن سلمہ کے والد)\nان کے بیٹے کے حالات میں ان کا ذکر ہوا ہے۔"],[3403,"§۳۴۰۹ ۔ سلمہ الخزاعی\nابو نعیم نے ان کا ذکر کیا ہے اور جگہ خالی چھوڑی ہے۔ شاید ان کی مراد ابن بدیل سے ہو جن کا پہلے تذکرہ ہوا ہے۔ واقدی فرماتے ہیں: یہ سلمہ بن قرط بن عبید ہیں۔"],[3404,"§۳۴۱۰ ۔ سلمہ ابو سنان(1)\nبغوی کی روایت ہے کہ سلمہ ابو سنان صحابی رسول صلی اللہ علیہ وسلم ہیں۔ فرماتے ہیں: نبی صلی اللہ علیہ وسلم نے ایک شخص کے ساتھ دو اونٹ روانہ کیے اور فرمایا: اگر انہیں کوئی مسئلہ ہو جائے تو انہیں نحر (ذبح) کر لینا”۔ (حدیث)(2) بغوی فرماتے ہیں: یہی روایت ابو یعلی نے بواسطہ عبد الکریم نقل کی ہے اور اس میں “بحوالہ ان کے والد” نہیں کہا۔","",{"fn":"(1) تجرید (۲۳۲/۱)\n(2) مسند احمد (۶/۵) کنز العمال (۱۲۲۷۵) مجمع الزوائد (۲۲۸/۳)"}],[3405,"§۳۴۱۱ ۔ سلمہ ابو یزید(1)\nعبد الحمید انصاری کے دادا۔ بعض نے ان کے والد کا نام یزید بتایا ہے۔ ابن حبان فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ ان کی حدیث(2) نسائی نے نقل کی ہے جس میں بچے کو والدین میں سے ایک کے انتخاب کرنے کا حکم ہے (جب دونوں کا دین جدا جدا ہو جائے)۔ دار قطنی وغیرہ کا بیان ہے: سلمہ عبد الحمید کے دادا ہیں، انہی کی نسبت سے یہ لکھے جاتے ہیں۔ جبکہ ان کا نسب یوں ہے: عبد الحمید بن یزید بن سلمہ۔ مذکورہ انتخاب والی حدیث ابو داؤد نے بروایت عبد الحمید بن جعفر بحوالہ اپنے دادا نقل کی ہے جس سے کسی کو دھوکا ہو گیا کہ ان کے والد کے نام میں اختلاف ہے، یوں انہوں نے رافع بن سنان کے حالات میں ان کا ذکر کر دیا، جو عبد الحمید بن جعفر کے دادا ہیں جس کی کچھ حیثیت نہیں، اس میں کوئی رکاوٹ نہیں ہے، کئی واقعات پیش آئے ہوں۔ بغوی ظاہری سند کے مطابق چلتے ہوئے کنیتوں میں ان کا عنوان “ابو سلمہ” قائم کر گئے ہیں۔ اور مذکورہ حدیث بطریق عبد الحمید بن سلمہ بواسطہ ان کے والد بحوالہ ان کے دادا نقل کی ہے۔ دار قطنی نے ان کا جو ذکر کیا ہے وہ قابل اعتماد ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۱)\n(2) نسائی کتاب الطلاق باب اسلام احد الزوجین (۳۲۹۵)"}],[3406,"§۳۴۱۲ ۔ سلمہ(1)\nوہی ابن قیس بن نفیع ہیں۔ بقول بعض: ابن لائم یا لائی بن قدامہ الجرمی بقول بعض یہ نام لام کے زبر سے ہے۔ عمرو بن سلمہ کے والد ہیں۔(2) ان کی حدیث(3) بخاری کی تخریج کی نسبت سے بیان ہوگی۔ اس میں سلمہ کی آمد کا ذکر ہے جو ان کے بیٹے عمرو کے حالات میں ہے۔ پہلے بیان ہو چکا ہے کہ کسی نے انہیں اور سلمہ بن نفیع کو ایک لکھا ہے، جو وہم ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۲) استیعاب (۱۰۳۰) تجرید (۲۳۳/۱)\n(2) التاریخ الکبیر (۶۹/۴)\n(3) اسد الغابہ (۲۱۹۳) استیعاب (۱۰۴۱)"}],[3407,"§۳۴۱۳ ۔ سلمی بن حنظلہ السحیمی(1)\nسالم کے والد۔ بقول ابو عمر: ان کی ایک حدیث ہے۔ بقول ابن حبان: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ کی روایت ہے کہ سلمی بن حنظلہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: آپ نے بنی امیہ کے بارے میں فرمایا: “فلاں شخص کی وجہ سے ان کے لیے خرابی ہے۔”(2) مدائنی وغیرہ کا بیان ہے کہ انہی مذکورہ سلمی نے یمامہ میں ان کی عبادت گاہ ویران کر کے اس کی جگہ مسجد کی بنیاد رکھی وہ بنی حنیفہ کے پہلے وفد میں تھے۔","",{"fn":"(1) استیعاب (۶۴۲/۲)\n(2) کنز العمال (۳۱۰۵۹) (۳۱۷۵۰)"}],[3408,"§۳۴۱۴ ۔ سلمی بن القین(1)\nبن عمرو بن بکر بن مالک بن حنظلہ بن مالک بن زید مناۃ تمیمی حنظلی۔ بقول ابن کلبی: صحابی ہیں۔ حرملہ بن مریطہ کے حالات میں ان کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۵) استیعاب (۱۰۴۲) تجرید (۲۳۴/۱)"}],[3409,"§۳۴۱۵ ۔ سلمی بن نوفل\nبن معاویہ الدئلی۔ ابن کلبی نے ان کا ذکر کیا ہے، ان کے والد نوفل کا تذکرہ ہوگا۔ سلمی نبی صلی اللہ علیہ وسلم کے آخری دور میں نو سال کے لگ بھگ تھے۔ سلمی کے متعلق ہی ایک شاعر کہتا ہے: ط “لوگ سردار نہ ہونے کے باوجود سردار بن بیٹھے، جبکہ قابل تعریف سردار تو سلمی بن نوفل ہے۔” مدائنی نے یہ اشعار سنائے ہیں، لکھتے ہیں: سلمی بڑے ثقہ تھے۔ “الاغانی” میں ابو الفرج نے لکھا ہے کہ ابن زبیر رضی اللہ عنہ کا خلافت سے پہلے ابو قرعہ سلمی بن نوفل کے ساتھ چپقلش و معارضہ تھا، جب ابن زبیر خلیفہ بنے، لوگوں سے خطاب کر رہے تھے، سلمی مسجد میں داخل ہوئے، جب واپس ہوئے تو محافظ سے کہا اٹھو مسجد کی فلاں جگہ جاؤ اور سلمی بن نوفل کو میرے پاس لے آؤ، چنانچہ وہ انہیں لے آیا۔ ابن زبیر نے فرمایا: ارے ذیخ (بھیڑئیے!) تو سلمی نے جواب دیا: جو شخص میری اور تمہاری عمر کا ہو جائے وہ ذیخ ہی کہلائے گا۔ پھر ایک واقعہ نقل کیا۔ میں کہتا ہوں: اس سے معلوم ہوا ان کی عمر ابن زبیر رضی اللہ عنہ کے قریب تھی۔"],[3410,"§۳۴۱۶ ۔ سلیط بن ثابت(1)\nبن وقش انصاری۔ طبرانی وغیرہ کا بیان ہے، ابو الاسود بحوالہ عروہ فرماتے ہیں: یہ احد میں شریک ہوئے اور اسی میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۷)"}],[3411,"§۳۴۱۷ ۔ سلیط بن حارث الہلالی(1)\nاہلِ بنی ہلال یا سیدہ میمونہ رضی اللہ عنہا کے رضاعی (دودھ شریک) بھائی۔ ابن مندہ کی روایت ہے کہ ابو الحارث ایک جنازہ میں نکلے، پھر کچھ لوگوں کی طرف متوجہ ہو کر فرمانے لگے: مجھے سلیط نے بتایا جو سیدہ میمونہ رضی اللہ عنہا کے رضاعی بھائی تھے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “جس کی نماز جنازہ لوگوں کی ایک جماعت نے پڑھی ہو تو ان کی سفارش میت کے حق میں قبول ہوتی ہے”۔(2) میں کہتا ہوں: اس کی سند میں اختلاف ہے۔ بقول بعض سلیط بحوالہ سیدہ میمونہ رضی اللہ عنہا اور ایک قول ہے، عبد اللہ بن سلیط بحوالہ میمونہ رضی اللہ عنہا روایت کرتے ہیں، جو نسائی میں ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۸) تجرید (۲۳۵/۱)\n(2) کنز العمال (۴۲۳۰۶)"}],[3412,"§۳۴۱۸ ۔ سلیط بن حرملہ\nسویبط میں تذکرہ ہوگا۔"],[3413,"§۳۴۱۹ ۔ سلیط بن سفیان(1)\nبن خالد بن عوف اسلمی۔ بقول ابو عمر:(2) ان تین میں سے ایک ہیں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے احد کے روز مشرکین کی نقل و حرکت کے بارے معلومات کے لیے بھیجا تھا۔ مالک بن عوف خزاعی کے حالات میں ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۹۹) استیعاب (۱۰۴۳)\n(2) استیعاب (۲۰۵/۲)"}],[3414,"§۳۴۲۰ ۔ سلیط بن سلیط(1)\nبن عمرو بن عبد شمس بن عبد ود بن نصر بن مالک بن حسل بن عامر قرشی عامری، سہیل بن عمرو کے بھتیجے، ان کے والد کا تذکرہ ہوتا ہے۔ ابو اسحاق(2) نے انہیں مہاجرین حبشہ میں ذکر کیا ہے کہ سلیط بن عمرو اور ان کی اہلیہ ام یقطہ بنت علقمہ نے ہجرت کی جہاں سلیط بن سلیط کی ولادت ہوئی۔ سلیط اپنے والد کے ہمراہ یمامہ میں شریک ہوئے اور وہیں شہادت پائی۔ ابو معشر کا قول ہے نہیں بلکہ اس کے بعد بھی زندہ رہے۔ ابو عمر(3) لکھتے ہیں: یہی زیادہ درست ہے۔ کیونکہ جب سیدنا عمر رضی اللہ عنہ کے پاس جوڑے لائے گئے تو آپ نے فرمایا: مجھے کوئی ایسا نو جوان بتاؤ جو خود اور اس کے والد نے ہجرت کی ہو تو لوگوں نے ان کا پتہ بتایا۔ زبیر بن بکار کا قول ہے کہ سیدنا عمر رضی اللہ عنہ کے پاس اصحاب رسول صلی اللہ علیہ وسلم میں جوڑے تقسیم کرنے کے بعد ایک جوڑا بچ گیا۔ تو آپ نے فرمایا: مجھے ایسا شخص بتاؤ جس نے اور اس کے والد نے ہجرت کی ہو۔ لوگوں نے کہا: ابن عمر۔ جس پر ابن عمر رضی اللہ عنہما فرمانے لگے: مجھے تو ہجرت کرائی گئی ہے، ایسا نوجوان سلیط بن سلیط ہے۔ چنانچہ آپ نے وہ جوڑا انہیں دے دیا۔ میں کہتا ہوں: اسی واقعہ کو عمر بن شبہ وغیرہ نے بطریق ابن سیرین بواسطہ کثیر بن افلح نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ جوڑے تقسیم کر رہے تھے، ایک عمدہ جوڑا سامنے آیا، کسی نے کہا: ابن عمر رضی اللہ عنہما کو دے دیجئے۔ آپ نے فرمایا: میں یہ جوڑا ہجرت کرنے والے، ہجرت کرنے والے کے بیٹے کو دوں گا۔ جو سلیط بن سلیط یا سعید بن عتاب ہے۔ میں کہتا ہوں: اکثریت کا اس سے اتفاق ہے کہ ان کے والد یمامہ میں شہید ہوئے ہیں۔ ہو سکتا ہے ابن اسحاق کی یہی مراد ہو۔ اور اگر ابن اسحاق کا یہ قول صحیح ثابت ہو جائے کہ وہ حبشہ میں پیدا ہوئے تو پھر سیدنا عمر رضی اللہ عنہ کے قول پر منطبق نہیں ہو گا کہ وہ مہاجر بن مہاجر ہے۔ اس واسطے کہ ایسے افراد کی تعداد تو بہت زیادہ ہے۔ جیسے محمد بن حاطب، عبد اللہ بن جعفر، اسی بنا پر ابن مندہ نے صاحب سوانح اور اس شخص میں فرق کیا ہے جس کا واقعہ سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آیا۔","",{"fn":"(1) اسد الغابہ (۲۲۰۰) استیعاب (۱۰۴۴) تجرید (۲۳۵/۱)\n(2) السیرۃ النبویہ (۸/۴)\n(3) استیعاب (۲۰۵/۲)"}],[3415,"§۳۴۲۱ ۔ سلیط بن سلیط\nسابقہ عنوان میں انہی کا ذکر ہوا ہے۔"],[3416,"§۳۴۲۲ ۔ سلیط بن سلیط\nخواتین کے حصہ میں کنیتوں میں ام سلیط کے حالات میں ان کا ذکر ہوگا۔"],[3417,"§۳۴۲۳ ۔ سلیط بن عمرو(1)\nبن عبد شمس عامری۔ ان کا نسب سابقہ شخصیت کے حالات میں بیان ہو چکا ہے۔ اور قریب ہی ان کے بھائی سکران بن عمرو کا ذکر ہوا ہے۔ سلیط بہت پہلے سیدنا عمر رضی اللہ عنہ سے بھی پہلے اسلام لائے۔ ابن اسحاق نے مہاجرین حبشہ میں ان کا ذکر کیا ہے جبکہ موسیٰ بن عقبہ نے ان کا ذکر نہیں کیا۔ واقدی اور ابو معشر نے بدری صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن اسحاق نے بادشاہوں کی طرف بھیجے جانے والے سفیروں میں ان کا نام لیا ہے کہ سلیط بن عمرو کو یمامہ کے بادشاہ ھوزہ بن علی کی جانب بھیجا۔ اس روایت کو اسمعیل بن عیاش نے ابن اسحاق، زہری، عروہ بحوالہ عائشہ رضی اللہ عنہا میں بھی نقل کیا ہے۔ طبرانی نے اسے روایت کیا ہے۔ پہلے بیان ہوا ہے کہ ابن اسحاق نے انہیں شہداء یمامہ میں اسی طرح ابن کلبی نے ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۳۵/۱)"}],[3418,"§۳۴۲۴ ۔ سلیط بن عمرو بن زید\nابن عائذ نے شہداء احد میں ان کا ذکر کیا ہے۔"],[3419,"§۳۴۲۵ ۔ سلیط بن عمرو انصاری\nابن سعد نے بیعت النساء کے باب میں طبقات النساء کے حصہ میں بحوالہ واقدی ان کی سند سے بحوالہ ام عمارہ ان کا ذکر کیا ہے۔ فرماتی ہیں: بیعت عقبہ کے بعد ہم اپنے سامان کے پاس واپس آئے۔ تو ہماری قوم کے دو آدمی ہمیں ملے جن میں سے ایک سلیط بن عمرو اور دوسرا ابو داؤد المازنی تھا، وہ بھی بیعت میں شریک ہونا چاہتے تھے، لوگ بیعت کر چکے تھے۔ انہوں نے بعد میں اسعد بن زرارہ سے بیعت کی وہ عقبہ کی رات ستر نقباء کے سردار تھے۔"],[3420,"§۳۴۲۶ ۔ سلیط بن قیس(1)\nبن عمرو بن عبد اللہ بن مالک بن عدی بن عامر بن غنم بن عدی بن النجار انصاری نجاری بدری۔ موسیٰ بن عقبہ اور ابو الاسود نے بحوالہ عروہ ان کا ذکر کیا ہے۔ موسیٰ کا قول ہے: ان کی کوئی نرینہ اولاد نہیں۔ ابن سعد نے لکھا ہے: تمام معرکوں میں شریک ہوئے اور جسر ابی عبید میں شہید ہوئے۔ یہی ابن کلبی کا قول ہے۔ ابن مندہ کی روایت ہے: ایک انصاری شخص کے باغ میں دوسرے شخص کا کھجور کا درخت تھا۔ جہاں وہ صبح و شام آتا تو آپ صلی اللہ علیہ وسلم نے اسے حکم دیا کہ وہ باغ کے قریب والی کھجور کا درخت اسے دے دے۔(2) تھا اسمعیلی نے مسند زید بن ابی انیسہ میں اسی طرح کی روایت نقل کی ہے۔ ابن الاثیر نے نسائی کی تخریج سے ان کا نسب بیان کیا ہے۔ لیکن مجھے سنن میں نہیں ملا۔ ابن مندہ نے صرف اپنے طریق سے اس کا ذکر کیا ہے۔ میں کہتا ہوں: اس سے موسیٰ بن عقبہ کے قول کی تردید ہوتی ہے کہ ان کی نرینہ اولاد نہ تھی۔ اگر موسیٰ کی بات صحیح ثابت ہو جائے تو احتمال ہے حدیث والے صحابی صاحب سوانح کے علاوہ کوئی شخص ہوں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۲۰۴) استیعاب (۱۰۴۶) تجرید (۲۳۵/۱)\n(2) الطبقات (۶۹/۳)"}],[3421,"§۳۴۲۷ ۔ سلیط التمیمی(1)\nبقول ابو عمر:(2) صحابی ہیں اور اہل بصرہ میں شمار ہوتے ہیں۔ ان سے ابن سیرین اور حسن بصری روایت کرتے ہیں۔ ابن سیرین کی روایت سے بحوالہ ان کے مروی ہے کہ سیدنا عثمان رضی اللہ عنہ نے محاصرہ کے وقت ان لوگوں کو گشت و خون سے منع فرمایا تھا۔ میں کہتا ہوں: حسن کی روایت سے بحوالہ ان کے مروی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس پہنچا، آپ نے فرمایا: “مسلمان، مسلمان کا بھائی ہے”۔ (حدیث)(3)","",{"fn":"(1) جامع المسانید (۵۰۴/۵)\n(2) اسد الغابہ (۲۱۹۶) استیعاب (۱۰۴۷)\n(3) استیعاب (۲۰۶/۲)"}],[3422,"§۳۴۲۸ ۔ سلیط انصاری(1)\nدلائل میں ابو نعیم نے لکھا ہے، جب رسول اللہ صلی اللہ علیہ وسلم نے ہجرت کی اور آپ کے ساتھ ابو بکر، عامر بن فہیرہ اور ابن اریقط تھے۔ یہ حضرات ام معبد خزاعیہ کے پاس سے گزرے، وہ انہیں پہچانتی نہ تھیں۔ پھر لمبی حدیث ذکر کی۔۔۔۔ اسی روایت کو طبرانی نے سلیط بن قیس کے حالات میں درج کیا ہے۔ سلیط بن قیس کے سوانح میں اس کے تعدد (کئی بار پیش آنے) کی طرف اشارہ ہو چکا ہے۔ ابن مندہ کو ان کے بارے میں وہم ہوا ہے جسے میں نے علاقہ کے حالات میں بیان کیا ہے۔","",{"fn":"(1) المعجم الکبیر (۷۴/۲۲) مجمع الزوائد (۳۳۸/۱۸) الدر المنثور (۲۲۱/۱)"}],[3423,"§۳۴۲۹ ۔ سلیط الجنی\nارقم الجنی کے حالات میں ان کا ذکر ہوا ہے۔"],[3424,"§۳۴۳۰ ۔ سلیک\nتصغیر ہے۔ ابن الاغتر ابو سلیط کنیتوں میں تذکرہ ہوگا۔"],[3425,"§۳۴۳۱ ۔ سلیک بن عمرو(1)\nیا ابن حذبہ الغطفانی۔ حدیث جابر سے صحیح میں ان کا ذکر ملتا ہے کہ وہ جمعہ کے دن مسجد میں اس وقت داخل ہوئے جب رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم نے نماز پڑھ لی؟ یہ بخاری میں مبہم روایت ہے۔ امام احمد اور دار قطنی نے بطریق ابو سفیان بحوالہ جابر رضی اللہ عنہ روایت کی ہے کہ سلیک نے فرمایا، نبی صلی اللہ علیہ وسلم نے ارشاد فرمایا: امام احمد رحمہ اللہ نے دوسری سند سے بحوالہ جابر رضی اللہ عنہ روایت کی ہے کہ غطفان کا سلیک نامی شخص آیا۔ ابن ماجہ، ابو یعلی بحوالہ ابو سفیان اور جابر روایت کرتے ہیں کہ سلیک آئے۔ یہی روایت مسلم، ابو داؤد اور صحیح ابن خزیمہ میں صرف بطریق جابر مروی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۰۶) تجرید (۲۳۵/۱)"}],[3426,"§۳۴۳۲ ۔ سلیک (دوسرے)(1)\nبے نسبت ابن مندہ نے ان میں اور غطفانی میں فرق کیا ہے۔ جبکہ ابو نعیم نے دونوں کو ایک لکھا ہے جو ان کا وہم ہے۔ ان کی حدیث حرف ذال میں ذو الغزہ میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۰۷)"}],[3427,"§۳۴۳۳ ۔ سلیل اشجعی(1)(3)(4)\nعبد الغنی بن سعید نے “المشتبه” میں اور ابو عمر نے لکھا ہے، یہ صحابی ہیں۔ ان سے ابو اسلیح بن اسامہ روایت کرتے ہیں۔ بغوی کی روایت ہے اور ابن شاہین اور حسن بن سفیان نے بطریق خالد بن عبد اللہ طحان بحوالہ سلیل اشجعی روایت کی ہے کہ “ایک رات ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ اچانک آپ صلی اللہ علیہ وسلم وہاں سے علیحدہ ہوئے تو ہمیں چکی کے گھومنے کے جیسی آواز سنائی دی۔۔۔۔” (حدیث)(2) اسی میں شفاعت کا ذکر ہے۔ بغوی لکھتے ہیں: سلیل کی اس کے علاوہ کوئی روایت نہیں۔ ابن مندہ فرماتے ہیں: یہ وہم ہے، درست ابن علیہ کی بواسطہ جریری، ابو سلیل سے، ابو اسلیح سے بحوالہ الجھی جو عوف بن مالک میں روایت ہے۔ اسی طرح خطیب نے “المؤتلف” میں اور ابن ماکولا نے “الاکمال” میں اعتماد ظاہر کیا ہے کہ خالد بن عبد اللہ کو اس میں وہم ہوا ہے۔ پھر اس کے علل اور طرق کو بیان کیا۔ اس کے بعد لکھا ہے: جریری کی ابو اسلیح سے ملاقات نہیں ہوئی۔ انہوں نے یہ روایت ان کے حوالہ سے بواسطہ ابو السلیل نقل کی ہے۔ پھر خالد کو اس میں خبط ہو گیا۔ میں کہتا ہوں: اس کا قتادہ سے بواسطہ ابو اسلیح بحوالہ عوف بن مالک ایک طریق ہے۔ خلاصہ یہ کہ ان کا معاملہ اس کا احتمال رکھتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۰۸) استیعاب (۱۰۴۹) تجرید (۲۳۵/۱)\n(2) استیعاب (۲۴۶/۲)\n(3) المعجم الکبیر (۵۹/۱۸) جمع الجوامع (۲۲۳) الترغیب والترهیب (۴۳۴/۳)\n(4) الاکمال (۳۳/۲)"}],[3428,"§۳۴۳۴ ۔ سلیم بن احمر\nاحمر بن سلیم میں تذکرہ ہوا ہے۔"],[3429,"§۳۴۳۵ ۔ سلیم بن اکیمہ اللیثی(1)\nطبرانی(2) کی روایت ہے کہ سلیم بن اکیمہ نے فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: “جب تک (حدیث کا مفہوم بیان کرنے میں) کسی حرام کو حلال اور کسی حلال کو حرام نہ بناؤ بلکہ صحیح مفہوم مطلب بیان کرو تو (روایت بالمعنی کرنے میں) کوئی حرج نہیں۔” دوسری مسند میں سلیم کی جگہ سلیمان ہے۔ یہی روایت ابن الجوزی نے “الموضوعات” میں لکھی ہے۔ اور اس کی تہمت ولید بن سلمہ پر دھری ہے۔ حالانکہ ایسا نہیں جیسا ان کا گمان ہے۔ یہی روایت ابن مندہ نے دوسری سند سے مفہوماً نقل کی ہے۔ لیکن عمر (بن ابراہیم) ولید کے دور میں تھے۔ ابن مندہ نے ہی ایک اور سند سے عمر بن ابراہیم سے بواسطہ محمد بن اسحاق بن عبد اللہ ابن سلیم فرمایا اور اس میں یہ اضافہ “عبد اللہ” ان کے نسب میں نقل کیا، پھر اسی سند سے یہ حدیث “عبد اللہ” کے حالات میں درج کر دی۔ اور ابو القاسم بن مندہ نے اسے “کتاب الوصیہ” میں دو سندوں سے جو ولید بن سلمہ کے حوالہ سے ہیں نقل کیا ہے۔ اس میں ایک اور اختلاف بھی ہے جو محمد بن عبد اللہ بن سلیم بن اکیمہ کے حالات میں ان شاء اللہ تعالیٰ بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (ت: ۲۲۱۰) تجرید اسماء الصحابہ (۲۳۶/۱)\n(2) المعجم الکبیر (الحدیث: ۱۱۷/۷)"}],[3430,"§۳۴۳۶ ۔ سلیم بن ثابت(1)\nبن وقش انصاری۔ ابن کلبی نے ان کا ذکر کیا ہے کہ اُحد و خندق میں شریک ہوئے اور غزوہ خیبر میں شہید ہوئے۔ ابن شاہین نے ان کی روایت نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۱۲) استیعاب (۱۰۴۸)"}],[3431,"§۳۴۳۷ ۔ سلیم بن جابر(1)\nجابر بن سلیم میں تذکرہ ہوا ہے۔ ابن ابی الدنیا نے “اصطناع المعروف” میں بحوالہ سلیم بن جابر روایت کی ہے کہ میں نبی صلی اللہ علیہ وسلم کی خدمت اقدس میں حاضر ہوا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “کسی نیکی کو معمولی نہ سمجھنا۔۔۔۔” (الحدیث)(2) یہ وہی ابو جر بی ہیں جن کی حدیث جابر بن سلیم کے حالات میں درج ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۲۲۱۳) استیعاب (۱۰۴۹) تجرید (۲۳۶/۱)\n(2) مسلم کتاب البر والصلۃ باب استحباب طلاقۃ الوجہ عند اللقاء (۱۴۴) مسند احمد (۶۳/۵) المعجم الکبیر (۷۴/۷)"}],[3432,"§۳۴۳۸ ۔ سلیم بن حارث(1)\nبن ثعلبہ بن کعب بن عبد الاشہل بن حارثہ بن دینار بن النجار انصاری۔ ابن اسحاق نے بدری صحابہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۱۴) استیعاب (۱۰۵۰) تجرید (۲۸۶/۱)"}],[3433,"§۳۴۳۹ ۔ سلیم بن خلدہ\nابو عمر الزرقی۔ واقدی کی فتوح میں ان کا ذکر ہے۔ ابن عساکر نے اپنے طریق سے روایت کی ہے کہ جب سیدنا ابو بکر رضی اللہ عنہ نے شرحبیل ابن حسنہ کو شام بھیجا تو یہ ان کے علمبردار تھے۔"],[3434,"§۳۴۴۰ ۔ سلیم بن سعید الجشمی(1)\nابن السکن نے صحابہ میں ان کا ذکر کیا ہے۔ ان کے والد کے ساتھ بھی ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۱۶)"}],[3435,"§۳۴۴۱ ۔ سلیم بن عُش العذری(1)\nابن السکن اور باوردی کی روایت ہے کہ سلیم بن عش نے فرمایا: نبی صلی اللہ علیہ وسلم نے “صعید الفرع” میں واقع مسجد میں ہمیں نماز پڑھائی، ہم نے پتھروں سے آپ صلی اللہ علیہ وسلم کے لیے نماز کی جگہ بنائی۔ یہ وہی مقام ہے جہاں دیہاتی لوگ نماز کے لیے جمع ہوتے ہیں۔ ابن السکن کا قول ہے: اس کی سند مجہول ہے۔ زبیر بن بکار نے “اخبار مدینہ” میں بطریق سلیم بن مطین اسی سند سے ایک حدیث نقل کی ہے۔ ابن دباغ اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۰) تجرید (۲۳۶/۱)"}],[3436,"§۳۴۴۲ ۔ سلیم بن عبد العزیز\nبن عبید السلمی ابو شجرہ۔ ان کی والدہ خنساء شاعرہ ہیں۔ اپنی والدہ کے ساتھ ہی اسلام قبول کیا۔ پھر خلافت صدیقی میں مرتد ہو کر مسلمانوں سے جنگ کی۔ مبرد نے “الکامل” میں لکھا ہے کہ عرب کے بہادروں میں شمار ہوتے۔ ارتداد کے زمانہ میں ان کے قصیدے کا یہ مصرعہ زبان زد عام تھا: ط “اپنی قوم کی اکثریت کو وسیلہ بنانے والے، ان سے تیرا حصہ یہ ہے کہ تو ذلیل اور مقہور ہو۔ ہر سخت دن میں ہمارے بارے لوگوں سے پوچھ جب ہم دار عین اور حسرا میں لڑنے کے لیے ملے تھے۔ اسی میں وہ کہتے ہیں: ط “میں نے خالد کے لشکر سے اپنے نیزے کو سیراب کیا، اس کے بعد بھی مجھے لمبی عمر جیسے کی امید ہے۔” پھر مسلمان ہو کر سیدنا عمر رضی اللہ عنہ کے پاس آئے اور کہنے لگے: میں ابو شجرہ سلمی ہوں، مجھے کچھ عطا کیا جائے۔ آپ رضی اللہ عنہ نے فرمایا: تم وہی نہیں جس نے کہا تھا: “میں نے اپنے نیزے کو۔۔۔۔” پھر کوڑا اٹھایا ہی تھا کہ وہ بھاگ کر اپنی سواری پر چڑھ گئے، یوں نجات ہوئی۔ وہ کہتے ہیں: ط “ابو حفص نے اپنی داد و دہش میں ہم سے بخیلی کی اور ہر عاجز کے لیے ایک سکہ چاندی ہوتا ہے۔ وہ برابر مجھ پر کوڑے برساتے رہے لیکن میں بھاگ نکلا یہاں تک کہ میں اتنی دور نکل گیا کہ بعض لوگوں کے سامنے شام کی سرخی چھا گئی۔”"],[3437,"§۳۴۴۳ ۔ سلیم بن عقرب(1)(2)\nابن ابی حاتم نے بحوالہ اپنے والد ان کا ذکر کیا ہے کہ شرکاء بدر میں سے تھے، ان سے اہل علم کی روایت نہیں۔ ابو عمر نے ان کا ذکر کیا کہ بعض نے انہیں بدری صحابہ میں تعلیم میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۰) استیعاب (۱۰۵۲)\n(2) الجرح والتعدیل (۲۰۹/۴)"}],[3438,"§۳۴۴۴ ۔ سلیم بن عمرو(1)\nیا عامر بن حدیدہ بن عمرو بن غنم بن سواد بن غنم بن کعب بن سلمہ انصاری سلمی۔ بقول بعض: ان کا نام سلیمان، اہل بدر و عقبہ اور شہداء اُحد میں ان کا ذکر ملتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۲)"}],[3439,"§۳۴۴۵ ۔ سلیم بن قیس(1)\nبن فہد بن قیس بن ثعلبہ بن عبید بن ثعلبہ بن غنم بن مالک بن النجار انصاری۔ ابن کلبی نے شرکاء بدر میں ان کا ذکر کیا ہے اور بتایا ہے کہ فہد کا نام خالد تھا۔ ابن شاہین نے یہ بات نقل کی ہے اور ابو عمر(2) کا قول ہے: خلافت عثمانی میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۳) استیعاب (۱۰۵۴) تجرید (۲۳۷/۱)\n(2) استیعاب (۲۰۸/۲)"}],[3440,"§۳۴۴۶ ۔ سلیم بن قیس\nبن لوذان بن ثعلبہ انصاری۔ ابن جریر نے شرکاء اُحد میں ان کا ذکر کیا ہے۔ عدوی کا بیان ہے: کوفہ میں ان کی اولاد ہے۔ ابن دباغ نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[3441,"§۳۴۴۷ ۔ سلیم بن مخنف\nمخنف بن سلیم میں ذکر ہوگا۔"],[3442,"§۳۴۴۸ ۔ سلیم بن مالک العذری\nان کے بھائی سعید کے حالات میں ان کا ذکر ہوا ہے۔"],[3443,"§۳۴۴۹ ۔ سلیم بن ملحان انصاری(1)\nاپنے بھائی حرام کے ساتھ بئر معونہ کے واقعہ میں شہید ہوئے۔ ابن کلبی اور ابن شاہین کا بیان ہے: بدر و اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۴) استیعاب (۱۰۵۴) تجرید (۲۳۷/۱)"}],[3444,"§۳۴۵۰ ۔ سلیم انصاری(1)(2)\nمعاذ بن جبل کے خاندان سے ہیں۔ بقول بعض ان کے والد کا نام حارث ہے۔ امام احمد، طبرانی، بغوی اور طحاوی کی بطریق عمرو بن یحی مازنی بحوالہ معاذ بن رفاعہ زرقی روایت ہے کہ بنی سلمہ کا سلیم نامی شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا۔ عرض کی اللہ کے رسول صلی اللہ علیہ وسلم! ہم لوگ اپنے کاموں میں مشغول ہوتے ہیں، معاذ بن جبل رضی اللہ عنہ آکر ہمیں لمبی نماز پڑھاتے ہیں۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: “معاذ! لوگوں کو ہرگز فتنے میں نہ ڈالنا۔” پھر فرمایا: “سلیم! تمہیں کتنا قرآن یاد ہے؟” (حدیث)(3) اسی میں ہے سلیم اُحد میں نکلے اور شہید ہوئے۔ اسی روایت کو بغوی، احمد اور ابن مندہ نے دوسری سند سے بحوالہ عمرو بن یحی نقل کیا ہے کہ معاذ بن رفاعہ بواسطہ سلیم روایت کرتے ہیں، یوں انہوں نے اس حدیث کو ان کی سند سے شمار کیا ہے جبکہ یہ منقطع ہے۔ کیونکہ معاذ بن رفاعہ نے ان کا دور نہیں پایا۔ پہلی سند اگرچہ مرسل ہے لیکن صحیح ہے۔ ابن مندہ کا گمان ہے کہ اس واقعہ والے وہی ہیں جن کا تذکرہ سلیمان بن حارث میں ہوا ہے کہ ابن اسحاق(4) کا بیان ہے کہ بدر میں شریک اور اُحد میں شہید ہوئے۔ ابن عبد البر نے دونوں میں فرق کیا ہے، بظاہر یہی درست ہے۔ کیونکہ وہ بنی دینار بن نجار سے تعلق رکھتے ہیں اور خزرجی ہیں۔ جبکہ یہ سعد بن معاذ رضی اللہ عنہ کے خاندان سے ہیں اور معاذ بن جبل اور اوسی ہیں۔ رہا خطیب کا یہ اعتماد کہ “معاذ بن جبل رضی اللہ عنہ والے شخص کا نام سلیم بن حارث ہے”۔ اس سے ایک ہونے کا پتہ نہیں چلتا۔ اس واسطے کہ اس میں کوئی ممانعت نہیں کہ باپ کے نام میں اشتراک ہو جیسے بیٹے کا نام مشترک ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۲۲۲۶) استیعاب (۱۰۵۶)\n(2) اسد الغابہ (۲۲۱۱) استیعاب (۱۰۵۷)\n(3) ابوداؤد کتاب الصلاۃ باب فی تخفیف الصلاۃ (۷۹۱) مسند احمد (۷۴/۵) السنن الکبریٰ (۱۱۷/۳) التاریخ الکبیر (۱۱۰/۳) کنز العمال (۲۰۴۲۷)\n(4) السیرۃ النبویۃ (۲۶۳/۲)"}],[3445,"§۳۴۵۱ ۔ سلیم العذری(1)\nابن ابی حاتم بحوالہ اپنے والد روایت کرتے ہیں کہ بنی عذرہ کے وفد میں نبی صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کیا۔ یہ بارہ شخص تھے۔ ابن مندہ نے واقدی کی سند سے بواسطہ حریث بن سلیم عذری وہ بحوالہ اپنے والد روایت کرتے ہیں کہ میں نے ان لوگوں کے متعلق پوچھا جو (ایک گھرانے کے) قیدیوں میں جدائی کر دیتے ہیں۔ آپ نے فرمایا: “جس نے باپ بیٹے میں جدائی ڈالی اللہ تعالیٰ قیامت کے دن اس میں اور اس کے دوستوں میں جدائی پیدا کر دے گا۔”(2) محملا سلیم بن مالک اور سلیم بن عُش کا تذکرہ ہو چکا ہے، مجھے معلوم نہیں آیا یہ ان میں سے ایک ہیں یا تیسرے۔","",{"fn":"(1) اسد الغابہ (۲۲۱۵) استیعاب (۱۰۵۹)\n(2) ترمذی کتاب البیوع باب ما جاء فی کراهیۃ الفرق بین الاخوین (۱۲۸۳)"}],[3446,"§۳۴۵۲ ۔ سلیم السلمی(1)\nابو عمر(2) نے ان کا ذکر کیا ہے، ان سے ابو العلاء بن الشخیر روایت کرتے ہیں۔","",{"fn":"(1) المستدرک (۵۵/۲) المعجم الکبیر (۲۱۷/۴) جامع المسانید (۵۲۰/۵)\n(2) استیعاب (۱۰۵۸) اسد الغابہ (۲۱۰/۲)"}],[3447,"§۳۴۵۳ ۔ سلیم (مولا عمرو بن الجموح)(1)\nابن المبارک کی کتاب الجہاد میں حدیث ابن عباس رضی اللہ عنہما میں سے ان کا ذکر ملتا ہے۔ فرمایا کہ عمرو بن جموح بہت بوڑھے اور لنگڑے شخص تھے۔ پھر اُحد میں ان کی شرکت کی حدیث ذکر کی۔ کہ ان کے ساتھ ان کا غلام تھا جس کا نام سلیم تھا۔ آپ نے اس سے فرمایا: تم اپنے گھر لوٹ جاؤ تو اس نے کہا: کیا میں آپ کے ساتھ آج کی بھلائی میں شریک نہ ہوں۔ پھر وہ غلام آگے بڑھا اور لڑ کر شہید ہو گیا۔ اسے ابو موسیٰ نے اور حاکم نے “الاکلیل” میں حدیث ابن المبارک سے طویل نقل کیا ہے۔ ظاہری سیاق سے پتہ چلتا ہے یہ مرسل ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۱)"}],[3448,"§۳۴۵۴ ۔ سلیم(2)\nبنی حارث بن سعد کے ایک فرد ہیں۔ ابن السکن نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے: جب رسول اللہ صلی اللہ علیہ وسلم تبوک آئے تو اپنے ہاتھ سے اشارہ کرتے ہوئے فرمایا: “ایمان تو یمنی ہے جبکہ دلوں کی سختی کسانوں اور خیمہ والوں میں ہے۔”(1) ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، شاید یہ سلیم بن مالک عذری ہیں، کیونکہ بنی حارث بن سعد کا تعلق بنی عذرہ سے ہے۔","",{"fn":"(1) المعجم الکبیر (۲۱۲/۱۷)\n(2) استیعاب (۱۰۵۵) تجرید (۲۳۷/۱)"}],[3449,"§۳۴۵۵ ۔ سلیم (بے نسبت)\nوہی ابو کبشہ ہیں، کنیتوں میں تذکرہ ہوگا۔"],[3450,"§۳۴۵۶ ۔ سلیمان بن اکیمہ\nسلیم میں ذکر ہوا۔"],[3451,"§۳۴۵۷ ۔ سلیمان بن ابی حثمہ\nقسم ثانی میں ذکر ہوگا۔"],[3452,"§۳۴۵۸ ۔ سلیمان بن صرد(1)(2)\nبن جون بن ابی الجون بن منقذ بن ربیعہ بن اصرم بن نفیس بن حرام بن حبیثہ بن سلول بن کعب، ابو المطرف خزاعی۔ بقول بعض: نام یسار تھا جو نبی صلی اللہ علیہ وسلم نے تبدیل کر دیا۔ انھوں نے(3) نبی صلی اللہ علیہ وسلم، سیدنا علی رضی اللہ عنہ، ابو الحسین اور جبیر بن مطعم رضی اللہ عنہما سے روایت کی ہے۔ جبکہ ان سے ابو اسحاق سبیعی، یحی بن یعمر، عبد اللہ بن سیار اور ابو الضحی روایت کرتے ہیں۔ وہ صاحب خیر اور فضیلت والے انسان تھے۔ صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا اور حوشب کو مبارزت میں قتل کیا۔ پھر ان لوگوں میں شامل ہو گئے جنہوں نے سیدنا حسین رضی اللہ عنہ سے خط و کتابت کی لیکن بعد میں ان کا ساتھ نہ دیا۔ اس کے بعد وہ اور مسیب بن نجبہ دوسرے لوگوں کے ساتھ آپ کے خون کا مطالبہ کرنے نکلے، ان لوگوں کی تعداد چار ہزار تھی۔ عبید اللہ بن زیاد سے مروان کے لشکر سمیت “عین الوردہ” پر بیڈ بھیٹر ہوئی، سلیمان اور ان کے ساتھی قتل ہوئے۔ یہ ربیع الثانی پینسٹھ (۶۵ھ) کا واقعہ ہے۔ قتل کے وقت سلیمان کی عمر ترانوے(۹۳) سال تھی۔ سلیمان کو یزید بن الحصین بن نمیر نے ایک تیر مارا تھا، جس سے فوت ہو گئے۔ پھر ان کا اور مسیب بن نجبہ کا سر مروان کے پاس بھیج دیا۔","",{"fn":"(1) اسد الغابہ (۲۲۳۰) استیعاب (۱۰۶۱)\n(2) استیعاب (۱۰۶۰) تجرید (۲۳۷/۱)\n(3) جامع المسانید (۵۱۲/۵)"}],[3453,"§۳۴۵۹ ۔ سلیمان بن عمرو الزرقی\nبقول ابن حبان صحابی ہیں۔(1) اور باوردی کی بطریق ابن لہیعہ بحوالہ سلیمان بن عمرو زرقی روایت ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں حضر موت اور کندہ کی جانب بھیجا تھا۔","",{"fn":"(1) الثقات (۱۶۲/۳)"}],[3454,"§۳۴۶۰ ۔ سلیمان بن عمرو بن حدیدہ(1)\nسلیم میں ذکر ہوا ہے۔","",{"fn":"(1) استیعاب (۱۰۶۲)"}],[3455,"§۳۴۶۱ ۔ سلیمان بن ابی سلیمان الشامی(1)\nبقول ابو حاتم(2) انہیں شرف صحابیت حاصل ہے۔ بغوی کی روایت ہے کہ سلیمان نے فرمایا: ایک دفعہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس بیٹھا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: “عنقریب تم لوگ لشکر تیار کرو گے، لوگ تمہارے ذمی اور باج گزار ہوں گے اور اللہ تمہیں ایک زمین عطا کرے گا”۔ (حدیث)(3) ابن ابی حاتم لکھتے ہیں: ابو زرعہ نے مسند شامین میں ان کا نام درج کیا ہے۔ جبکہ بغوی کا قول ہے: مجھے اس سند سے صرف اسی حدیث کا پتہ ہے۔ یہی روایت ابو حاتم نے “الوحدان” میں لکھی ہے کہ صحابی رسول صلی اللہ علیہ وسلم یہ سلیمان سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۹) استیعاب (۱۰۶۳) تجرید (۲۳۷/۱)\n(2) الجرح والتعدیل (۱۲۲/۴)\n(3) دلائل النبوۃ للبیہقی (۳۲۵/۶) کنز العمال (۳۱۸۰۷، ۳۸۱۹۶)"}],[3456,"§۳۴۶۲ ۔ سلیمان السلمی\nابو الحدید۔ میں نے اپنے شیخ الشیوخ قطب حلبی کے قلب سے تاریخ مصر میں لکھا دیکھا کہ سلیمان سلمی صحابی رسول صلی اللہ علیہ وسلم ہیں۔ علماء مصر میں سے کسی نے کہا کہ جب وہ مصر آئے تو ان سے ملاقات کی۔ میں نے ان کے پاس نبی صلی اللہ علیہ وسلم کی نعل (جوتے) کا ایک تسمہ دیکھا جو انہیں اپنے مذکورہ آباء و اجداد سے وراثت میں ملا ہے۔ یہ چھ سو پچیس (۶۲۵ھ) میں بلا ورث فوت ہوئے تو اشرف بن عادل نے ان کا سامان جو بہت زیادہ تھا سارا مدرسہ اشرفیہ دمشق کے اوقاف میں جمع کرا دیا۔ میں کہتا ہوں: اس میں مذکور فعل بھی تھا جس کا ذہبی وغیرہ نے ذکر کیا ہے جسے لوگ “اثر شریف” سے تعبیر کرتے ہیں۔ یہی اس کی اصل ہے۔ احمد بن عثمان کے جد امجد محمد بن احمد بن عثمان بن ابی الحدید مشہور محدث ہوئے ہیں۔ ابن عساکر نے تاریخ دمشق میں ان کا ذکر کیا ہے۔"],[3457,"§۳۴۶۳ ۔ سماک\nبن اوس بن خرشہ ابو دجانہ - کنیتوں میں تذکرہ ہوگا۔ اکثر اوس کے حذف سے ہی ان کا ذکر کرتے ہیں۔"],[3458,"§۳۴۶۴ ۔ سماک بن ثابت(1)\nبن سفیان، ان کے والد ثابت کے حالات میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) التاریخ الکبیر (۳۳/۵)"}],[3459,"§۳۴۶۵ ۔ سماک بن حارث(1)(2)\nبن ثابت خزرجی۔ ابن ابی حاتم(3) نے صحابہ میں ان کا ذکر کیا ہے۔ جبکہ مشہور سابقہ ہیں۔ ان کا حارث بن ثابت بن سفیان نامی ایک بھائی ہے۔ شاید اس سے آگے اختلاف ہو۔","",{"fn":"(1) استیعاب (۱۰۶۴)\n(2) اسد الغابہ (۲۲۳۴) استیعاب (۱۰۶۴)\n(3) الجرح والتعدیل (۲۷۸/۴)"}],[3460,"§۳۴۶۶ ۔ سماک بن خرشہ انصاری (دوسرے)(1)\nابو دجانہ کے علاوہ ہیں۔ “فتوح” میں سیف نے لکھا ہے: سماک بن مخرمہ اسدی، سماک بن عبد عبسی اور سماک بن خرشہ انصاری جو ابو دجانہ نہیں۔ یہ تینوں سب سے پہلے ہمدان کے علاقہ دستبا (جو دیلم کا ایک شہر ہے اس کی اسلحہ فیکٹری کے ذمہ دار بنے۔ اور یہی تینوں سیدنا عمر رضی اللہ عنہ کے پاس اہل کوفہ کے وفد میں خمس لے کر آئے۔ اپنا نسب بیان کیا تو آپ نے فرمایا: اللہ! انہیں برکت دے اور ان کے ذریعہ اسلام کو سر بلندی عطا فرما۔ سیف ہی نے ذکر کیا ہے کہ سماک بن خرشہ جنگ قادسیہ میں شریک ہوئے۔ ابن فتحون کا قول ہے کہ ابن عبد البر نے لکھا ہے کہ ابو دجانہ صفین میں شریک ہوئے، جبکہ ابو دجانہ صفین میں نہیں شریک ہوئے۔(2) شاید اس سے انہیں شبہ ہو گیا ہے۔ ان حضرات کا اس قسم میں، میں نے اس لیے ذکر کیا ہے کیونکہ اس دور کی فتوحات میں صرف صحابہ کو امیر و ذمہ دار بنائے جاتے تھے۔ ابن مسکویہ کا قول ہے: سماک بن خرشہ۔ جو ابو دجانہ نہیں۔ کاری کی فتوحات میں ذکر ملتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۳۵) استیعاب (۱۰۶۵)\n(2) المستدرک (۲۳۰/۳) استیعاب (۲۱۲/۲)"}],[3461,"§۳۴۶۷ ۔ سماک بن سعد بن ثعلبہ انصاری(1)\nبن ثعلبہ انصاری۔ نعمان بن بشیر کے چچا۔ موسیٰ بن عقبہ اور ابن اسحاق نے شرکاء بدر و احد میں ان کا ذکر کیا ہے۔ ان کی نرینہ اولاد نہ تھی۔ ابن ابی حاتم کا قول ہے: مجھے ان کی کسی روایت کا علم نہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۳۶) استیعاب (۱۰۶۶) تجرید (۲۳۸/۱)"}],[3462,"§۳۴۶۸ ۔ سماک بن عبد عیسیٰ\nایک عنوان پہلے ان کا ذکر ہوا ہے۔ فتوح ہمدان میں بھی ان کا ذکر ہے۔ انہوں نے ہی دینار فارسی کو قید کیا تھا جو آٹھ آدمیوں کے ساتھ تھا۔ سماک بن عبید نے انہیں قتل کر کے دینار کو سیدنا حذیفہ کے سامنے پیش کر دیا۔ آپ نے ان سے صلح کا معاملہ کر لیا۔ دینار خلافت معاویہ کے اخیر تک زندہ رہا۔ اہل کوفہ کے ساتھ اس کا ایک واقعہ بھی ہے۔ مجھے دینار کے مسلمان ہونے کی وضاحت نہیں ملی۔"],[3463,"§۳۴۶۹ ۔ سماک بن مخرمہ(1)\nبن حمیر بن ثابت اسدی۔ اسد خزیمہ۔ ان کا ذکر بھی ہوا۔ حمزہ بن یوسف نے تاریخ جرجان میں جرجان آنے والے صحابہ میں ان کا ذکر کیا ہے۔ بقول ابن ابی حاتم(2) کوفہ کی مسجد سماک انہی کی نسبت سے مشہور ہے۔ یہ سماک بن حرب کے ماموں ہیں۔ ان کا نام انہی کے نام پر رکھا گیا تھا۔ بقول ابو عمر صحابی ہیں۔ ابن معین سے مروی ہے: صحابہ میں سے ہیں۔ عبید بن عمرو الرقی کا قول ہے: بقول بعض: رقہ میں فوت ہوئے۔ ایک قول ہے: خلافت معاویہ تک زندہ رہے۔ ابن عساکر نے سماک بن مخرمہ کا امیر معاویہ سے پیش آمدہ ایک واقعہ نقل کیا ہے۔ جس میں امیر معاویہ فرماتے ہیں: اگر تمہاری طرف سے بالشت بھر بھی بغاوت ہوتی تو ہماری طرف سے ایک باع (دونوں کھلے بازوؤں کی لمبائی) اس کی سزا بھیجی جاتی۔ لیکن ان کا نسب تمیمی بیان کیا ہے، شاید یہ اور ہوں۔","",{"fn":"(1) اسد الغابہ (۲۲۳۷) استیعاب (۱۰۶۷) تجرید (۲۳۸/۱)\n(2) الجرح والتعدیل (۲۰۹/۴)"}],[3464,"§۳۴۷۰ ۔ سماک بن نعمان\nبن قیس بن عمرو بن زید بن امیہ انصاری۔ بقول طبری: یہ اور ان کے بھائی فضالہ غزوہ اُحد میں شریک ہوئے۔"],[3465,"§۳۴۷۱ ۔ سماک الخیبری\nواقدی کا بیان ہے سیدنا عمر رضی اللہ عنہ نے خیبر کے روز انہیں گرفتار کیا، جب مسلمانوں نے نطاۃ کو فتح کیا تھا۔ گردن زدنی کے لیے انہیں پیش کیا تو وہ کہنے لگے: مجھے ابو القاسم تک پہنچا دو، چنانچہ وہاں پہنچایا گیا تو ان کے خفیہ ٹھکانوں کی اطلاع دی، پھر سماک مسلمان ہو گئے۔ اور نبی صلی اللہ علیہ وسلم سے اپنی بیوی نقیبہ کا مطالبہ کیا تو آپ صلی اللہ علیہ وسلم نے انہیں ہبہ کر دی اور خیبر سے چلے گئے۔ اس کے بعد سے خیبر واپس نہیں آئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا اور رشاطی نے خیبری حضرات میں ان کا تذکرہ کیا ہے۔"],[3466,"§۳۴۷۲ ۔ سمالی بن ھزال(1)\nعسکری نے “الافراد” میں ان کا ذکر کیا ہے اور ابو موسیٰ نے بحوالہ زید بن اسلم روایت نقل کی ہے کہ سمالی بن ھزال نے نبی صلی اللہ علیہ وسلم کے پاس زنا کا اقرار کیا تو آپ صلی اللہ علیہ وسلم نے انہیں رجم کیے جانے کا حکم دیا تو انہیں سنگسار کر دیا گیا۔ ابو موسیٰ فرماتے ہیں: یہ واقعہ تو ماعز بن مالک رضی اللہ عنہ کا انزال کے ساتھ مشہور ہے، جیسا کہ بیان ہوگا۔ شاید اس میں لفظی غلطی ہو گئی ہے۔ میں کہتا ہوں: اس کا احتمال ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۳۸)"}],[3467,"§۳۴۷۳ ۔ سَمْحَجُ (بروزن أَحْمَرُ) الجنّی\nکتاب مکہ میں فاکہی نے حدیث ابن عباس رضی اللہ عنہما سے بحوالہ عامر بن ربیعہ لکھا ہے کہ ایک دفعہ اسلام کے ابتدائی دور میں ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مکہ میں تھے کہ اچانک مکہ کے کسی پہاڑ سے غائبانہ آواز آئی جو مسلمانوں کے خلاف کسی کو بڑھکا رہا تھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: “یہ ایک شیطان ہے جو شیطان بھی کسی نبی کے خلاف بڑھکاتا ہے اللہ تعالیٰ اسے ہلاک کر دیتا ہے”۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے ہمیں فرمایا: “اللہ تعالیٰ نے ایک سرکش جن کے ہاتھوں اسے قتل کر دیا ہے جس کا نام سمحج ہے، میں نے اس کا نام عبد اللہ رکھ دیا ہے”۔ جب شام کا وقت ہوا تو ہمیں اسی جگہ سے ایک غیبی آواز سنائی دی: ط “ہم نے مسعر کو مار ڈالا، جب اس نے تکبر اور سرکشی کی، حق کو حقیر سمجھا اور برائی کی طرح ڈالی، اس نے ہمارے کامیاب نبی کو برا بھلا کہا تھا جس کے عوض ہم نے اس کا کام تمام کر دیا۔” اور عبد الرحمن بن عوف رضی اللہ عنہ سے مروی ہے، جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں نبی بن کے ظاہر ہوئے تو ایک جن مسعر نامی نے غائبانہ آواز سے آپ کے خلاف بڑھکایا، قریش ٹوٹ پڑے اور ان کی اذیت سخت ہو گئی۔ آئندہ رات ہوئی تو اس کی جگہ دوسرا جن سمحج نامی کھڑا ہوا، اس نے بھی ایسا ہی کلام کیا، پھر اس کا مفہوم ذکر کیا۔"],[3468,"§۳۴۷۴ ۔ سَمْحَج(1)\nبقول بعض: سمحج الجنی۔ مجھے معلوم نہیں یہ پہلے والے ہیں یا اور ہیں۔ “الافراد” میں دارقطنی نے بحوالہ ابو موسیٰ لکھا ہے: “ہم نے ان کے اتباع میں ان کا ذکر کیا ہے۔ کیونکہ آپ صلی اللہ علیہ وسلم کی طرف انسانوں اور جنوں کی طرف مبعوث ہوئے ہیں”(2)۔ میں کہتا ہوں: شیرازی نے “الالقاب” میں ان کا ذکر کیا ہے اور طبرانی نے “الکبیر” میں بحوالہ عبد اللہ بن حسین روایت کی ہے کہ جب میں طرسوس پہنچا تو کسی نے مجھے بتایا یہاں ایک عورت رہتی ہے جس نے ان جنات کو دیکھا ہے جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تھے۔ میں اس کے پاس گیا تو وہاں ایک عورت تھی جو چت لیٹی ہوئی تھی، اس کے پاس لوگوں کا ایک مجمع تھا۔ میں نے اس سے پوچھا: بی! آپ کا کیا نام ہے؟ وہ کہنے لگے: منوسہ۔ میں نے کہا: آپ نے ان جنوں میں سے کسی کو دیکھا ہے جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تھے؟ اس نے کہا: ہاں! مجھ سے سمحج نے بیان کیا جن کا نام عبد اللہ تھا کہ میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! زمین و آسمان کو پیدا کرنے سے پہلے ہمارا رب کہاں تھا؟ فرمایا: “نور کی ایک مچھلی پر جو نور میں تیرتی ہے”۔ میں کہتا ہوں: عبد اللہ بن حسین جو طبرانی کے شیوخ میں شامل ہیں، ابن حبان نے کتاب الضعفاء میں ان کا ذکر کیا ہے کہ وہ احادیث کو الٹ پلٹ کر چراتے تھے کسی روایت میں جب وہ اکیلے ہوں تو اس کو بطور دلیل پیش کرنا جائز نہیں۔ پھر احمد بن مجاہد سے بحوالہ ان کے انہی کی روایت سے دو حدیثیں محمد بن المبارک سے نقل کی ہیں۔ فرماتے ہیں: ان کا ایک نسخہ ہے جس کی اکثر احادیث تبدیل ہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۳۹)\n(2) جامع المسانید (۵۲۱/۵)"}],[3469,"§۳۴۷۵ ۔ سمرہ بن جنادہ(1)\nبن جندب بن بشیر بن زباب بن سواءہ سوائی، جابر کے والد۔ دونوں صحابی ہیں۔ حدیث سمرہ ان کے والد کی روایت سے مسلم میں ہے۔(2) ابن مندہ کو ان کے نسب میں غلطی لگی ہے۔ چنانچہ وہ لکھتے ہیں: “سمرہ بن جنادہ بن حجر بن زیاد”۔ یوں جندب کا نام ساقط کر دیا، اور جیر کو حجر بنا دیا اور زباب کو زیاد لکھ دیا۔ ابن سعد(3) فرماتے ہیں: فتح کے روز اسلام لائے۔ اور خطیب کا قول ہے: مدائن سیدنا سعد بن ابی وقاص رضی اللہ عنہ کے ساتھ تھے، سیدنا سعد کی ہمشیرہ سے شادی کر لی پھر کوفہ فروکش ہوئے۔ ابن حبان(4) اور ابن منجویہ کا قول ہے: عبد الملک کی حکومت میں کوفہ میں فوت ہوئے اور ذہبی کے قلم سے میں نے پڑھا ہے: عبد الملک کے دور میں فوت ہونے والے ان کے بیٹے جابر تھے، جبکہ سمرہ بہت پہلے فوت ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۰) تجرید (۲۳۹/۱)\n(2) مسلم کتاب الفتن، باب لا تقوم الساعۃ حتى يمر الرجل بقبر الرجل (۷۲۶۹)\n(3) الطبقات (۱۴/۶)\n(4) الثقات (۱۷۵/۳)"}],[3470,"§۳۴۷۶ ۔ سمرہ بن جندب(1)\nبن ہلال بن حریج بن مرہ بن حزن بن عمرو بن جابر بن خشین بن لای بن نصیم بن فزارہ فزاری۔ کنیت ابو سلیمان تھی۔ ابن اسحاق کا قول ہے: انصار کے حلیف تھے۔ ان کی والدہ ان کے والد کی وفات کے بعد انہیں لے آئی تھیں، پھر انصار کے کسی شخص نے ان سے شادی کر لی تھی۔ رسول اللہ صلی اللہ علیہ وسلم کے سامنے انصار کے بچے آئے، آپ کے پاس سے ایک لڑکا گزرا جسے آپ نے غزوہ میں شرکت کی اجازت دے دی۔ سمرہ پیش ہوئے تو آپ نے انہیں واپس کر دیا، جس پر سمرہ عرض کرنے لگے: آپ نے اسے اجازت دے دی اور مجھے واپس کر دیا، اگر میں اس سے کشتی لڑوں تو اسے پچھاڑ لوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “مقابلہ کر کے دیکھ لو”۔ چنانچہ سمرہ نے اسے پچھاڑ لیا۔ یوں آپ صلی اللہ علیہ وسلم نے انہیں بھی شرکت کی اجازت دے دی۔ عبد اللہ بن بریدہ بحوالہ سیدنا سمرہ رضی اللہ عنہ روایت کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے عہد میں لڑکا تھا، پھر بھی مجھے آپ صلی اللہ علیہ وسلم کی باتیں یاد ہو جاتیں۔ سمرہ بصرہ فروکش ہوئے۔ زیاد جب کوفہ جاتا تو انہیں اپنا نائب(2) بنا کر جاتا۔ وہ خوارج کے بڑے مخالف تھے۔ وہ ان پر طعن کرتے، جبکہ حسن بصری اور ابن سیرین ان کی تعریف کرتے۔ ابن سیرین فرماتے ہیں: سمرہ نے جو خط اپنے بیٹوں کو بھیجا اس میں بڑا علم ہے۔ ان سے ابو رجاء عطاردی، شعبی، ابن ابی لیلی، مطرف بن مخیر اور عبد اللہ بن سلیمان وغیرہ روایت کرتے ہیں۔ ساٹھ (۶۰ھ) سے پہلے انتقال ہوا۔ انتقال کا سبب ابن عبد البر نے یہ لکھا ہے کہ گرم پانی کی بھری دیگ میں گرے تھے جو حقیقت میں نبی صلی اللہ علیہ وسلم کے ارشاد کی تصدیق تھی جو آپ صلی اللہ علیہ وسلم نے ان سے ابو ہریرہ اور ابو محذورہ رضی اللہ عنہما سے فرمایا تھا: “تم میں سے آخری شخص آگ میں جل کر مرے گا”۔(3) بقول بعض: اٹھاون (۵۸ھ) یا انسٹھ (۵۹ھ) ایک قول ہے ساٹھ (۶۰ھ) کے آغاز میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۱) استیعاب (۱۰۶۸)\n(2) المستدرک (۱۴۹/۲) السنن الکبری (۱۸۸/۸)\n(3) مجمع الزوائد (۵۱۴/۸) المعجم الکبیر (۲۱۱/۷) علل الحدیث لابن ابی حاتم (۱۰۳۷)"}],[3471,"§۳۴۷۷ ۔ سمرہ بن حبیب(1)\nبن عبد شمس العبشمی۔ “الجمہرہ” میں ابن حزم نے لکھا ہے، بقول بعض: آغاز اسلام میں اسلام قبول کیا اور بہت عرصہ پہلے فوت ہو گئے۔ ابن الدباغ نے بحوالہ ابن داستہ نقل کیا ہے کہ وہ اسلام لائے تھے اور سیدنا عثمان رضی اللہ عنہ نے انہیں کسی عہدے پر فائز کیا تھا۔ اس کا تقاضا یہ ہے کہ وہ خلافت عثمانی تک حیات رہے ہوں، حالانکہ ایسا نہیں۔ واقعہ یہ ہے کہ سیدنا عثمان رضی اللہ عنہ نے ان کے بیٹے عبد الرحمن بن سمرہ کو کوئی عہدہ دیا تھا۔ ابن قانع بطریق شعبی بواسطہ عبد الرحمن بن سمرہ انہوں نے بحوالہ اپنے والد روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم وتروں میں سبح اسم، قُلْ يَا أَيُّهَا الْكَافِرُونَ اور قُلْ هُوَ اللهُ اَحَدٌ پڑھا کرتے تھے۔ ابن قانع لکھتے ہیں: انہوں نے بحوالہ ان کے والد اسی طرح کہا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۲)"}],[3472,"§۳۴۷۸ ۔ سمرہ بن ربیعہ العدوانی(1)\nبقول بعض: العدوی ابن مندہ کی روایت ہے کہ سمرہ بن ربیعہ العدوانی ابو الیسر سے اپنا حق مانگنے آئے تو ابو الیسر نے گھر والوں سے کہا: ان سے کہو وہ یہاں نہیں ہیں۔(2) تو سمرہ تیز تیز چلنے لگے، ابو الیسر سمجھے وہ چلے گئے ہیں۔ اپنا سر باہر نکال کر جھانکا تو سمرہ نے انہیں دیکھ لیا، ابو الیسر فورا بولے: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کی تعلیم کو فرماتے ہوئے نہیں سنا: “جو تنگدست (مقروض) کو مہلت دے گا اللہ تعالیٰ اسے اپنے (عرش کے) سائے میں جگہ دے گا”۔ (حدیث) تو سمرہ نے کہا: میں گواہی دیتا ہوں ہاں میں نے آپ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے۔ میں کہتا ہوں: اس واقعہ کی اصل مسلم میں بغیر اس سیاق کے ہے اور نہ اس میں سمرہ ہی کا ذکر ہے، بلکہ اس میں ہے ابو الیسر کا ایک اور شخص کے ذمہ قرض تھا۔ اس کے متعلق حارث بن یزید کے حالات میں کچھ تفصیل گزر چکی ہے اور حرام بن عثمان متروک راوی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۳) استیعاب (۱۰۷۱) تجرید (۲۳۹/۱)\n(2) مسلم کتاب الزهد باب حدیث جابر الطویل و قصۃ ابی الیسر (۷۴۳۷) المعجم الکبیر (۱۶۶/۱۹) السنن الکبریٰ (۳۵۷/۵)"}],[3473,"§۳۴۷۹ ۔ سمرہ بن عمرو(1)\nبن قرط العنبری۔ حبیب بن عدی بن العنبر بن تمیم کی اولاد سے، کئی احادیث میں ان کا ذکر ملتا ہے۔ سنن ابی داؤد میں ہے کہ نبی صلی اللہ علیہ وسلم نے ایک لشکر بنی عنبر کی طرف بھیجا جس نے انہیں گرفتار کر لیا۔ - (حدیث) اس میں ہے: “کیا تمہارے پاس گرفتاری سے پہلے مسلمان ہونے کی کوئی دلیل ہے؟ انہوں نے کہا: سمرہ بنی عنبر کا ہے ایک اور شخص بغوی کی روایت میں ہے، انہوں نے کہا: سمرہ بن عمرو۔ سیف نے “الفتوح” میں لکھا ہے کہ خالد بن ولید رضی اللہ عنہ نے سمرہ بن عمرو بن قرط کو یمامہ فتح کرنے کے بعد اس کا گورنر بنا دیا۔ ابن الاعرابی کا بیان ہے کہ سیدنا عثمان رضی اللہ عنہ نے سمرہ کو گمشدہ اونٹوں کی نگرانی پر مقرر کیا۔ چنانچہ جو نہی انہیں کسی گمشدہ اونٹ کی خبر ملتی اسے پکڑ کر اس کا اعلان کرنے لگتے۔ پھر ایسا ہونے لگا جس کی کوئی اوٹنی وغیرہ گم ہوتی تو وہ سمرہ کے پاس آکر پوچھتا۔ ایک دفعہ ایسا ہوا کہ انہیں اطلاع ملی کہ بنی دلیل کی ایک اونٹنی گم ہوگئی ہے، وہاں آئے تو سوائے ایک بڑھیا کے کوئی نہ تھا جو ان کی والدہ تھی جس کا نام لیلیٰ بنت شداد بن اوس تھا۔ اس کے بعد ایک واقعہ نقل کیا۔ جب کمیم بن وثیل اپنی والدہ کے پاس آیا تو اس نے سارا واقعہ سنایا تو اس وقت خاموش ہو گیا پھر موقعہ پا کر عبید بن غافرہ بن سمرہ سے ملا، اسے پچھاڑ کر اس کا منہ کوٹ دیا۔ سمرہ نے اس کے خلاف سیدنا عثمان رضی اللہ عنہ سے استدعا کی تو آپ نے اسے قید کروا دیا۔ ان کے بیٹے غافرہ بن سمرہ کا تذکرہ ان شاء اللہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۵)"}],[3474,"§۳۴۸۰ ۔ سمرہ بن فاتک(1)\nبقول بعض: ابن فاتکہ الاسدی۔ ایک قول ہے: ان کا نام سبرہ ہے۔ امام احمد، بغوی، حسن بن سفیان، ابن مندہ اور امام بخاری نے اپنی تاریخ(2) میں بطریق بشر بن عبید اللہ بحوالہ سمرہ بن فاتکہ اسدی روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “سمرہ کیا ہی اچھا آدمی ہے، اگر اپنے لمبے بال کچھ کم کرلے اور اپنا تہبند اڑس لئے”۔ انہیں اس کی اطلاع ملی تو ایسا ہی کیا۔ “الجہاد” میں اسی سند سے ابن المبارک بحوالہ سمرہ ایک اور موقوف حدیث نقل کرتے ہیں جس میں ہے مجھے اس کی خواہش ہے کہ ہر دن کسی مشرک سے میرا مقابلہ ہو جس نے زرہ پہن رکھی ہو، اگر وہ مجھے شہید کر دے تو فبہا اور اگر میں اسے موت کے گھاٹ اتار دوں تو پھر اسی جیسا میرے مقابلہ میں آجائے۔ ابن عساکر نے یہی “متن” سمرہ بن فاتک کے حالات میں نقل کیا ہے۔ جہاں تک مجھے لگتا ہے وہ اور ہیں۔ چنانچہ امام بخاری رحمہ اللہ نے اپنی تاریخ(3) میں دونوں شخصوں میں فرق کیا ہے۔ ان کے متعلق لکھتے ہیں: انہیں شرف صحابیت حاصل ہے اور اہل شام سے ان کی حدیث منقول ہے پھر ان کی یہ حدیث روایت کی، جبکہ سبرہ کے سوانح میں حدیث جبیر بن نفیر بحوالہ ان کے بیان کی ہے جو ان کے حالات میں گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۶)\n(2) التاریخ الکبیر (۱۷۷/۲) مسند احمد (۲۰۰/۴) الکامل فی الضعفاء (۱۷۷/۲)\n(3) التاریخ الکبیر (۱۷۷/۲)"}],[3475,"§۳۴۸۱ ۔ سمرہ بن معاویہ(1)\nبن عمرو بن سلمہ بن ابی کرب بن ربیعہ الکندی۔ ابن شاہین کا بیان ہے: انہیں آنے کی سعادت حاصل ہے۔ ان کے پردادا سلمہ کو “المجر” کہا جاتا ہے۔ ابن کلبی کا بیان ہے: کیونکہ انہوں نے ایک شخص کو نیزہ مار کر کھینچا تھا یعنی اس کے حلق تک اتر گیا تھا۔ “بنو المجر” انہی کی اولاد کا کوفہ میں ایک “بطن” ہے، وہاں ان کی مسجد بھی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۷) استیعاب (۱۰۷۱)"}],[3476,"§۳۴۸۲ ۔ سمرہ بن مغیر بن لوذان الجمحی(1)\nابو محذورہ کے بھائی۔ بقول بعض: ابو محذورہ ہی کا نام ہے۔ “الجمہرہ” میں ابن حزم لکھتے ہیں: محمد شین کا خیال ہے کہ ابو محذورہ کا نام سمرہ ہے، جبکہ ایسا نہیں، سمرہ تو ان کے بھائی کا نام ہے۔ میں کہتا ہوں: ابن معین اور ابن سعد وغیرہ نے اس پر بھروسا کیا ہے کہ ابو محذورہ کا نام سمرہ ہے، جبکہ مصعب زبیری فرماتے ہیں: ابو محذورہ کا نام اوس ہے۔ ان کا سمرہ نامی ایک بھائی تھا، اسی قول پر ابن حزم نے اعتماد کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۴۸) استیعاب (۱۰۷۰)"}],[3477,"§۳۴۸۳ ۔ سمعان بن خالد(1)\nاز بنی تحریک۔ ابن مندہ کی روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کے لیے برکت کی دعا کی، جب وہ آپ کے پاس آئے اور ان کی پیشانی پر دست مبارک پھیرا تھا جس کے متعلق ایک طویل حدیث(2) ہے۔ اس کی اسناد میں غیر معروف راوی ہیں۔ ابو عمر نے تو اس بن سمعان کے حالات میں لکھا ہے: یہ سمعان بن خالد نو اس کے والد ہیں۔ علیحدہ سے ان کا عنوان نہیں قائم کیا۔","",{"fn":"(1) اسد الغابہ (۲۲۴۹)\n(2) المستدرک (۲۳۵/۲)"}],[3478,"§۳۴۸۴ ۔ سمعان بن عمرو(1)\nبن حجر اسلمی۔ بقول ابن مندہ: انہیں شرف صحابیت حاصل ہے۔ پھر بحوالہ سمعان بن عمرو روایت کی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم سے اسلام کے بارے بیعت کی اور رسالت کی تصدیق کی۔ آپ صلی اللہ علیہ وسلم نے انہیں ایک قطعہ ارض عطا کیا، جس کی سند میں کئی مجہول راوی ہیں۔ ان کا بیٹا خیار ہے۔ ابو عمر کی کتاب “الافراد” میں حرف سین کے تحت لکھتے ہیں: سمعان بن عمرو اسلمی، ان کی حدیث اسناد صحیح نہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۵۰) استیعاب (۱۱۵۰)"}],[3479,"§۳۴۸۵ ۔ سمعان بن عمرو\nبن قریط بن عبید بن ابی بکر بن کلاب کلابی۔ مدائنی نے “رسول اللہ صلی اللہ علیہ وسلم کے قاصد” نامی کتاب میں لکھا ہے کہ لوگوں کا بیان ہے رسول اللہ صلی اللہ علیہ وسلم نے سمعان بن عمرو کی طرف عبد اللہ بن عوسجہ کے ہاتھ اپنا خط دے کر بھیجا جس سے انہوں نے اپنا ڈول لیا، جس کی وجہ سے انہیں بنی مرقع (پیوند لگانے والی کی اولاد) کہا جانے لگا۔ پھر سمعان مسلمان ہو گئے، اور آپ صلی اللہ علیہ وسلم کے پاس آئے اور یہ اشعار سنائے: ط “مجھے آپ معاف رکھیں جیسے آپ صلی اللہ علیہ وسلم نے ورد کو امان دی میں آپ کے پاس درد سے آیا ہوں، میں نے کوئی برا گناہ نہیں کیا”۔ ان کا اشارہ ورد بن مرداس کی طرف تھا جو بنی سعد عذیم کے ایک فرد ہیں۔ آپ نے اس کی طرف سمجھور کی شاخ پر تحریر بھیجی تو اس نے شاخ توڑ دی پھر وہ بھی مسلمان ہو گئے۔ اور وادی القری میں سیدنا زید بن حارثہ کی معیت میں جنگ کی جس میں شہید ہوئے۔ احتمال ہے وہ تو اس کے والد سمعان ہوں اور ان کے نسب سے ان کے والد کا نام رہ گیا ہو۔ وہ نواس بن سمعان بن عمرو بن خالد بن عمرو بن قریط ہیں۔ ان کا بقیہ ایسا ہی ہے جیسا وہاں ذکر ہوا۔"],[3480,"§۳۴۸۶ ۔ سمعون\nآل حضر موت کے خلیف، موسیٰ بن سہل دنکی نے فلسطین فروکش ہونے والے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔"],[3481,"§۳۴۸۷ ۔ سمعون\nبقول بعض: همخون۔ ابو ریحانہ شین میں بیان ہوگا۔"],[3482,"§۳۴۸۸ ۔ سُمَیْحَہ(1)(2)\nبقوض بعض: بخشیمہ۔ اثیری نے ابن عبد البر کی کتاب میں اپنے استدراک میں ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ ابو لبابہ انصاری کا ایک پڑوسی تھا جس کا نام قیمہ یا سمجھہ تھا، اس کی کھجور کا سایہ ابو لبابہ رضی اللہ عنہ کے گھر میں پڑتا تھا۔ پھر وہ حدیث ذکر کی۔ میں کہتا ہوں: یہ واقعہ ابو دحداح کے حالات میں بیان ہوگا، جو انہی سے مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۱)\n(2) مسند احمد (۱۴۶/۳) فتح الباری (۵۸/۸)"}],[3483,"§۳۴۸۹ ۔ سمیدع الکنانی(1)\nابو الفرج اصبہانی کی بطریق ابن داب روایت ہے کہ جب سیدنا خالد بن ولید بنی کنانہ سے جنگ کرنے متوجہ ہوئے تو وہ کہنے لگے: ہم بے دین ہوئے، وہ یہ کہنا نہیں جانتے تھے کہ ہم مسلمان ہوئے۔ تو آپ نے ان سے جنگ کی، حضور نبی صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو روانہ کیا، آپ نے ان میں سے مقتولین کی دیت دی۔ فرماتے ہیں: اسی اثناء میں ایک نوجوان آیا جس کا نام سمیدع تھا، جس کا تعلق بنی اقرم سے تھا۔ اس نے نبی صلی اللہ علیہ وسلم کو لوگوں کے حالات سے آگاہ کیا اور جو کچھ خالد رضی اللہ عنہ نے ان سے کیا اس کا بھی ذکر کیا۔ ابن داب کا قول ہے کہ مجھے صالح بن کیسان نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “کیا خالد کے کیسے پر کسی نے نکیر کی ہے؟” انہوں نے عرض کی: ایک مرد زرد رنگ والا میانے قد کا تھا، اور دوسرا شخص دراز قد سرخ رنگ والا تھا۔ جس پر سیدنا عمر رضی اللہ عنہ نے فرمایا: پہلا میرا بیٹا تھا اور دوسرا سالم مولا ابی حذیفہ تھا۔ پھر وہ واقعہ ذکر کیا۔","",{"fn":"(1) البدایہ والنھایہ (۳۱۳/۴)"}],[3484,"§۳۴۹۰ ۔ سمیر بن حصین(1)\nبن حارث بن ابی خزیمہ بن ثعلبہ بن طریف الخزرجی۔ عدوی کا بیان ہے: اُحد میں شریک ہوئے اور خلافت فاروقی میں فوت ہوئے۔ اور ان کے گورنر تھے۔ لکھتے ہیں: انہیں ان سے خصوصی نشست حاصل تھی، طبری نے بھی ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۲)"}],[3485,"§۳۴۹۱ ۔ سمیر بن زہیر(1)\nعائذ بن سعد کے حالات میں ان کا ذکر ملتا ہے۔ ابن مندہ کی روایت ہے کہ عائذ بن سعد نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو سمیر نے عرض کی: “اللہ کے رسول صلی اللہ علیہ وسلم! میرا بھائی سلمہ بن زہیر اللہ اور رسول صلی اللہ علیہ وسلم کی طرف ہجرت کر کے نکلا تھا، وہ شہید ہو گیا ہے”۔ (حدیث)","",{"fn":"(1) اسد الغابہ (۲۲۵۳)"}],[3486,"§۳۴۹۲ ۔ سمیر بن کعب\nسیف نے “الفتوح” میں لکھا ہے کہ فتوحات کے امیروں میں شامل تھے۔ سیدنا ابو عبیدہ اور خالد بن ولید رضی اللہ عنہما کے جنگی دستوں میں شریک تھے۔"],[3487,"§۳۴۹۳ ۔ سمیر(1)\nسلیمان کے والد۔ شاید یہ سمرہ بن جندب ہیں۔ ابن مندہ کی روایت ہے سیدنا سمیر نے فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے دور میں متعہ کیا کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۴)"}],[3488,"§۳۴۹۴ ۔ سمیط البجلی(1)\nبغوی وغیرہ نے ان کا ذکر کیا ہے، پھر بغوی اور ابن قانع نے بحوالہ سمیط البجلی روایت کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “جس نے اللہ کی راہ میں ایک دن جہاد میں گزارا تو اسے رمضان کے روزوں اور قیام تراویح جیسا ثواب ملے گا”۔(2)","",{"fn":"(1) اسد الغابہ (۲۲۵۵) تجرید (۲۴۰/۱)\n(2) نسائی کتاب الجہاد باب فضل الرباط (۳۱۶۷) کنز العمال (۱۰۸۱۹)"}],[3489,"§۳۴۹۵ ۔ سمیفع\nذو الکلاع میں تذکرہ ہوا ہے۔"],[3490,"§۳۴۹۶ ۔ سنان بن تیم الجہنی(1)\nبنی عوف بن خزرج کے حلیف، سنان بن وبرہ میں تذکرہ ہوگا۔","",{"fn":"(1) استیعاب (۱۰۷۲)"}],[3491,"§۳۴۹۷ ۔ سنان بن ثعلبہ(1)\nبن عامر بن مجدعہ بن جشم بن حارثہ انصاری۔ بقول ابو عمر:(2) اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۸) استیعاب (۱۰۷۳)\n(2) اسد الغابہ (۲۱۷/۲)"}],[3492,"§۳۴۹۸ ۔ سنان بن رؤح(1)\nدارقطنی کا بیان ہے کہ حمص فروکش ہونے والے صحابہ میں ان کا ذکر ملتا ہے۔ بقول بعض: سیاران کا نام ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۹) استیعاب (۱۰۷۴)"}],[3493,"§۳۴۹۹ ۔ سنان بن سلمہ(1)\nعوف بن سراقہ میں ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۲۶۲) استیعاب (۱۰۷۸)"}],[3494,"§۳۵۰۰ ۔ سنان بن سنّہ اسلمی\nبقول بعض: حرملہ بن عمرو کے چچا۔ ایک قول ہے: ان کے دادا۔۔۔۔ پہلا قول زیادہ صحیح ہے۔ نبی صلی اللہ علیہ وسلم سے یہ حدیث نقل کرتے ہیں: “کھانا کھا کر شکر کرنے والے کے لیے روزہ رکھ کر صبر کرنے والے جیسا ثواب ہے”۔ ابن ماجہ(1) نے اسے نقل کیا ہے۔ امام احمد رضی اللہ عنہ(2) کی بطریق حرملہ بن عمرو اسلمی روایت ہے کہ میں نے حجۃ الوداع کے سال حج کیا، مجھے میرے چچا سنان بن سنّہ نے اپنے ساتھ سوار کیا تھا۔ ابن حبان(3) لکھتے ہیں، بقول بعض: خلافت عثمانی میں بنتیس (۳۳ھ) میں فوت ہوئے۔ میں کہتا ہوں: کسی راوی سے اس میں غلطی ہو گئی ہے، جیسا کہ حرف شین کی قسم رابع میں بیان ہوگا۔ سنان بن سنّہ کے حوالے سے ایک اور حدیث مروی ہے جس میں اس کے راوی سے غلطی ہوئی ہے۔ اسے ابو بکر بن ابی شیبہ(4) نے وکیع سے بواسطہ ابن ابی لیلی، عبد الکریم سے معاذ بن سعوہ بحوالہ سنان بن سنّہ ہدی کے بارے میں مرفوع روایت کرتے ہیں: “(اگر اسے ضرورت پڑے) تو کھا لے اگر کھا لے تو تاوان دینا پڑے گا”۔ عبد اللہ بن موسیٰ بواسطہ ابی لیلی نے اسی سند سے سنان بن سلمہ نام نقل کیا ہے۔ بغوی نے ان کا ذکر کیا ہے وہی درست ہے۔ سنان بن سلمہ ابن اکتم ہیں، جن کا ذکر قسم ثانی میں ہوگا۔","",{"fn":"(1) ابن ماجہ کتاب الصیام (۱۷۶۵)\n(2) مسند احمد (۳۴۳/۴)\n(3) الثقات (۱۷۸/۳)\n(4) المصنف لابن ابی شیبہ (۴۰۷/۸)"}],[3495,"§۳۵۰۱ ۔ سنان بن ابی سنان(1)\nبن محصن الاسدی۔ عکاشہ کے بھتیجے۔ ابن اسحاق نے شرکاء بدر میں ان کا ذکر کیا ہے۔ سیف کی “الفتوح” میں ہے کہ سنان بن ابی سنان پہلے شخص ہیں جنہوں نے طلیحہ بن خویلد اسدی سے نبی صلی اللہ علیہ وسلم کو خط لکھ کر آگاہ کیا۔ سنان بنی مالک کے سردار تھے۔ واقدی کا گمان ہے: انہوں نے سب سے پہلے درخت(2) تلے نبی صلی اللہ علیہ وسلم کے دست مبارک پر بیعت کی۔ ابو سنان وہب اسدی کے حالات میں ہے کہ وہ اس فضیلت سے موصوف ہیں۔ شعبی اور زر بن حبیش نے ان کا یہ وصف بیان کیا، جو دو صحیح طریقوں سے مروی ہے۔ فرماتے ہیں: بتیس (۳۲ھ) میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۱) استیعاب (۱۰۷۷) تجرید (۲۴۰/۱)\n(2) السیرۃ النبویۃ (۲۴۲/۲)"}],[3496,"§۳۵۰۲ ۔ سنان بن ابی سنان اسدی\nدوسرے ہیں۔ ان کی حدیث ان کے والد ابو سنان اور والدہ ام سنان کے حالات میں بیان ہوگی۔"],[3497,"§۳۵۰۳ ۔ سنان بن سوید جہنی(1)\nابن السکن کی روایت ہے کہ یاسر بن سوید، سنان بن سوید اور سیار بن سوید سب آپس میں بھائی تھے، جن کی نبی کریم صلی اللہ علیہ وسلم سے ملاقات ہوئی۔","",{"fn":"(1) اسد الغابہ (۳۸۱/۲)"}],[3498,"§۳۵۰۴ ۔ سنان بن شفعلہ(1)(2)\nبقول بعض: شمعلہ۔ ایک قول ہے: ابن شعلہ اوسی۔ ابو موسیٰ کی روایت ہے کہ سنان بن شفعلہ اوسی نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “مجھ سے جبرائیل نے بیان کیا کہ جب اللہ تعالیٰ نے فاطمہ رضی اللہ عنہا کی شادی علی رضی اللہ عنہ سے کر دی تو رضوان کو حکم دیا، اس نے شجرہ طوبی کو حکم دیا تو اس پر آل بیت محمد صلی اللہ علیہ وسلم سے محبت کرنے والوں کی مقدار پتے لگ گئے”۔ ابو موسیٰ فرماتے ہیں: اس کی سند میں سوائے عباد بن راشد کے کوئی مشہور راوی نہیں اور محمد بن فارس رافضی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۳)\n(2) جامع المسانید (۱۴/۶)"}],[3499,"§۳۵۰۵ ۔ سنان بن صیفی(1)(2)\nبن صخر بن خنساء بن سنان بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاری۔ بقول ابن شاہین بحوالہ اپنے رجال: بدر و احد اور بعد کے معرکوں میں شریک ہوئے۔ ابن ابی حاتم بحوالہ اپنے والد نقل کرتے ہیں: بدری ہیں۔ جبکہ ابن اسحاق کے ہاں بدری صحابہ رضی اللہ عنہم میں ابو سنان بن صیفی ہیں، تو اگر وہ ان کے بھائی نہیں تو دو میں سے ایک قول وہم پر مبنی ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۴) استیعاب (۱۰۷۹)\n(2) الجرح والتعدیل (۲۵۱/۴)"}],[3500,"§۳۵۰۶ ۔ سنان بن ظہیر اسدی(1)(2)\nبقول ابو عمر: صحابی ہیں۔ ابو نعیم بحوالہ سنان بن ظہیر روایت کرتے ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ایک اونٹنی ہدیہ پیش کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: “دودھ پینے والے کے لیے تھوڑا سا دودھ چھوڑ دو (یعنی سارا دودھ نہ دوہنا)”۔(3)","",{"fn":"(1) اسد الغابہ (۲۲۶۶) استیعاب (۱۰۸۰) تجرید (۲۴۱/۱)\n(2) استیعاب (۲۱۹/۲)\n(3) جامع المسانید (۱۵/۶)"}],[3501,"§۳۵۰۷ ۔ سنان بن عبد اللہ(1)(2)\nبن قشیر بن خزیمہ اسلمی۔ اکوع لقب تھا۔ ابن سعد رضی اللہ عنہ نے صحابہ کرام رضی اللہ عنہم کے تیسرے طبقہ میں ان کا ذکر کیا ہے کہ بہت پہلے اسلام لائے، خود اور ان کے بیٹے عامر اور سلمہ بھی صحابی ہیں۔ یہی روایت بغوی اور طبری کی ہے۔ ان کا یہ کہنا کہ ان کے دونوں بیٹے” اس میں چشم پوشی ہے۔ کیونکہ عامر تو ان کے بیٹے ہیں جبکہ سلمہ ان کے پوتے ہیں۔ جیسا کہ ان کے حالات میں بیان ہوا ہے۔ تجرید میں اسے بعید سمجھا ہے۔ پھر لکھتے ہیں: یقینا یہ غلطی ہے، کیونکہ انہیں بعثت کا زمانہ نہیں نصیب ہوا، سو جو کچھ انہوں نے کہا اس میں بھی تامل ہے، جیسا کہ عیاں ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۸)\n(2) الطبقات (۳۷/۴)"}],[3502,"§۳۵۰۸ ۔ سنان بن عبد اللہ الجہنی(1)\nحدیث ابن عباس رضی اللہ عنہما میں ان کا ذکر ملتا ہے۔ ابن خزیمہ بطریق موسیٰ بن سلمہ ھذلی روایت کرتے ہیں کہ میں اور سنان بن سلمہ عمرہ کرنے گئے۔ میں نے ابن عباس رضی اللہ عنہما سے پوچھا میری والدہ کی طرف سے عمرہ ہو جائے گا؟ انہوں نے فرمایا: میں نے سنان بن عبد اللہ الجہنی کی اہلیہ سے کہا تھا کہ وہ نبی صلی اللہ علیہ وسلم سے اپنی والدہ کے بارے میں پوچھیں کہ ان کی والدہ حج نہ کر سکی تھیں، آیا یہ ان کی طرف سے حج کر سکتی ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا تھا: “ہاں”۔(2) ایک اور طریق سے مروی ہے، ایک جہنی نے کہا: ایسا ہی مسند احمد(3) علم میں لکھا ہے۔ ابن مندہ کا قول ہے: یہی روایت محمد بن کریب نے بحوالہ اپنے والد نقل کی تو کہا: سنان بن عبد اللہ۔ میں کہتا ہوں: یہی روایت طبرانی میں ہے، وہاں انہوں نے محمد بن کریب سے سنان کی جگہ سفیان نقل کیا ہے، جو وہم سے ایک قول ہے۔ ابن عباس، حصین بن عوف سمی سے روایت کرتے ہیں، لیکن بظاہر وہ ایک علیحدہ واقعہ ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۷) استیعاب (۱۰۸۱) تجرید (۲۴۱/۱)\n(2) التاریخ الکبیر (۱۶۱/۴)\n(3) مسند احمد (۲۲۷/۱)"}],[3503,"§۳۵۰۹ ۔ سنان بن ابی عبید\nبن وہب بن لوذان بن عبد ود بن زید بن ثعلبہ انصاری۔ بقول عدوی: احد میں شریک ہوئے۔"],[3504,"§۳۵۱۰ ۔ سنان بن غرفہ(1)(2)\nابن مفرج نے ابن اسکن کی کتاب میں ایسا ہی قلمبند کیا ہے۔ اسی طرح باوردی کی کتاب الصحابہ میں لکھا ہے۔ ابن فتحون فرماتے ہیں: میں نے ابن السکن کے ایک نسخہ میں عین کے زیر اور را کے سکون سے عرقہ بعد میں قاف سے لکھا دیکھا ہے۔ باوردی، ابن السکن اور طبرانی رضی اللہ عنہم کی بطریق بسر بن عبد اللہ بحوالہ سنان بن غرفہ روایت ہے، جو صحابی ہیں، کہ نبی صلی اللہ علیہ وسلم سے مروی ہے: “جو عورت ایسے مردوں کے ساتھ فوت ہو جائے جو اس کے محرم نہ ہوں تو اسے تیمم کرایا جائے، غسل نہ دیا جائے”۔ یہی مسئلہ مرد کے بارے میں ہے (یعنی مرد مسافر تھے ان کے ساتھ ایک عورت سفر کرتے فوت ہوگئی یا چار پانچ عورتوں کے ساتھ ایک اکیلا شخص سفر کرتے فوت ہو گیا تو مرد اس اجنبی عورت کو اور عورتیں اس اجنبی مرد کو غسل میت نہ دیں بلکہ تیمم کرا کے دفنا دیں)۔","",{"fn":"(1) اسد الغابہ (۲۲۶۹) تجرید (۲۴۱/۱)\n(2) المعجم الکبیر (۱۰۲/۷)"}],[3505,"§۳۵۱۱ ۔ سنان بن عمرو(1)\nبن طلق القضاعی ابو المقنع بنی ظفر کے حلیف۔ بقول ابن کلبی: انہیں اسلام لانے میں سبقت اور شرف حاصل ہے، نبی صلی اللہ علیہ وسلم کے ساتھ اُحد وغیرہ میں شریک ہوئے۔ ابن شاہین نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۷۰) استیعاب (۱۰۸۲)"}],[3506,"§۳۵۱۲ ۔ سنان بن مقرن المزنی(1)(2)\nبھائیوں میں سے ایک، مولی ابن سعد، ملک صحابی ہیں۔ ابو حاتم، ابن شاہین اور کئی ایک نے انہیں صحابہ میں شمار کیا ہے۔ ابن مندہ فرماتے ہیں: مغازی میں ان کا ذکر ملتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۷۱) استیعاب (۱۰۸۳)\n(2) الطبقات (۱۱/۶)"}],[3507,"§۳۵۱۳ ۔ سنان بن وبرہ(1)(2)\nیا وبر الجھنی، بنی حارث بن خزرج کے حلیف۔ ابن ابی حاتم بحوالہ اپنے والد لکھتے ہیں: “انہوں نے ہی عبد اللہ بن ابی کو کہتے سنا تھا: اگر ہم مدینہ صحیح سالم لوٹ گئے ... -(3) (تو عزت مند ذلیل لوگوں کو نکال باہر کریں گے)۔ طبرانی(4) کی روایت ہے کہ رافع الجھنی فرماتے ہیں، میں نے سنان بن وبرہ جھنی کو فرماتے سنا: غزوہ بنی مصطلق کے موقع پر ہم لوگ نبی صلی اللہ علیہ وسلم کے ساتھ تھے، ہمارا شعار (کوڈ) تھا “یا منصور آیت”۔ الاوسط کی روایت ہے کہ سنان سے صرف اسی سند سے حدیث منقول ہے جس میں محمد بن جہضم منفرد ہے۔ ابو عمر لکھتے ہیں: ان کا نام سنان بن تیم ہے۔ “ابن وبرہ” کہا جاتا ہے۔ انہوں نے ہی جھجاہ غفاری سے پانی پر جھگڑا کیا تھا اور مرنے مارنے پر اتر آئے تھے۔ میں کہتا ہوں: یہ حدیث صحیح میں دونوں آدمیوں کے نام کے بغیر موجود ہے، جس کا کچھ تذکرہ جھجاہ کے حالات میں بیان ہوا ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۵۱/۴)\n(2) تجرید (۲۴۱/۱)\n(3) سورۃ المنافقون: ۸\n(4) المعجم الکبیر (۶۴۹۶/۷)"}],[3508,"§۳۵۱۴ ۔ سنان الضمری(1)\nابو عمر نے ان کا ذکر کیا ہے کہ ابو بکر رضی اللہ عنہ نے انہیں مدینہ میں اپنا نائب بنا کر مرتدوں کے خلاف جہاد کیا تھا۔ سنین ابو جمیلہ کے واقعہ میں ہے جب انہیں نوزائدہ بچہ ملا، سیدنا عمر رضی اللہ عنہ نے ان کے متعلق ان کی قوم کے ناظم سے پوچھا، انہوں نے کہا: نیک آدمی ہیں۔ شیخ ابو حامد کا بیان ہے کہ ناظم کا نام سنان تھا۔ احتمال ہے کہ وہ یہی ہوں۔","",{"fn":"(1) اسد الغابہ (۲۲۶۵) استیعاب (۱۰۸۴)"}],[3509,"§۳۵۱۵ ۔ سنان (بے نسبت)(1)(2)\nباوردی کی روایت ہے کہ سنان سے مروی ہے، نبی صلی اللہ علیہ وسلم نے سیدنا ابو بکر رضی اللہ عنہ سے فرمایا: “(اس حدیث کے دو ترجمے ہیں)” ۱ سوچ سمجھ کر دوست کا انتخاب کرو، پھر اس سے محتاط رہو۔ ۲ مال بچا کر رکھو اور فضول خرچی سے بچو”۔","",{"fn":"(1) اسد الغابہ (۲۲۷۴)\n(2) المعجم الصغیر (۲۶۶/۱) کنز العمال (۲۴۷۷۹)"}],[3510,"§۳۵۱۶ ۔ سنان\nبقول بعض: ابو ہند حجام (سینگی لگانے والے) کا نام ہے۔ سالم میں تذکرہ ہوا ہے۔"],[3511,"§۳۵۱۷ ۔ سَنْبَرہ (بروزن جعفر) الاراشی(1)\nخطیب کے قلم سے میں نے ایسا ہی لکھا دیکھا ہے۔ ان کا ذکر ایک اور حدیث میں بھی ہے جو ابن شاہین اور ابن السکن نے بحوالہ مالک رضی اللہ عنہ روایت کی ہے کہ مجھے یاد ہے کہ نبی صلی اللہ علیہ وسلم کے پاس وادی القری میں عمرو بن حسان بنی اراش کا ایک شخص لے کر آئے، جس کا نام سنبر تھا اور ان کے حلیف تھے۔ تو آپ صلی اللہ علیہ وسلم نے ان سے اسلام کی بیعت لی۔ وہ عرض کرنے لگے: اللہ کے رسول صلی اللہ علیہ وسلم! میرے حلیف کو قطعہ ارضی عطا فرما دیں۔ چنانچہ آپ صلی اللہ علیہ وسلم نے انہیں جاگیر دی اور اس کے لیے بطور سند کھجور کی شاخ پر ایک تحریر بھی لکھوا کر دی۔ ابن فتحون کی کتاب میں سنبر کی جگہ ستیار لکھا ہے۔ شاید یہ لفظی غلطی ہے۔ خطیب نے المؤتلف میں ان کا ذکر کیا ہے لیکن انہوں نے ابواشی لکھا ہے، جو میں نے خود ان کے قلم سے لکھا ہوا پڑھا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۷۵)"}],[3512,"§۳۵۱۸ ۔ سَنْدَر(1)(3)(4)(6)\nمولا زنباع الجذامی، زنباع میں ذکر ہوا ہے۔ امام بخاری رحمہ اللہ لکھتے ہیں: سندر صحابی ہیں۔(2) طبرانی کی روایت ہے کہ سندر زنباع کے غلام تھے۔ جن سے ناراض ہو کر انہیں آختہ (خصی) کر دیا۔ (حدیث) عمرو بن شعیب نے ان کی حدیث نقل کی ہے اور اس میں یہ اضافہ ہے کہ سندر نے سیدنا عمر بن خطاب رضی اللہ عنہ سے گزارش کی کہ ان کی رجسٹریشن مصر میں کر دی جائے تو آپ رضی اللہ عنہ نے ان کی یہ بات قبول کرلی۔ چنانچہ یہ وہاں فروکش ہو گئے۔ ابن مندہ نے ان کا ذکر کیا ہے اور ان کا واقعہ نقل کیا ہے کہ انہوں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی وصیت فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “میں تمہیں ہر مسلمان کے بارے میں (نیک سلوکی) کی وصیت کرتا ہوں”۔ پھر سیدنا ابو بکر رضی اللہ عنہ کے پاس آئے تو ان کی وفات تک انہی کی زیر کفالت رہے۔ پھر سیدنا عمر رضی اللہ عنہ کے پاس آئے، آپ رضی اللہ عنہ نے فرمایا: اگر میرے پاس رہنا چاہتے ہو تو تمہارا وظیفہ جاری کر دوں اور جو جگہ تمہیں زیادہ اچھی لگتی ہے وہ تمہارے لیے نامزد کر دیتا ہوں۔ انہوں نے مصر کا علاقہ منتخب کیا۔ جب سیدنا عمرو کے پاس پہنچے تو انہوں نے کشادہ زمین اور ایک حویلی بطور جاگیر دے دی۔ میں کہتا ہوں: ابن یونس نے اسے ترجیح دی ہے کہ سیدنا عمر رضی اللہ عنہ کے ساتھ سندر کے بیٹے کا واقعہ پیش آیا تھا، جس کی وضاحت مسروح بن سندر کے حالات میں بیان ہوگی۔ المؤتلف میں خطیب لکھتے ہیں: اس شخص کے بارے اختلاف ہے جسے زنباع نے آختہ کیا تھا۔ بقول بعض: وہ خود سندر ہی ہیں، ایک قول ہے ان کا بیٹا تھا، بقول بعض سندر کے والد تھے۔ میں کہتا ہوں: ایک قول ہے: ابو الاسود تھے۔ راجح یہی ہے کہ وہ آختہ سندر ہی تھے۔ ان کی کنیت ابو الاسود تھی، عبد اللہ اور مسروح ان کے بیٹے ہیں۔ امام بخاری رحمہ اللہ یہ فرماتے ہیں: سندر ابو الاسود صحابی ہیں۔ زہری بواسطہ سندر وہ بحوالہ اپنے والد روایت کرتے ہیں۔ سعید بن عفیر کی روایت ہے کہ عثمان بن سوید جروی نے مسروح بن سندر کو دیکھا تھا، جن کی ناک زنباع نے کاٹی تھی۔ سندر نے عبد الملک کے دور تک عمر پائی۔ ذیل میں ابو موسیٰ کی بطریق ابو الخیر بحوالہ سندر روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “قبیلہ اسلم کو اللہ تعالیٰ سلامت رکھے اور غفار کی مغفرت فرمائے۔ حکم مانتے اور اللہ تعالیٰ کا حکم قبول کیا”۔(5) قسم رابع میں اس بارے میں ابو موسیٰ کو جو وہم ہوا ہے اس کی تفصیل بیان ہوگی۔ محمد بن رجع الجیزی نے مصر آنے والے صحابہ رضی اللہ عنہم کے بارے میں لکھا ہے کہ اہل مصر کے ہاں بحوالہ سندر دو حدیثیں مروی ہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۷۷) استیعاب (۱۱۵۱)\n(2) التاریخ الکبیر (۲۱۰/۲)\n(3) المعجم الکبیر (۱۶۹/۷) مجمع الزوائد (۴۲۷/۴) کنز العمال (۳۷۱۳۱) الطبقات (۱۹۷/۷) مختصر تاریخ دمشق (۳۸۷/۵)\n(4) التاریخ الکبیر (۲۱۰/۲)\n(5) بخاری کتاب المناقب باب فی ذکر اسلم و غفار (۳۵۱۴)\n(6) مسلم کتاب فضائل الصحابہ باب دعاء النبی لغفار و اسلم (۳۹۴۰) مجمع الزوائد (۴۷/۱۰)"}],[3513,"§۳۵۱۹ ۔ سُنَیْن ابو جمیلہ سلمی(1)(4)\nبقول بعض: ضمری۔ ایک قول ہے: ان کے والد کا نام واقد ہے، جسے ابن حبان رضی اللہ عنہ نے نقل کیا ہے۔ امام بخاری(2) بطریق زہری بحوالہ ابو جمیلہ روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کی معیت میں حج کیا۔ ابن سعد(3) نے تابعین کے پہلے طبقہ میں ان کا ذکر کیا ہے کہ ان کی کئی احادیث ہیں۔ عجلی کا قول ہے: معتبر تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۷۸) استیعاب (۱۱۵۲)\n(2) بخاری کتاب المغازی باب مقام النبی بمکۃ زمن الفتح (۴۲۰۱)\n(3) الطبقات (۴۵/۵)\n(4) الثقات (۱۷۹/۳)"}],[3514,"§۳۵۲۰ ۔ سنین بن واقد ظفری(1)(2)\nابن حبان نے صحابہ میں ان کا ذکر کیا ہے کہ ان کی مسند حدیث مشہور نہیں۔ بغوی کی روایت ہے کہ عثمان بن عبد الملک نے فرمایا: میں نے سنین بن واقد ظفری صحابی رسول صلی اللہ علیہ وسلم کو فرماتے سنا کہ رکن یمانی پر ایک فرشتہ ہے جو ہر استلام کرنے والے کی دعا پر آمین کہتا ہے”۔ بغوی کے حوالہ سے ابن قانع نے یہ روایت نقل کی ہے۔ ان میں سے بعض نے انہیں اور سابقہ شخصیت کو ایک لکھا ہے۔ جبکہ درست یہ ہے کہ دونوں میں فرق ہے۔ تجرید میں ہے: ساٹھ (۶۰ھ) کے بعد ان کی وفات ہوئی۔","",{"fn":"(1) اسد الغابہ (۲۲۷۹) تجرید (۲۴۲/۱)\n(2) الثقات (۱۷۹/۳)"}],[3515,"§۳۵۲۱ ۔ سہل ابن بیضاء قرشی(1)\nبیضاء ان کی والدہ ہیں جن کا نام وغد تھا۔ والد کا نام وہب بن ربیعہ بن عمرو بن عامر بن ربیعہ بن ہلال بن مالک بن خبر بن حارث بن فہر قرشی تھا۔ ان لوگوں میں شامل تھے جنہوں نے قریش کی بنی ہاشم کے خلاف لکھی جانے والی تحریر کو ختم کرنے کی کوشش کی تھی۔ ابو حاتم(2) کا قول ہے: مکہ میں اسلام کا اظہار کرتے تھے۔ بغوی ابو بکر رضی اللہ عنہ کے سوانح میں لکھتے ہیں کہ ابن عیینہ سے کسی نے پوچھا، اصحاب رسول صلی اللہ علیہ وسلم میں سے بڑی عمر والا کون ہے؟ تو حسین بن جدعان نے کہا: میرے خیال میں سیدنا انس رضی اللہ عنہ سے مروی ہے کہ سیدنا ابو بکر رضی اللہ عنہ نے فرمایا: سہل بن بیضاء۔ مسلم اور ابو داؤد میں سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیضاء کے دونوں بیٹوں سہیل اور ان کے بھائی کا جنازہ مسجد میں ہی پڑھا۔ یہی روایت ابن مندہ نے نقل کی ہے، اس میں “سہل” لکھا ہے۔ ابو عمر(3) فرماتے ہیں: سہل مکہ میں اسلام لائے لیکن کسی سے اپنے مسلمان ہونے کو ظاہر نہیں کیا۔ قریش انہیں بدر میں ساتھ لے گئے، گرفتار ہوئے تو ابن مسعود رضی اللہ عنہ نے ان کے بارے گواہی دی کہ میں نے انہیں مکہ میں نماز پڑھتے دیکھا ہے، اس لیے آزاد کر دیئے گئے۔ مدینہ میں وفات پائی تو آپ صلی اللہ علیہ وسلم نے ان کا اور ان کے بھائی سہیل کا جنازہ مسجد میں پڑھایا۔ میں کہتا ہوں: امام مالک رحمہ اللہ نے گزشتہ حدیث کی روایت میں سہیل سے زیادہ کچھ نہیں کہا۔ واقدی کا گمان ہے: یہ سہل نبی صلی اللہ علیہ وسلم کے بعد فوت ہوئے تھے۔ ابو نعیم لکھتے ہیں: سہیل کے بھائی کا نام صفوان تھا، جس نے ان کا نام سہل بتایا، اسے وہم ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۸۲) استیعاب (۱۰۸۵)\n(2) الجرح والتعدیل (۱۹۴/۴)\n(3) استیعاب (۲۲۱/۲)"}],[3516,"§۳۵۲۲ ۔ سہل بن حارث(1)(2)\nبن عمرو یا عروہ بن عبد رزاح انصاری۔ بقول عدوی: اُحد میں شریک ہوئے، ان کی کوئی نرینہ اولاد نہ تھی۔ ابن امین نے ان کا نام عروہ بتایا ہے، جبکہ ابن دباغ نے عمرو بتایا ہے۔ ابن الاثیر نے بھی ان کا اتباع کیا ہے، دونوں عدوی سے نقل کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۲۸۴)\n(2) اسد الغابہ (۳۸۷/۲)"}],[3517,"§۳۵۲۳ ۔ سہل بن حارثہ انصاری(1)(4)(5)\nابن ابی عاصم نے “الآحاد” میں ان کا ذکر کیا ہے۔ دراوردی کی بحوالہ سہل بن حارثہ انصاری روایت ہے کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکایت کی کہ ایک حویلی میں رہنے سے پہلے وہ بڑی تعداد میں تھے اب ان کی تعداد کم ہو گئی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تم لوگوں نے اس گھر کو برا سمجھتے ہوئے چھوڑ کیوں نہیں دیا”۔ ابن مندہ کا قول ہے: ان کا صحابی ہونا صحیح نہیں۔ تابعین میں شمار ہوتے ہیں۔ ابن حبان(2) رحمہ اللہ نے تابعین میں ان کا ذکر کیا ہے۔ ابن الاثیر نے ابو علی غسانی اور ابن القداح سے نقل کیا ہے کہ حارثہ بن سہل ان کے والد اور یہ خود اُحد اور باقی غزوات میں شریک ہوئے۔ ابن ماکولا(3) نے اس کا مفہوم نقل کر کے یہ اضافہ بھی کیا ہے کہ سہل کی مدینہ اور بغداد میں اولاد ہے۔ یہی حدیث ابو نعیم نے روایت کی تو اس میں سلمہ بن حارثہ لکھا اور سعد بن اسحاق سے آگے ان کے نام میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۸۳) استیعاب (۱۰۸۶) تجرید (۲۴۲/۱)\n(2) المعجم الکبیر (۶۳/۶)\n(3) جامع المسانید (۵۰/۴)\n(4) الثقات (۳۲۱/۴)\n(5) اسد الغابہ (۳۸۶/۲)"}],[3518,"§۳۵۲۴ ۔ سہل بن ابی حثمہ(1)\nبن ساعدہ بن عامر بن عدی بن مجدعہ بن حارثہ بن حارث بن عمرو بن مالک بن الاوس انصاری اوسی۔ ان کے والد کے نام میں اختلاف ہے۔ بقول بعض: عامر/عبد اللہ۔ والدہ کا نام ام الربیع بنت سالم بن عدی بن مجدعہ ہے۔ ایک قول ہے۔ نبی صلی اللہ علیہ وسلم کی وفات کے وقت سہل کی عمر سات آٹھ(2) (۷/۸) سال تھی۔ آپ علیہ السلام سے کئی احادیث نقل کی ہیں۔ اسی طرح زید بن ثابت، محمد بن مسلمہ سے روایت کی ہے جبکہ ان سے ان کا بیٹا محمد، بھتیجا محمد بن سلیمان بن ابی حثمہ، بشیر بن یسار، صالح بن خوات، نافع بن جبیر اور عروہ وغیرہ روایت کرتے ہیں۔ ابن ابی حاتم(3) بحوالہ اپنے والد لکھتے ہیں: انہوں نے درخت تلے بیعت کی اور سوائے بدر باقی غزوات میں شمولیت کی۔ اُحد کی رات وہ نبی صلی اللہ علیہ وسلم کے راہبر تھے۔ ابن القطان فرماتے ہیں: یہ صحیح نہیں کیونکہ اُحد کا اس پر اتفاق ہے کہ نبی صلی اللہ علیہ وسلم کی رحلت کے وقت وہ سات آٹھ سال کے تھے، جن میں ابن مندہ، ابن حبان،(4) ابن السکن، ابو الحکم احمد اور طبری شامل ہیں۔ اور اس پر بھروسا کیا ہے کہ خلافت معاویہ کے آغاز میں فوت ہوئے۔ اور ان سے یہ غلطی ہوئی کہ وہ ان کے والد تھے۔ مجھے لگتا ہے جس نے باقی غزوات میں شرکت کا قول اختیار کیا اسے سہل بن حنظلیہ کی وجہ سے اشتباہ ہو گیا کیونکہ مذکورہ قول ان کے متعلق ہے۔ ایک قول ہے: یہ بات ان کے والد ابو حثمہ کے متعلق مذکور ہے جنہیں نبی صلی اللہ علیہ وسلم نے کھجوروں کے پھلوں کا اندازہ لگانے بھیجا تھا، اور وہی اُحد میں آپ صلی اللہ علیہ وسلم کے راہنما تھے۔","",{"fn":"(1) الاکمال (۱/۱۱۳)\n(2) مسند احمد (۳/۴۴۸)\n(3) الجرح والتعدیل (۴/۲۰۰)\n(4) الثقات (۳/۱۶۶)"}],[3519,"§۳۵۲۵ ۔ سہل بن حمار انصاری\nبقول التحریر یمامہ میں شہید ہوئے۔"],[3520,"§۳۵۲۶ ۔ سہل ابن الحنظلیہ(1)\nان کے والد کا نام الربیع تھا۔ بقول بعض: عبید، عقیب بن عمرو۔ ایک قول ہے: عمرو بن عدی، یہی زیادہ مشہور ہے۔ عدی زید بن حشم بن حارثہ بن حارث بن خزرج بن عمرو بن مالک بن اوس انصاری اوسی کے بیٹے ہیں۔ ابن ابی خیثمہ کا قول ہے: حنظلیہ ان کی والدہ ہیں، ایک قول ہے: ان کی دادی ہیں۔ بقول بعض: پر دادی ہیں۔ ابن سعد ان کا نسب بیان کرنے کے بعد لکھتے ہیں: حنظلیہ عمرو بن عدی کی والدہ ہیں۔ ان کا نام اُم ایاس بنت ابان بن دارم تمیمی تھا۔ عمرو بن عدی کی اولاد کے ہر شخص کو ابن حنظلیہ کہا جاتا ہے۔ ابن البرقی لکھتے ہیں: ان کے والد کا نام عبید تھا جو بنی عدی بن زید کے فرد تھے۔ اُحد اور بعد کے معرکوں میں شریک ہوئے۔ پھر شام منتقل ہوئے اور وفات تک وہیں رہے۔ نبی صلی اللہ علیہ وسلم سے روایت کی ہے، ان سے ابو کبشہ سلولی، قاسم بن عبد الرحمن، یزید بن ابی مریم شامی وغیرہ روایت کرتے ہیں۔ امام بخاری(2) فرماتے ہیں: صحابی ہیں۔ ان کے ہاں اولاد نہ ہوتی تھی، درخت تلے بیعت کی تھی۔ ان کے علاوہ کا قول ہے: سوائے بدر باقی معرکوں میں شریک ہوئے۔ ابو زرعہ بحوالہ دحیم روایت کرتے ہیں: خلافت معاویہ میں فوت ہوئے۔ جامع ابن وہب میں بطریق قاسم مولا معاویہ مروی ہے، دوپہر کے وقت میں دمشق کی جامع مسجد میں پہنچا۔ اس وقت امیر معاویہ وہاں کے خلیفہ تھے۔ میں نے دیکھا ایک شخص لوگوں سے حدیث بیان کر رہا ہے۔ میں نے جھانک کر دیکھا تو زرد داڑھی والا ایک بزرگ شخص لوگوں میں بیٹھا ہے، مجھ سے کسی نے کہا: یہ سہل ابن حنظلیہ صحابی رسول صلی اللہ علیہ وسلم ہیں۔ امام احمد اور ابو داؤد نے ان کی حدیث بطریق قیس بن بشر روایت کی ہے۔ مجھے میرے والد نے بتایا وہ ابو درداء رضی اللہ عنہ کی مجلس میں بیٹھے تھے کہ دمشق میں ابن حنظلیہ نامی ایک صحابی تھے، وہ یکسو انسان تھے۔ بہت کم لوگوں سے ملتے۔ اکثر نماز میں مشغول ہوتے، نماز سے فراغت کے بعد سبحان اللہ، اللہ اکبر پڑھتے، یہاں تک کہ ان کے گھر والے جو قریب ہی تھے آ جاتے۔ ہم اس وقت ابو درداء رضی اللہ عنہ کے پاس تھے، تو ابو درداء رضی اللہ عنہ نے ان سے فرمایا: ایک بات ہے جس سے ہمیں نفع ہوگا اور آپ کا کوئی نقصان نہ ہو۔(3) پھر مرفوع احادیث ذکر کیں جو تین مواقع کی ہیں۔ ابو زرعہ دمشقی کا قول ہے: امیر معاویہ بن ابی سفیان رضی اللہ عنہ کی خلافت کے ابتدائی دور میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۸۶) استیعاب (۱۰۸۸)\n(2) التاریخ الکبیر (۲/۹۸)\n(3) ابو داؤد مراسیل (۱۴۷) مسند احمد (۲/۲۶۶)"}],[3521,"§۳۵۲۷ ۔ سہل بن حنظلہ العبشمی(1)\nبقول بعض: ابن حنظلیہ سہیل میں تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۲۸۸) استیعاب (۱۰۸۹)"}],[3522,"§۳۵۲۸ ۔ سہل بن حنیف\nبن واہب بن الحکیم بن ثعلبہ بن حارث بن مجدعہ بن عمرو بن حبیش بن عوف بن عمرو بن عوف بن مالک بن اوس انصاری اوسی۔ ابو سعد یا ابو عبد اللہ از اہل بدر۔ نبی صلی اللہ علیہ وسلم اور زید بن ثابت سے روایت کرتے ہیں جبکہ ان سے ان کے دونوں بیٹے ابو امامہ اسعد، عبد اللہ یا عبد الرحمن، ابو وائل، عبید بن السباق اور عبد الرحمن بن ابی لیلی وغیرہ روایت کرتے ہیں۔ سابقین میں سے تھے۔ بدر میں شریک تھے اور اُحد میں جب لوگوں کے پاؤں اکھڑنے لگے تو یہ ثابت قدم رہے۔ اس دن موت کی بیعت کی اور نیزے سے رسول اللہ صلی اللہ علیہ وسلم کا دفاع کر رہے تھے۔ آپ صلی اللہ علیہ وسلم فرمانے لگے: “سہل کو نیزے دو کیونکہ وہ سہل (آسان) ہے۔”(1) سیدنا عمر رضی اللہ عنہ فرماتے: “سہل (آسان) ہے، سخت نہیں”۔ اسی طرح غزوہ خندق اور باقی معرکوں میں شریک ہوئے۔ سیدنا علی رضی اللہ عنہ نے جنگ جمل کے بعد انہیں بصرہ میں اپنا نائب بنایا۔ پھر وہ آپ کے ساتھ صفین میں شریک ہوئے۔ بقول بعض: نبی کریم صلی اللہ علیہ وسلم نے انہیں اور سیدنا علی بن ابی طالب رضی اللہ عنہ کو بھائی بھائی بنایا۔ اڑتیس (۳۸ھ) میں فوت ہوئے۔ واقدی کا قول ہے: سہل کوفہ میں فوت ہوئے اور سیدنا علی رضی اللہ عنہ نے ان کا جنازہ پڑھایا۔ بقول مدائنی: اڑتیس (۳۸ھ) میں فوت ہوئے۔ عبد اللہ بن مغفل کا قول ہے: سیدنا علی رضی اللہ عنہ نے ان کا جنازہ پڑھایا تو چھ تکبیریں کہیں۔ ایک روایت میں ہے، پانچ تکبیریں کہیں۔ پھر فرمایا: یہ بدری ہیں۔","",{"fn":"(1) المستدرک (۳/۴۰۹) الطبقات (۳/۲) (۳/۴۰)"}],[3523,"§۳۵۲۹ ۔ سہل بن رافع(1)\nبن ابی عمرو بن عائذ بن ثعلبہ بن غنم بن مالک بن نجار انصاری خزرجی۔ بقول بعض: یہی صاع (ٹوپے) والے ہیں (جنہیں منافقین نے طعنہ دیا تھا)۔ ابن مندہ کا قول ہے: اُحد میں شریک ہوئے اور خلافت فاروقی میں فوت ہوئے۔ عیسیٰ بن یونس بواسطہ سعید بن عثمان بلوی وہ بحوالہ اپنی دادی بنت عدی سے روایت کرتے ہیں کہ ان کی والدہ عمیرہ بنت سہل بن رافع، صاع والے کی بیٹی تھیں جنہیں منافقین نے طعنہ دیا تھا۔ وہ ایک صاع کھجوریں اپنی زکوٰۃ لائے اور ساتھ اپنی بچی عمیرہ کو نبی صلی اللہ علیہ وسلم کے پاس لے کر حاضر ہوئے، عرض کی: میرے لیے اللہ تعالیٰ سے دعا کریں اور اس کے لیے برکت کی دعا کریں۔ کیونکہ میرا اس کے سوا کوئی نہیں۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اپنا دست مبارک اس کے سر پر رکھا اور ان کے لیے دعا فرمائی۔ اوسط میں طبرانی(2) لکھتے ہیں: عمیرہ بنت سہل سے صرف یہی سند روایت کی جاتی ہے۔ ابن کلبی اور ان کے پیروکاروں کا گمان ہے: یہ سہیل کے بھائی ہیں اور یہی دونوں اس جگہ کے مالک تھے جہاں مسجد ہے۔ البتہ ابن اسحاق کا قول ہے کہ مسجد کی جگہ والے سہل اور سہیل عمرو کے بیٹے تھے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۰) استیعاب (۱۰۹۰)\n(2) المعجم الکبیر (۶/۵۶۵)"}],[3524,"§۳۵۳۰ ۔ سہل بن رافع(1)\nبن خدیج ابن مالک بن غنم بن سری بن سلمہ بن انیف بلوی اراشی۔ بنی عمرو بن عوف انصاری کے حلیف۔ بقول ابن کلبی یہی صاع والے ہیں، جنہیں منافقوں نے طعنہ دیا تھا۔ ایسا ہی ابو عمر(2) نے لکھا ہے۔ میں کہتا ہوں: حرف حاء میں بیان ہوا ہے کہ ان کا نام حجاب ہے۔ محفوظ یہ ہے کہ ان کی کنیت ابو عقیل ہے۔ صرف نام میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۸۹) استیعاب (۱۰۹۱)\n(2) اسد الغابہ (۲/۲۲۳)"}],[3525,"§۳۵۳۱ ۔ سہل بن الربیع(1)\nبن عمرو بن عدی بن جشم بن حارثہ انصاری حارثی۔ اُحد میں شریک ہوئے۔ بقول عدوی: ابو عمر(2) نے ان کا ذکر کیا ہے۔ میں کہتا ہوں: یہی ابن حنظلیہ ہیں جن کا پہلے تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۱) استیعاب (۱۰۹۲) تجرید (۲/۲۲۴)\n(2) استیعاب (۲/۲۲۴)"}],[3526,"§۳۵۳۲ ۔ سہل بن رومی(1)\nبن وقش بن زغبہ انصاری اشہلی۔ اُحد میں شہادت پائی۔ ابو عمر(2) نے بحوالہ واقدی ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۲) استیعاب (۱۰۹۳)\n(2) استیعاب (۲/۲۲۴)"}],[3527,"§۳۵۳۳ ۔ سہل بن زید\nزید بن سہل میں ان کے متعلق تنبیہ ہو چکی ہے۔"],[3528,"§۳۵۳۴ ۔ سہل بن سعد(1)(2)(3)(4)\nبن مالک بن خالد بن ثعلبہ بن حارثہ بن عمرو بن خزرج بن ساعدہ انصاری ساعدی۔ مشہور صحابہ میں سے ہیں۔ بقول بعض: جسے ابن حبان نے نقل کیا ہے کہ ان کا نام حزن تھا۔ آپ علیہ السلام نے تبدیل کر دیا۔ انہوں نے نبی علیہ السلام سے ابی، عاصم بن عدی، عمرو بن عبہ سے اسی طرح مروان سے روایت کی ہے۔ حالانکہ مروان ان سے کم سن تھے۔ ان سے ان کے بیٹے عباس نے ابو حازم، زہری وغیرہ نے روایت لی ہے۔ زہری فرماتے ہیں: نبی صلی اللہ علیہ وسلم کی وفات کے وقت پندرہ(۱۵) برس کے تھے، اور مدینہ میں سب سے آخر میں یہی صحابی فوت ہوئے۔ اکانوے (۹۱ھ) میں بقول بعض اس سے پہلے فوت ہوئے۔ واقدی فرماتے ہیں: سو(۱۰۰) سال زندہ رہے، یہی قول ابو حاتم کا ہے، انہوں نے یہ اضافہ نقل کیا ہے کہ سو(۱۰۰) سال سے زائد زندہ رہے۔ ایک قول ہے چھیانوے (۹۶ھ) میں فوت ہوئے۔ ابن ابی داؤد کا گمان ہے کہ اسکندریہ میں وفات پائی۔ قتادہ سے مروی ہے، مصر میں فوت ہوئے۔ احتمال ہے کہ یہ قول وہم پر مبنی ہو درست یہ ہے کہ وہ ان کے بیٹے عباس تھے جن کا انتقال باہر ہوا۔","",{"fn":"(1) اسد الغابہ (۲۲۹۳) استیعاب (۱۰۹۴)\n(2) الثقات (۳/۱۶۸)\n(3) جامع المسانید (۶/۹۱)\n(4) الجرح والتعدیل (۴/۱۹۸)"}],[3529,"§۳۵۳۵ ۔ سہل بن صخر(1)\nبن واقد بن عضمہ بن ابی عوف بن عبد مناۃ بن تنجح بن عامر بن لیث بن بکر بن عبد مناۃ بن کنانہ لیثی۔ محمد بن سعد(2) وغیرہ نے ان کا نسب بیان کیا ہے۔ بقول بعض: سہیل، ابن شاہین کی روایت ہے کہ سہیل بن صخر فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے فرمایا: لڑکے! تمہارا کیا نام ہے؟ میں نے عرض کی: سہل۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “قریب آ جاؤ”۔ پھر میرے سر پر ہاتھ پھیرا اور مجھ سے فرمانے لگے: “سہل! اگر اللہ تعالیٰ تمہیں مال سے نوازے تو اس سے غلام خرید لینا کیونکہ اللہ تعالیٰ نے مردوں کی لونڈی غلام میں بھلائی رکھی ہے”۔ ابن مندہ نے اسی سند سے یہ روایت نقل کی اور اس میں فرمایا: انہیں شرف صحابیت حاصل ہے۔ یہ روایت غریب ہے جو ہمیں صرف اسی سند سے معلوم ہے۔ طبرانی(3) نے یہ روایت نقل کی تو ان کا نام سہیل بتایا۔ اور حدیث کو موقوف لکھا۔ بغوی موقوف حدیث نقل کرنے کے بعد لکھتے ہیں: مجھے ان کی بحوالہ نبی صلی اللہ علیہ وسلم کوئی روایت معلوم نہیں۔ لیکن ان کا نام سہل بتایا۔","",{"fn":"(1) اسد الغابہ (۲۲۹۵) استیعاب (۱۰۹۶) تجرید (۱/۲۴۴)\n(2) الطبقات (۷/۴۵)\n(3) المعجم الکبیر (۶/۵۶۴۱) جامع المسانید (۶/۱۶۱)"}],[3530,"§۳۵۳۶ ۔ سہل بن ابی صعصعہ انصاری(1)\nقین کے بھائی۔ بقول ابن سعد اور عدوی: اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۶)"}],[3531,"§۳۵۳۷ ۔ سہل بن عامر(1)\nبن سعد۔ بقول بعض سہیل بن عامر بن عمرو بن ثقیف انصاری۔ موسیٰ بن عقبہ اور عروہ نے بئر معونہ کے شہداء میں ان کا ذکر کیا ہے اور کہا ہے کہ سہل ان کے چچا تھے۔(2) ایک قول ہے: ان کے بھائی تھے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۸) استیعاب (۱۰۹۷)\n(2) تجرید (۱/۲۴۵)"}],[3532,"§۳۵۳۸ ۔ سہل بن عبید(1)\nبن قیس۔ سہل بن مالک میں ذکر ہوگا۔","",{"fn":"(1) المعجم الکبیر (۶/۵۶۴۶) (۶/۵۶۴۷)"}],[3533,"§۳۵۳۹ ۔ سہل بن عتیک(1)\nبن نعمان بن عمرو بن عتیک بن عمرو بن مبذول بن مالک۔ موسیٰ بن عقبہ، ابن اسحاق(2) اور عروہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ جبکہ ابو معشر نے ان کے والد کا نام عبید بتایا ہے اور ابن مندہ نے بھی ان کا اتباع کیا ہے۔ ابو نعیم نے ان کا تعاقب کیا ہے۔ ان سے پہلے طبرانی نے ابو معشر کی تردید کی ہے اور اس پر اتفاق نقل کیا ہے کہ ان کے والد کا نام عتیک ہے۔ ابن الاثیر(3) کی کتاب میں لکھا ہے۔ بقول بعض: ان کا نام سہیل ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۹۹) استیعاب (۱۰۹۸)\n(2) السیرۃ النبویۃ (۲/۷۶)\n(3) اسد الغابہ (۲/۳۹۲)"}],[3534,"§۳۵۴۰ ۔ سہل بن عتیک انصاری(1)\nابن مندہ نے ان میں اور سابقہ شخصیت میں فرق کیا ہے اور بطریق حمیدی ایک روایت نقل کی ہے کہ سیدنا ابن عباس رضی اللہ عنہما نے فرمایا: نبی صلی اللہ علیہ وسلم کے پاس جب سہل بن عتیک کا جنازہ لایا گیا تو آپ نے ان کی نماز جنازہ میں چار تکبیریں کہیں اور فاتحہ پڑھی۔(2) محمد بن حسن اور ضحاک نے اسے موقوف کہا ہے اور بحوالہ یحییٰ فرمایا: زہری کی غریب حدیث ہے۔ صرف اسی سند سے مشہور ہے۔ طبرانی نے الاوسط میں اسی سند سے نقل کی ہے جس کے الفاظ یہ ہیں: رسول اللہ صلی اللہ علیہ وسلم کے پاس جابر بن عتیک یا سہل بن عتیک کا جنازہ لایا گیا۔ یہ پہلے شخص تھے جن کا جنازہ جنازگاہ میں پڑھا گیا۔ پھر طویل حدیث نقل کی۔ اس میں یہ اضافہ ہے: “دوسری تکبیر کے بعد آپ نے اپنے آپ پر اور انبیاء پر درود بھیجا”۔ فرماتے ہیں: ابو عبادہ کے علاوہ کسی نے زہری سے یہ روایت نہیں نقل کی اور ان سے صرف یحییٰ بن یزید نوفلی نے، اس میں سلیم بن منصور منفرد ہے۔ ابن مندہ کے کلام سے، ان کی اور ان دونوں کی دعوئیٰ تفرد ابی عبادہ کی تردید ہوتی ہے۔ دوسرا اعتراض یہ ہے طبرانی نے یہ روایت یعقوب بن یزید سے بحوالہ زہری نقل کی لیکن اس میں ابن عتیک کا کوئی ذکر نہیں اور نہ یہ مذکور ہے کہ حدیث مرفوع ہے۔ بلکہ ابن عباس کی موقوف حدیث ہے اور سند کے لحاظ سے شاذ ہے کیونکہ اس بارے میں زہری سے بحوالہ اصحاب رسول صلی اللہ علیہ وسلم موقوف حدیث ہے۔ اور بروایت زہری، محمد بن سوید سے بواسطہ ضحاک بن قیس بحوالہ حبیب بن مسلمہ بھی موقوف ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۰۰)\n(2) اسد الغابہ (۲/۳۹۲)"}],[3535,"§۳۵۴۱ ۔ سہل بن عدی(1)\nبن زید بن عامر بن جشم بن حارث بن خزرج انصاری۔ ابو عمر(2) نے شہداء اُحد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۰۲) استیعاب (۱۰۹۹)\n(2) استیعاب (۲/۲۲۶)"}],[3536,"§۳۵۴۲ ۔ سہل بن عدی(1)\nبن مالک بن حرام بن خدیج بن معاویہ خزرجی۔ ان کے بھائیوں ثابت اور حارث کے حالات میں ان کا ذکر ہوا ہے کہ اُحد میں شریک ہوئے۔ طبرانی(2) کا بیان ہے: سیدنا عمر رضی اللہ عنہ نے بصرہ ابو موسیٰ اشعری رضی اللہ عنہ کو لکھا: سہل بن عدی کو امیر بنائیں۔ انہی کے ہاتھ پر کرمان فتح ہوا۔ عبد اللہ بن عبد اللہ بن عتبان نے ان کی مدد کی تھی۔ جن کا تذکرہ اپنی جگہ پر ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۳۰۱)\n(2) المعجم الکبیر (۶/۱۰۴۰)"}],[3537,"§۳۵۴۳ ۔ سہل بن عدی تمیمی(1)\nانصار کے حلیف۔ ابو الاسود نے بحوالہ عروہ شہداء یمامہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۰۳)"}],[3538,"§۳۵۴۴ ۔ سہل بن عمرو(1)\nبن عبد شمس العامری۔ سہیل کے بھائی۔ ابن سعد کا بیان ہے: فتح مکہ کے موقع پر مسلمان ہوئے، مدینہ کے رہائشی تھے، وہیں ان کی حویلی ہے۔ بقول ابو عمر(2): خلافت صدیقی یا فاروقی میں فوت ہوئے۔ میں کہتا ہوں: ان کی اہلیہ صفیہ بنت عمرو کے حالات میں ان کا ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۳۰۵) استیعاب (۱۱۰۰) (۲/۲۲۶)\n(2) استیعاب (۲/۲۲۶)"}],[3539,"§۳۵۴۵ ۔ سہل بن عمرو بن عدی(1)\nبن زید بن جشم بن حارثہ انصاری حارثی۔ بقول ابو عمر(2): اُحد اور بعد کے غزوات میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۳۰۶) استیعاب (۱۱۰۱)\n(2) استیعاب (۲/۲۲۶)"}],[3540,"§۳۵۴۶ ۔ سہل بن عمرو انصاری النجاری(1)\nہجرت کی حدیث میں ان کا ذکر ملتا ہے۔ ابن اسحاق(2) کا قول ہے (آپ صلی اللہ علیہ وسلم کی اونٹنی مسجد کے دروازے پر بیٹھ گئی جو ان دنوں بنی نجار کے دو یتیم بچوں سہل اور سہیل صاحبزادگان عمرو کا باڑہ تھا، وہ دونوں معاذ بن عفراء کی کفالت میں تھے۔ موسیٰ بن عقبہ بحوالہ ابن شہاب روایت کرتے ہیں مسجد کی جگہ بنی نجار کے دو یتیم بچوں کی تھی جو اسعد بن زرارہ کی پرورش میں تھے۔ ان کا نام سہل اور سہیل تھا جو عمرو کے صاحبزادے تھے۔ سہیلی نے ان میں اور سابقہ میں بحوالہ ابن کلبی یہ تطبیق نقل کی ہے کہ وہ دونوں سہل اور سہیل، رافع کے بیٹے تھے اور ان کا نام رافع بن عمرو تھا۔ ابن شہاب اور ابن اسحاق کا قول زیادہ وزنی ہے۔ رہا یہ اختلاف کہ وہ کسی کی پرورش میں تھے، اس میں یوں تطبیق ممکن ہے کہ وہ دونوں ایک ساتھ دونوں کی زیر پرورش تھے۔ اسی بنا پر صحیح میں لکھا ہے نبی صلی اللہ علیہ وسلم نے فرمایا: “بنی نجار! مجھ سے اس جگہ کی قیمت لے لو”۔","",{"fn":"(1) اسد الغابہ (۲۳۰۴)\n(2) السیرۃ النبویۃ (۲/۱۰۵)"}],[3541,"§۳۵۴۷ ۔ سہل بن قرط انصاری\nاوی از بنی عمرو بن عوف۔ دار قطنی کا قول ہے: معاذہ بنت عبد اللہ سے شادی کی تھی۔ انہیں بیوہ چھوڑ کر فوت ہوئے تو حمیر بن عدی نے ان سے نکاح کیا۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ اس کی وضاحت معاذہ کے حالات میں بیان ہوگی۔"],[3542,"§۳۵۴۸ ۔ سہل بن قرظہ(1)\nبن قیس بن عنترہ بن امیہ بن زید بن مالک بن اوس۔ بقول طبری اور ابن شاہین: اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۳۰۷)"}],[3543,"§۳۵۴۹ ۔ سہل بن قیس(1)\nبن ابی کعب بن القین بن کعب بن سواد بن کعب بن سلمہ انصاری خزرجی سلمی۔ موسیٰ بن عقبہ وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ جبکہ ابن اسحاق نے شہداء اُحد میں ان کا ذکر کیا ہے۔ اُحد میں مشہور قبر والے یہی ہیں۔ والدہ کا نام نائلہ بنت سلامہ بن وقش اہلیہ تھا۔ ابن سعد(2) کا قول ہے: ان سہل کی اولاد سے ایک مرد اور ایک عورت بچی تھی۔","",{"fn":"(1) اسد الغابہ (۲۳۰۹) استیعاب (۱۱۰۲) تجرید (۱/۲۵۴)\n(2) الطبقات (۳/۱۱۹)"}],[3544,"§۳۵۵۰ ۔ سہل بن قیس مزنی(1)\nابن مندہ کی روایت ہے کہ سہل بن قیس نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے مال قرض میں دے دیا اس پر زکوٰۃ نہیں”۔ ابن مندہ(2) فرماتے ہیں: غریب حدیث ہے جو ہم اسی سند سے جانتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۱۰) تجرید (۱/۲۵۴)\n(2) مجمع الزوائد (۳/۷۹) کنز العمال (۱۵۸۴۷) الکامل فی الضعفاء (۶/۲۲۱۱) جامع المسانید (۶/۵۶۴۰)"}],[3545,"§۳۵۵۱ ۔ سہل بن قیس انصاری\nسیدنا حمزہ کے ساتھ مدفون ہیں۔ عمرو بن سہیل بن قیس کے حالات میں ذکر ہوگا۔ میرے خیال میں یہ سہل بن قیس بن ابی کعب ہیں جن کا تذکرہ پہلے ہو چکا ہے۔"],[3546,"§۳۵۵۲ ۔ سہل بن منجاب تمیمی(1)\nطبری(2) کا بیان ہے بنی تمیم کی زکوٰۃ وصول کرنے پر نبی صلی اللہ علیہ وسلم کے عامل تھے۔ نبی صلی اللہ علیہ وسلم کی وفات تک اسی عہدہ پر فائز رہے۔","",{"fn":"(1) اسد الغابہ (۲۳۱۲)\n(2) تاریخ طبری (۲/۲۶۸)"}],[3547,"§۳۵۵۳ ۔ سہل بن مالک(1)\nبن ابی کعب بن القین انصاری۔ کعب بن مالک مشہور شاعر کے بھائی۔ بقول ابن حبان(2): انہیں شرف صحابیت حاصل ہے۔ سیف بن عمر “الفتوح” کے آغاز میں لکھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب حجۃ الوداع سے واپس آئے تو منبر پر چڑھ کر یہ اعلان کیا: “لوگو! مجھے ابو بکر کی طرف سے کبھی کوئی اذیت نہیں پہنچی۔” (حدیث)۔ یہی روایت ابن شاہین اور ابو نعیم نے بطریق سہل طویل نقل کی ہے۔(3) اور ابن مندہ نے بطریق خالد بن عمرو اموی بحوالہ سہل انہی الفاظ میں نقل کر کے فرمایا: غریب ہے جسے ہم اسی سند سے جانتے ہیں۔ میں کہتا ہوں: خالد بن عمرو متروک ہے۔ اور اس کی روایت کردہ احادیث بے اصل ہوتی ہیں۔ ابو عوانہ اور طحاوی کی بحوالہ عبد الرحمن بن کعب بن مالک انہوں نے اپنے چچا کے حوالہ سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے ان لوگوں کو عورتوں اور بچوں کے قتل سے منع کیا جو ابن ابی الحقیق یہودی کو قتل کرنے گئے تھے۔ اگر یہ روایت محفوظ ہے تو احتمال ہے کہ ان کے چچا کا نام سہل ہے، لیکن یہ روایت ابو عوانہ اور طحاوی نے دوسری دو سندوں سے بواسطہ زہری انہوں نے عبد الرحمن سے بحوالہ اپنے والد نقل کی ہے۔ دمیاطی کا گمان ہے کہ سہل بن یوسف کے دادا سہل بن قیس بن ابی کعب ہیں جن کا تذکرہ ابھی ہوا ہے۔ اس کی تردید اس روایت سے ہوتی ہے جو ہم نے فوائد ابو نعیم میں نقل کی ہے۔ اسی طرح ابن عبد البر(4) کا گمان ہے کہ یہ سہل بن مالک بن عبید بن قیس انصاری ہیں۔ ابو عمر نے ان کا ذکر کیا ہے کہ “انہیں سہل بن عبید بن قیس کہا جاتا ہے”۔ ان میں سے ایک بھی صحیح نہیں۔ فرماتے ہیں: بقول بعض: حجازی تھے، مدینہ میں رہائش پذیر تھے۔ ان کی روایت کردہ حدیث کا مدار خالد بن عمرو پر ہے، جو متروک ہے۔ نیز ان کی حدیث کی سند میں مجہول اور ضعیف راوی ہے۔ اس کا مدار سہل بن یوسف بن سہل بن مالک پر یا مالک بن یوسف بن سہل بن عبید پر ہے۔ بہر کیف یہ حدیث منکر ہے یا موضوع ہے۔ اس میں طبرانی سے وہم واقع ہوا ہے۔ انہوں نے مقدمی کے طریق سے بواسطہ یوسف بن محمد بن بحوالہ سہل بن یوسف روایت کی ہے۔ ضیاء مقدسی کو اسی طریق سے دھوکا ہوا ہے چنانچہ انہوں نے “مختارہ” میں یہ حدیث اسی طریق سے نقل کی ہے جو وہم ہے کیونکہ اس کی سند سے دو شخص چھوٹ گئے ہیں۔ وجہ یہ ہے کہ علی بن محمد بن یوسف نے یہ حدیث قنان بن ابی لباب سے بواسطہ خالد بن عمرو بحوالہ سہل سنی ہے۔ دار قطنی نے “الافراد” میں یہ اعتماد ظاہر کیا ہے کہ خالد بن عمرو اس روایت کو سہل سے نقل کرنے میں منفرد ہے۔ لیکن سیف بن عمرو کے طریق سے اس کی تردید ہوتی ہے۔ ابن قانع کو بھی اس میں خبط ہوا چنانچہ انہوں نے مذکورہ حدیث “سہل بن حذیف” کی سند میں شامل کی ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۱۱) استیعاب (۱۱۰۳)\n(2) الثقات (۳/۱۷۰)\n(3) المعجم الکبیر (۶/۵۶۴۰)\n(4) استیعاب (۲/۲۲۷)"}],[3548,"§۳۵۵۴ ۔ سہل بن نسیر\nبن عنبس انصاری اوی ظفری ان کے والد کے حالات میں ان کا تذکرہ ہوگا۔"],[3549,"§۳۵۵۵ ۔ سہل بن وہب\nبن ربیعہ۔ وہی ابن بیضاء ہیں جن کا پہلے ذکر ہوا ہے۔"],[3550,"§۳۵۵۶ ۔ سہل(1)\nبے نسبت۔ مولا بنی ظفر۔ بقول ابن کلبی، ابن سعد اور ابن شاہین غزوہ اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۹۷) استیعاب (۱۱۰۳)"}],[3551,"§۳۵۵۷ ۔ سہل بن فلان\nبن عبادہ انصاری خزرجی۔ سعد بن عبادہ کے بھتیجے۔ طبرانی کی روایت ہے کہ صحابی رسول صلی اللہ علیہ وسلم نے فرمایا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “انصار کا بہترین گھرانہ بنی نجار کا ہے”۔ سعد بن عبادہ رضی اللہ عنہ (حدیث)(1) کو علم ہوا تو انہیں کچھ قلبی صدمہ ہوا، فرمانے لگے: میرے گدھے پر پالان رکھو میں نبی صلی اللہ علیہ وسلم کے پاس جاتا ہوں۔ تو سیدنا سہل کے بھتیجے نے کہا: کیا آپ رسول اللہ صلی اللہ علیہ وسلم کی بات واپس کرنا چاہتے ہیں؟ جبکہ اللہ اور رسول صلی اللہ علیہ وسلم کو زیادہ علم ہے تو آپ نے حکم دیا تو اس کا پالان اتار لیا گیا۔ اس کی اصل مسلم میں ہے، ابن ابی خیثمہ نے بھی اسے نقل کیا ہے، مجھے کتابوں مسندوں اور انصار کے انساب میں سہل کا ذکر نہیں ملا۔ فاللہ اعلم","",{"fn":"(1) مسلم کتاب فضائل الصحابہ (۱۷۹)"}],[3552,"§۳۵۵۸ ۔ سہل انصاری (ایاس کے والد - بے نسبت)\nامام بخاری رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے۔ حسن بن سفیان، بغوی اور باوردی کی بطریق ابو حازم روایت ہے کہ وہ ایاس بن سہل انصاری جو بنی ساعدہ سے تعلق رکھتے ہیں، ان کی مسجد میں بیٹھے۔ وہ کہنے لگے: کیا میں تمہیں اپنے والد کے حوالہ سے حدیث نہ سناؤں؟ میں نے کہا: کیوں نہیں۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “میں صبح کی نماز پڑھ کر سورج نکلنے تک اپنی مجلس میں بیٹھا رہا کروں یہ مجھے اللہ تعالیٰ کی راہ میں عمدہ گھوڑے باندھنے سے زیادہ پسند ہے۔”(1) اس کی سند میں محمد بن ابی حمید ہے جو ضعیف راوی ہے۔ بغوی کی کتاب میں محمد بن ابراہیم لکھا ہے، لکھتے ہیں: مجھے معلوم نہیں یہ کون ہیں، میرا خیال ہے یہ وہی ہیں۔","",{"fn":"(1) کنز العمال (۳۵۵۴) المطالب العالیہ (۲۸۵)"}],[3553,"§۳۵۵۹ ۔ سہل انصاری (دوسرے ہیں)\nاخبار مدینہ میں عمر بن شبہ لکھتے ہیں: یہ آیت “اس مسجد میں ایسے مرد ہیں جو پاک صاف رہنا پسند کرتے ہیں”(1) قباء کے ان لوگوں کے بارے میں نازل ہوئی جو قضاء حاجت کے بعد پانی سے استنجاء کرتے تھے۔","",{"fn":"(1) سورۃ التوبۃ: ۱۰۸"}],[3554,"§۳۵۶۰ ۔ سہم ابن عمرو الاشعری\nابن سعد نے ان کا ذکر کیا ہے کہ ابو موسیٰ کے ساتھ کشتی میں آئے پھر شام فروکش ہوئے۔"],[3555,"§۳۵۶۱ ۔ سہم بن مازن\nیا ابن مدرک۔ یزید بن سنان کے دادا۔ زید نامی حضرات میں ان کا ذکر ہوا ہے۔"],[3556,"§۳۵۶۲ ۔ سہیل ابن بیضاء(1)\nان کا نسب ان کے بھائی سہل کے حالات میں بیان ہو چکا ہے کہ بیضاء ان دونوں کی والدہ ہیں۔ ابن اسحاق(2) کا بیان ہے بدر میں شریک ہوئے اور نو (۹ھ) میں فوت ہوئے۔ اسی طرح موسیٰ بن عقبہ نے بدری صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن کلبی کا گمان ہے: یہی بدر میں قید ہوئے تو ابن مسعود نے ان کی گواہی دی۔ واقدی نے اس کی تردید کرتے ہوئے فرمایا ہے: وہ ان کے بھائی سہل ہیں، ابن کلبی کے قول کی تائید طبرانی کی اس روایت سے ہوتی ہے۔ جو صحیح سند کے ذریعہ بواسطہ ابو عبیدہ بن عبد اللہ بن مسعود انہوں نے بحوالہ اپنے والد نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر کے روز فرمایا: “ان کافروں میں سے کوئی بھی فدیے اور گردن اڑائے بغیر نہیں چھوٹ سکتا، عبد اللہ رضی اللہ عنہ(3) عرض کرنے لگے: صرف سہیل ابن بیضاء، میں نے انہیں اسلام کا ذکر خیر کرتے سنا تھا۔ آپ نے فرمایا: صرف سہیل ابن بیضاء۔ ابن حبان نے اپنی صحیح میں بحوالہ سہیل ابن بیضاء جن کا تعلق بنی عبد الدار تھا، فرمایا: ایک دفعہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی سفر میں تھے، پھر ایک واقعہ ذکر کیا۔ طبرانی میں یہ روایت اسی سند سے بحوالہ سہل ابن بیضاء منقول ہے کہ ایک دفعہ کسی سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور سہیل ابن بیضاء رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اونٹ پر سوار تھے۔ اچانک آپ نے فرمایا: “سہیل ابن بیضاء”(4) اور پھر اپنی آواز بلند کی۔ (حدیث)۔ ابن ابی حاتم(5) بحوالہ اپنے والد روایت کرتے ہیں یہ مرسل ہے، کیونکہ سعید بن المسیب نے سہیل کو نہیں دیکھا، یہی معتبر ہے۔ اس واسطے کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے سہیل ابن بیضاء کا جنازہ مسجد میں ہی پڑھایا۔ (مسلم)۔ اس سے معلوم ہوا کہ وہ نبی صلی اللہ علیہ وسلم کی حیات میں فوت ہوئے۔ ابن سعد(6) نے ان کی تاریخ وفات ۹ھ لکھی ہے، جیسا کہ پہلے بیان ہو چکا ہے۔ ابن مندہ فرماتے ہیں: سعد بن الصلت، عبد اللہ بن انیس بحوالہ سہیل ابن بیضاء روایت کرتے ہیں۔ میں کہتا ہوں: اسی طرح بغوی کے ہاں ہے، اکثریت جس نے یہ روایت نقل کی ہے انہوں نے ابن انیس کا ذکر نہیں کیا۔ مسند احمد میں یہ روایت تین طرق سے بواسطہ یزید بن الہادی مروی ہے، اس میں عبد اللہ بن انیس کا ذکر نہیں۔ اور بعض نے سعد بن الصلت کا ذکر بھی نہیں کیا۔ بعض نے اس میں محمد بن ابراہیم کا نام ساقط کر دیا ہے۔ صحیح میں حدیث انس رضی اللہ عنہ سے مروی ہے جس میں انہیں شراب پلانے والے کا ذکر ہے، جب شراب کی حرمت نازل ہوئی تو لوگوں نے کہا: اسے بہا دو! تو ان میں کسی طریق میں سہیل ابن بیضاء کا ذکر بھی ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۱۵) استیعاب (۱۱۰۵)\n(2) السیرۃ النبویۃ (۱/۲۵۶) (۲/۲۴۷)\n(3) ترمذی کتاب تفسیر القرآن باب و من سورۃ الانفال (۳۰۸۴) مسند احمد (۱/۳۸۴)\n(4) المستدرک (۳/۶۳۰) المعجم الکبیر (۶/۲۵۷)\n(5) الجرح والتعدیل (۴/۲۴۵)\n(6) الطبقات الکبریٰ (۳/۳۰۲)"}],[3557,"§۳۵۶۳ ۔ سہیل بن حنظلہ(1)\nبقول بعض: ابن حنظلیہ العبشمی حسن بن سفیان بطریق قتادہ بواسطہ ابو العالیہ بحوالہ سہیل ابن حنظلیہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جو قوم بھی اللہ تعالیٰ کا ذکر کرنے کے لیے اکٹھی ہو جب وہ جانے لگتے ہیں تو فرشتے ان سے کہتے ہیں: تمہاری مغفرت کر دی گئی۔” ابو نعیم(2) لکھتے ہیں: مسلم بن ابراہیم بواسطہ ابان، قتادہ سے پھر سہیل ابن حنظلیہ روایت کرتے ہیں۔ میں کہتا ہوں: یہ روایت امام بخاری رحمہ اللہ نے مسلم سے سہل ابن حنظلیہ انصاری کے حالات میں نقل کی ہے۔ پھر فرمایا: بقول بعض: یہ پہلے کے علاوہ ہیں۔ ابو الفرج کا بیان ہے کہ سہیل ابن الحنظلیہ غنوی ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۱۶)\n(2) المعجم الکبیر (۶/۶۰۳۹) مجمع الزوائد (۱۰/۷۷)"}],[3558,"§۳۵۶۴ ۔ سہیل بن حنظلہ\nبن الطفیل العامری۔ عامر بن الطفیل کے بھتیجے۔ قسم ثالث میں ان کا ذکر ہوگا۔ ان کے واقعے کے سیاق و سباق سے معلوم ہوتا ہے یہ صحابی ہیں۔"],[3559,"§۳۵۶۵ ۔ سہیل بن خلیفہ المنقری\nابو سوید۔ ابن مندہ نے ان کا ذکر کیا ہے۔"],[3560,"§۳۵۶۶ ۔ سہیل بن دغدغ\nوہی ابن بیضاء ہیں، بیضاء لقب ہے۔"],[3561,"§۳۵۶۷ ۔ سہیل بن رافع(1)\nبن ابی عمرو بن عائذ بن ثعلبہ بن غنم انصاری۔ ابن اسحاق نے شرکاء بدر و اُحد میں ان کا ذکر کیا ہے۔ بقول بعض: باڑے کے دو مالکوں میں سے ایک یہ تھے۔","",{"fn":"(1) اسد الغابہ (۲۳۱۸) استیعاب (۱۱۰۷)"}],[3562,"§۳۵۶۸ ۔ سہیل بن سعد ساعدی(1)\nسہل کے والد، ان کے بھائی کا تذکرہ ہو چکا ہے۔ ابن مندہ کی روایت ہے کہ سہیل بن سعد، جو سہل کے بھائی ہیں، نے فرمایا: میں مسجد میں داخل ہوا تو نبی صلی اللہ علیہ وسلم نماز پڑھ رہے تھے، میں نے بھی نماز پڑھ لی۔ نماز کے بعد آپ صلی اللہ علیہ وسلم نے مجھے رکوع کرتے دیکھا تو فرمایا: “یہ کونسی دو رکعتیں ہیں؟” میں نے بتایا تو آپ صلی اللہ علیہ وسلم خاموش ہو گئے۔ آپ صلی اللہ علیہ وسلم کی یہ عادت تھی جب کسی بات پر راضی ہوتے تو اکثر خاموش رہتے۔ اس کی سند میں عمرو بن قیس ہے۔ ابو نعیم نے لکھا ہے کہ انہیں اس میں وہم ہوا ہے۔ درست سند یوں ہے: قیس بن عمرو سے مروی ہے۔ میں کہتا ہوں: اگر یہ روایت انہیں یاد ہے تو صحیح ہے، مختلف واقعات ہونے میں کوئی ممانعت نہیں۔","",{"fn":"(1) المستدرک (۱/۲۷۵) المصنف لابن ابی شیبہ (۲/۱۵۴) السنن الکبریٰ (۲/۴۵۶) (۲/۴۸۳)"}],[3563,"§۳۵۶۹ ۔ سہیل بن السمط\nسہیل ابن بیضاء کی حدیث میں بروایت بغوی ان کا ذکر آتا ہے۔ خطیب نے المتفق میں بطریق ابی القاسم البغوی روایت کی ہے کہ سہیل بن السمط نے فرمایا: ایک دفعہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی سفر میں تھے، سہیل ابن بیضاء آپ صلی اللہ علیہ وسلم کے ساتھ سوار تھے۔ آپ علیہ السلام نے فرمایا: “سہیل! اور پھر اپنی آواز بلند کی...”۔ (حدیث)۔ یہی روایت انہوں نے پہلے بطریق عبد العزیز بن ابی حازم بحوالہ سعد نقل کی ہے، لیکن اس میں کہا: سہل ابن بیضاء سے مروی ہے، ایک دفعہ ہم سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور سہیل ابن بیضاء آپ صلی اللہ علیہ وسلم کے ساتھ سواری پر بیٹھے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “سہیل ابن بیضاء! اور دو یا تین بار آواز بلند کی، ہر بار سہیل انہیں جواب دیتے۔ جونہی لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کی آواز سنی تو قافلے میں کھلبلی مچ گئی۔ وہ سمجھے کہ آپ صلی اللہ علیہ وسلم ہم سے مخاطب ہیں۔ چنانچہ جو آگے تھے بیٹھ گئے اور جو پیچھے رہ گئے وہ آ ملے یہاں تک کہ سارے اکٹھے ہو گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جو لا الٰہ الا اللہ کی گواہی دیتا ہے، اللہ تعالیٰ اس کے لیے جہنم حرام کر دیتا اور جنت اس کے لیے لازم کر دیتا ہے۔” امام احمد رحمہ اللہ(1) نے یہی روایت نقل کی لیکن یزید کے شیخ میں اختلاف کیا اور ان کے بدلے محمد بن ابراہیم کہا کہ بحوالہ سہیل ابن بیضاء مروی ہے: رسول اللہ صلی اللہ علیہ وسلم نے ایک رات آواز دی جب میں آپ صلی اللہ علیہ وسلم کے ساتھ سوار تھا... پھر وہ حدیث ذکر کی۔ اس حدیث کی سند میں بہت زیادہ اختلاف ہے۔ لیکن اس کے کسی طریق میں ماسواے سعید بن سلمہ کی روایت کے، سہیل بن سمط کا ذکر نہیں۔ میں نے سہیل بن سمط کا نام آخری قسم میں درج کیا تھا۔ پھر اس حدیث کے سیاق میں غور کیا تو اس کا احتمال مل گیا، اس لیے میں نے اس قسم میں نقل کر دیا۔ واللہ المستعان۔","",{"fn":"(1) مسند احمد (۳/۴۵۱) المستدرک (۳/۶۳۰) مجمع الزوائد (۱/۱۶)"}],[3564,"§۳۵۷۰ ۔ سہیل بن عامر\nبن سعد، سہل میں ذکر ہوا ہے۔"],[3565,"§۳۵۷۱ ۔ سہیل بن عتیک\nبقول بعض: ابن عبید، سہل میں ذکر ہوا ہے۔"],[3566,"§۳۵۷۲ ۔ سہیل بن عدی ازدی(1)\nازد شنوءۃ۔ بنی عبد الاشہل کے حلیف۔ بقول ابو عمر(2): یمامہ میں شہید ہوئے، ان کے بھائی سہل کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۲۳) استیعاب (۱۱۰۷)\n(2) استیعاب (۲/۲۲۷)"}],[3567,"§۳۵۷۳ ۔ سہیل بن عمرو (باڑے والے)(1)\nان کا تذکرہ ان کے بھائی سہل کے ساتھ پہلے ہو چکا ہے۔ ابن کلبی کا گمان ہے یہ سیدنا علی رضی اللہ عنہ کے ساتھ جنگ صفین میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۳۲۴) استیعاب (۱۱۱۰)"}],[3568,"§۳۵۷۴ ۔ سہیل بن عمرو(1)\nبن عبد شمس بن عبد ود بن نصر بن مالک بن حسل بن عامر بن لؤی قریشی عامری۔ ابو یزید قریش کے خطیب۔ بقول امام بخاری رحمہ اللہ(2): مکہ کے رہائشی تھے، پھر مدینہ رہنے لگے۔ ابن سمیع نے شام فروکش ہونے والوں کے پہلے طبقے میں ان کا ذکر کیا ہے۔ حدیبیہ میں صلح کی ذمہ داری ان ہی کو سونپی گئی تھی۔ ان کی گفتگو اور نبی صلی اللہ علیہ وسلم سے شرائط میں کسی کا ذکر صحیحین وغیرہ میں ہے۔ حدیث ابن عمر رضی اللہ عنہما میں ان لوگوں میں ان کا ذکر ہے جن کے لیے رسول اللہ صلی اللہ علیہ وسلم نے قنوت میں بد دعا کی تھی۔ جس پر یہ آیت نازل ہوئی: “اس بارے میں آپ کو کچھ اختیار نہیں”۔ امام احمد رحمہ اللہ(3) نے اپنی روایت میں یہ اضافہ نقل کیا ہے کہ یہ سب تائب ہو گئے تھے۔ حمید بن زنجویہ نے “کتاب الاموال” میں بطریق ابن ابی حسین روایت کی ہے جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ فتح کیا تو بیت اللہ میں داخل ہوئے، پھر باہر تشریف لائے اور بیت اللہ کی چوکھٹ پر ہاتھ رکھ کر فرمانے لگے: تم لوگ کیا کہتے ہو؟ تو سہیل بن عمرو نے کہا: ہم بھلائی کی بات کرتے، اور اچھا گمان رکھتے ہیں۔ آپ صلی اللہ علیہ وسلم کرم نواز بھائی اور کرم نواز بھائی کے بیٹے ہیں۔ آپ کو دسترس حاصل ہو چکی ہے۔ آپ علیہ السلام نے فرمایا: “میں تو وہی بات کہوں گا جو میرے بھائی یوسف علیہ السلام نے کہی: آج تم پر کچھ ملامت نہیں”۔ ابن اسحاق(4) نے ان تالیف قلبی والوں میں ان کا ذکر کیا ہے جنہیں نبی صلی اللہ علیہ وسلم نے سو اونٹ دیے تھے۔ ابن ابی حاتم(5) بحوالہ الشافعی روایت کرتے ہیں کہ سہیل جب اسلام لائے تو ان کا اسلام قابل تعریف تھا۔ بیہقی نے دلائل میں بحوالہ محمد بن الحنفیہ روایت کی ہے کہ صلح حدیبیہ کے موقع پر سیدنا عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے عرض کی: “مجھے اجازت دیجیے میں سہیل کی بتیسی توڑ دوں تاکہ وہ ہم سے گفتگو نہ کر سکے”۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “رہنے دو، شاید یہی بتیسی کسی دن تمہیں خوش کر دے”۔(6) جب نبی کریم صلی اللہ علیہ وسلم کا انتقال ہوا تو سہیل بن عمرو نے کھڑے ہو کر لوگوں سے کہا: “جو شخص محمد (صلی اللہ علیہ وسلم) کی عبادت کرتا تھا تو اس کا معبود فوت ہو چکا ہے اور جو اللہ تعالیٰ کی عبادت کرتا تھا تو اللہ تعالیٰ زندہ ہے، جسے کبھی موت نہیں آئے گی”۔ اس کا پہلا حصہ یونس بن بکیر نے مغازی ابن اسحاق میں بواسطہ ان کے بحوالہ محمد بن عمرو بن عطاء نقل کیا ہے، جو محاملیات میں بطریق سعید بن ابی ہند بواسطہ عمر بحوالہ عائشہ رضی اللہ عنہا موصولاً مروی ہے۔ ابن خالویہ کا بیان ہے سیدنا عمر رضی اللہ عنہ نے بتیسی کا ذکر اس وجہ سے کیا کہ سہیل کا اوپر والا ہونٹ پھٹا ہوا تھا اور جس شخص کا اوپر والا ہونٹ چوڑا ہو اگر اس کے سامنے کے دانت ٹوٹ جائیں تو وہ بات نہیں کر سکتا۔ یہی اس میں راز ہے۔ واقدی نے بحوالہ مولا سہیل بحوالہ سہیل روایت کی ہے، فرماتے ہیں: بدر کے روز میں نے زمین و آسمان کے درمیان نشان زدہ سیاہ و سفید رنگوں والے گھوڑوں پر مردوں کو دیکھے جو جنگ کر کے قید کر رہے تھے۔ ابو قرہ بطریق ابن ابی حسین روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے انہیں آب زمزم کا ہدیہ بھیجا۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں اور باوردی نے بطریق حمید بحوالہ حسن روایت کی ہے کہ مہاجرین و انصار سیدنا عمر رضی اللہ عنہ کے دروازے پر تھے جنہیں ان کے مراتب کے لحاظ سے اجازت دے رہے تھے وہیں طلقاء (فتح مکہ کے موقع پر ایمان لانے والوں) کی ایک جماعت موجود تھی۔ تو یہ لوگ ایک دوسرے کا منہ تکنے لگے۔ سیدنا سہیل بن عمرو نے فرمایا: اپنے آپ کو کوسو! لوگوں کو اسلام کی دعوت دی گئی اور تمہیں بھی لوگوں نے جلدی کی اور تم نے تاخیر کی، اس وقت تمہارا کیا حال ہوگا جب جنت کے دروازوں پر بلایا جائے گا۔ اس کے بعد وہ جہاد(7) میں شامل ہو گئے۔ ابن المبارک نے “کتاب الجہاد” میں اس سے مکمل روایت کی ہے۔ ابن شاہین کی بطریق ثابت البنانی روایت ہے کہ سہیل بن عمرو نے فرمایا: اللہ کی قسم! جس جس جگہ میں مشرکین کے ساتھ مل کر مسلمانوں کے خلاف کھڑا ہوا وہیں مسلمانوں کے ساتھ مل کر مشرکین کے خلاف لڑوں گا اور جیسی رقم میں نے مشرکین کی حمایت میں خرچ کی ویسی ہی مسلمانوں پر خرچ کروں گا، تاکہ میری ایک نیکی دوسری برائی کے پیچھے لگ جائے۔ ابن ابی خیثمہ کی روایت ہے، سہیل کی وفات طاعون سے اٹھارہ (۱۸ھ) میں ہوئی۔ بقول بعض: یرموک میں شہید ہوئے۔ خلیفہ کا قول ہے: مرج الصفر میں شہادت پائی، پہلا قول زیادہ افراد کا ہے کہ وہ طاعون سے فوت ہوئے۔ یہی روایت ابن سعد نے اپنی سند سے بحوالہ ابو سعد بن ابی فضالہ جو صحابی رسول صلی اللہ علیہ وسلم ہیں روایت کی ہے، فرمایا: میں اور سہیل بن عمرو اکٹھے شام گئے، میں نے انہیں فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “تم میں سے کسی کا اپنی عمر کی ایک گھڑی اللہ کی راہ میں کھڑے ہونا اپنے گھر میں عمل کرنے سے بہتر ہے۔”(8) سہیل فرماتے ہیں: اسی بنا پر میں مرتے دم تک جہاد میں رہتا ہوں اور مکہ لوٹ کر نہیں جاؤں گا۔ راوی کا بیان ہے کہ وہ شام میں ہی مقیم رہے بالآخر طاعون عمواس میں فوت ہو گئے۔","",{"fn":"(1) اسد الغابہ (۲۳۲۵) استیعاب (۱۱۱۱)\n(2) التاریخ الکبیر (۲/۱۰۵)\n(3) سورۃ آل عمران (۱۲۸)\n(4) سورۃ یوسف (۹۲)\n(5) الجرح والتعدیل (۴/۲۴۶)\n(6) دلائل النبوۃ (۶/۳۶۷) الدر المنثور (۲/۸۱)\n(7) المعجم الکبیر (۶/۶۰۳۸)\n(8) مسند احمد (۹۷۶۹)"}],[3569,"§۳۵۷۵ ۔ سہیل بن عمرو الجمحی\nتالیف قلبی والوں میں شمار ہوتے ہیں۔ جس کے متعلق عبد الرحمن بن یربوع کے حالات میں حدیث گزر چکی ہے۔"],[3570,"§۳۵۷۶ ۔ سہیل بن قیس(1)\nبن ابی کعب انصاری۔ کعب کے چچا زاد بھائی، ابن کلبی کا بیان ہے: بدر میں شریک ہوئے۔ پہلے سہل کا تذکرہ ہو چکا ہے، معلوم نہیں آیا دونوں ایک ہیں یا جدا جدا دو شخص ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۲۶) تجرید (۱/۲۴۷)"}],[3571,"§۳۵۷۷ ۔ سہیل الثقفی(1)\nبقول بعض: عمرو بن سفیان۔ حاء کی قسم رابع میں حارث بن بدل میں ان کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) المعجم الکبیر (۶/۱۰۵)"}],[3572,"§۳۵۷۸ ۔ سواء بن حارث محاربی(1)\nابن سعد کا بحوالہ ابو جزہ سعدی کا بیان ہے: محارب کا ۱۰ افراد پر مشتمل ایک وفد آیا، جن میں سواء بن حارث اور ان کا بیٹا خزیمہ بن سواء تھا۔ یہ لوگ اسلام لے آئے اور انہیں بھی آپ صلی اللہ علیہ وسلم نے ویسے ہی نوازا جیسے وفود کو تحائف وغیرہ سے نوازتے تھے۔ طبرانی(2) اور ابن شاہین کی روایت ہے کہ عمارہ بن خزیمہ بحوالہ اپنے والد نقل کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے سواء بن حارث سے گھوڑا خریدا تھا، جس کا انہوں نے انکار کر دیا، تو خزیمہ بن ثابت نے آپ صلی اللہ علیہ وسلم کے بارے میں گواہی دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “خزیمہ تم کیسے گواہی دے رہے ہو جبکہ موقع پر تم موجود نہ تھے؟” عرض کی: “اللہ کے رسول صلی اللہ علیہ وسلم! آپ کی سچائی کی وجہ سے، کیونکہ آپ صلی اللہ علیہ وسلم صرف حق سچ بات ہی کہتے ہیں”۔ تو آپ صلی اللہ علیہ وسلم نے انہیں یہ تمغہ امتیاز دیتے ہوئے فرمایا: “خزیمہ جس حق میں یا جس کے خلاف گواہی دے دے تو اس کے لیے کافی ہے (یعنی اکیلے ان کی گواہی دو آدمیوں کے برابر ہے)”۔ یہی روایت ابن شاہین نے نقل کی تو کہا: سواء بن قیس سے مروی ہے جو میرے خیال میں وہم ہے۔ اسی طرح ابن شاہین اور ابن مندہ ایک اور سند سے بواسطہ زید بن حجاب بحوالہ مطلب بن عبد اللہ روایت کرتے ہیں کہ میں نے بنی حارث بن سواء سے پوچھا: تمہارے ہی بڑے نے رسول اللہ صلی اللہ علیہ وسلم کے سودے کا انکار کیا تھا؟ وہ کہنے لگے: ایسا مت کہو۔ آپ صلی اللہ علیہ وسلم نے انہیں ایک اونٹ دیا تھا اور فرمایا: “اللہ تعالیٰ تمہیں اس میں برکت دے گا”۔ چنانچہ اسی کی کمائی سے ہم نے اونٹوں کا چرواہا اور پانی ڈھونے کا اونٹ حاصل کیا۔ اصل واقعہ جو قدرے طویل ہے ابو داؤد اور نسائی نے نقل کیا ہے۔ یعنی سند عالی طریق سے ہمیں محمد بن یحییٰ بن ذہلی کے جزو میں بطریق زہری لکھی ہوئی ملی ہے کہ عمارہ بن خزیمہ انصاری نے بحوالہ اپنے چچا جو صحابی ہیں مجھ سے بیان کیا، آپ صلی اللہ علیہ وسلم نے ایک دیہاتی سے اونٹ خریدا تو وہ اعرابی آپ سے نیا سودا کرنے لگا تاکہ اپنے گھوڑے کی قیمت وصول کر لے، آپ علیہ السلام لیے قدم بھر کر چل دیئے۔ پھر لوگ آ کر اس سے بھاؤ کرنے لگے۔ پھر وہ حدیث اور واقعہ نقل کیا۔ اسی میں ہے وہ اعرابی کہنے لگا: کوئی گواہ لائے جو یہ گواہی دے کہ یہ گھوڑا میں نے آپ کے ہاتھ بیچ دیا تھا۔ مسلمانوں میں سے جو شخص آتا وہ یہی کہتا: ارے تیرا ناس ہو! نبی صلی اللہ علیہ وسلم حق بات ہی کہتے ہیں۔ اتنے میں خزیمہ بن ثابت آگئے، انہوں نے نبی صلی اللہ علیہ وسلم کی یاد دہانی اور اعرابی کی تردید سن کر فورا عرض کی: “میں گواہی دیتا ہوں کہ آپ صلی اللہ علیہ وسلم نے اس سے گھوڑا خرید لیا تھا۔ نبی صلی اللہ علیہ وسلم سیدنا خزیمہ رضی اللہ عنہ کی طرف متوجہ ہو کر فرمانے لگے: “تم کیسے گواہی دیتے ہو؟”(3) عرض کی: آپ صلی اللہ علیہ وسلم کو سچا جاننے کی وجہ سے۔ تو نبی صلی اللہ علیہ وسلم نے خزیمہ رضی اللہ عنہ کی گواہی دو مردوں کے برابر قرار دی۔","",{"fn":"(1) اسد الغابہ (۲۳۲۷) تجرید (۱/۲۴۷)\n(2) المعجم الکبیر (۶/۳۷۲۰)\n(3) ابو داؤد کتاب الاقضیہ (۳۶۰۷) نسائی کتاب البیوع (۴۶۶۱) مسند احمد (۵/۲۱۶) الطبقات (۴/۹۱)"}],[3573,"§۳۵۷۹ ۔ سواء بن الحارث\nبن ظالم بن حداد بن ذہل بن طریف بن محارب بن محارب بن خصفہ، عاصم کے بھائی۔ عاصم کے حالات میں ان کی حدیث بیان ہوگی، لہذا لکھ لیا جائے۔ آیا وہ یہی سواء بن حارث ہیں یا کوئی اور؟ شاید یہ پہلے والے ہیں۔"],[3574,"§۳۵۸۰ ۔ سواء بن خالد\nاپنے بھائی عتبہ بن خالد کے ساتھ ان کا ذکر ہوا ہے، وکیع نے بحوالہ الاعمش ان کا نام سوار بتایا ہے، پہلا معتبر ہے۔"],[3575,"§۳۵۸۱ ۔ سواد(1)\nابن زید بن ثعلبہ بن عبید بن عدی بن کعب بن سلمہ خزرجی۔ ابن کلبی کا بیان ہے بدر میں شریک ہوئے۔ بقول بعض: ان کا نام زریق، یزید یا ترزن ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۳۰)"}],[3576,"§۳۵۸۲ ۔ سواد بن عمرو(1)\nبن عطیہ بن خنساء بن مبذول بن عمرو بن غنم انصاری۔ بقول بعض: سوادہ۔ طبرانی کی روایت ہے کہ سواد بن عمرو انصاری نے فرمایا: میں نے عرض کی: “اللہ کے رسول صلی اللہ علیہ وسلم! میں ایسا شخص ہوں جسے خوبصورتی اور جمال (یعنی اچھا پہننا، اچھا کھانا) پسند ہے...”۔ (حدیث) اسی میں ہے: “تکبر حق کو جھٹلانے اور لوگوں کو گھٹیا سمجھنے کا نام ہے۔”(2) امام بخاری رحمہ اللہ(3) فرماتے ہیں: ان کی حدیث مرسل ہے، یعنی ابن سیرین کا ان سے سماع نہیں۔ اسی طرح بغوی نے ان کی دوسری حدیث نقل کی ہے، جو بروایت حسن بصری ان سے مروی ہے اور اسے مرسلا نقل کیا کہ ان کا ان سے سماع نہیں۔ بعد والی شخصیت میں ان کا تذکرہ کروں گا۔","",{"fn":"(1) اسد الغابہ (۲۳۳۱) استیعاب (۱۱۱۲) تجرید (۱/۲۴۷)\n(2) مسلم کتاب الایمان باب تحریم الکبر و بیانہ (۱۴۷) ترمذی کتاب البر والصلۃ باب ما جاء فی الکبر (۱۹۹۹) اتحاف السادۃ المتقین (۸/۳۳۸) (۱۰/۴۹۰)\n(3) التاریخ الکبیر (۲/۲۰۲)"}],[3577,"§۳۵۸۳ ۔ سواد بن غزیہ انصاری(1)(4)\nاز بنی عدی بن النجار۔ بقول بعض سوادہ، ایک قول ہے: بلوی ہیں اور انصار کے حلیف ہیں۔ بلوی کی واؤ مخفف ہے۔ سہیلی نے واؤ مشدد لکھی ہے۔ ابو حاتم(2) کا قول ہے۔ بدر میں شریک ہوئے۔ انہوں نے ہی خالد بن ہشام مخزومی کو قید کیا تھا۔ دار قطنی کی روایت ہے کہ سیدنا ابو ہریرہ اور ابو سعید رضی اللہ عنہما سے مروی ہے، نبی صلی اللہ علیہ وسلم نے سواد بن غزیہ کو، جو بنی عدی کے تھے، روانہ کیا اور خیبر کا امیر بنایا جو آپ کے پاس وہاں کی کھجوریں لائے۔ (حدیث)۔ صحیحین میں بغیر نام اس کا ذکر ہے۔ دار قطنی کے کسی نسخہ میں سوار لکھا ہے جس کے متعلق ابو عمر(3) فرماتے ہیں یہ لفظی غلطی ہے۔ میں کہتا ہوں: ایسا ہی ابن شاہین نے دار قطنی کے شیخ ابن صاعد سے بحوالہ ان کے درست نقل کیا ہے، اور خطیب کی المبہمات میں ایک روایت ہے کہ خیبر کے امیر کا نام فلاں ابن صعصعہ ہے۔ ابن اسحاق کی بواسطہ حبان بن واسع بحوالہ ان کی قوم کے بزرگوں سے روایت ہے کہ بدر کے روز رسول اللہ صلی اللہ علیہ وسلم نے صفیں درست کیں، آپ کے ہاتھ میں پیالہ تھا، سواد بن غزیہ کے پاس سے گزرے تو ان کے پیٹ میں پیار سے چھوکا لگایا تو وہ عرض کرنے لگے: آپ نے مجھے تکلیف دی ہے میں نے بدلہ لینا ہے۔ آپ صلی اللہ علیہ وسلم نے اپنے پیٹ سے کپڑا ہٹایا تو وہ آپ سے لپٹ کر آپ کے پیٹ کو چومنے لگے۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے دعاء خیر کی۔ ابو عمر(5) فرماتے ہیں: یہی واقعہ سواد بن عمرو کے حوالہ سے بھی مروی ہے۔ میں کہتا ہوں: دو واقعات ہونے میں کوئی ممانعت نہیں جبکہ سبب بھی مختلف ہو۔ عبد الرزاق کی روایت ہے آپ صلی اللہ علیہ وسلم کھجور کی شاخ لے کر گزر رہے تھے جو سواد بن غزیہ انصاری کے لگ گئی، پھر وہ واقعہ نقل کیا۔ معمر بحوالہ ایک شخص روایت کرتے ہیں جو حسن بصری سے اس کے مفہوم میں مروی ہے، لیکن اس میں کہا: وہ شاخ سوادہ بن عمرو کے لگ گئی۔ اور بغوی کی روایت ہے کہ سوادہ بن عمرو رنگدار خوشبو لگاتے تھے۔ آپ نے انہیں اس سے منع کر دیا۔ ایک دن آپ سے ملاقات ہوئی آپ کے ہاتھ میں کھجور کی شاخ تھی جس کا چھوکا انہیں لگایا تو وہ عرض کرنے لگے: اللہ کے رسول صلی اللہ علیہ وسلم! میں نے تو بدلہ لینا ہے۔ آپ صلی اللہ علیہ وسلم نے اپنے پیٹ سے کپڑا ہٹایا اور فرمایا: بدلہ لے لو! انہوں(6) نے شاخ پھینک کر آپ صلی اللہ علیہ وسلم کے پیٹ کو چومنا شروع کر دیا۔ حسن فرماتے ہیں: اسلام نے انہیں بدلہ لینے سے روکا۔","",{"fn":"(1) اسد الغابہ (۲۳۳۲) استیعاب (۱۱۱۳) تجرید (۱/۲۴۸)\n(2) الجرح والتعدیل (۲/۳۰۳)\n(3) استیعاب (۲/۲۳۲)\n(4) السیرۃ النبویۃ (۲/۲۰۲)\n(5) استیعاب (۲/۲۷۲)\n(6) السنن الکبریٰ (۹/۴۹) المعجم الکبیر (۱/۱۷۵) کنز العمال (۴۰۲۲۲)"}],[3578,"§۳۵۸۴ ۔ سواد بن قارب الدوسی یا السدوسی(1)\nامام بخاری(2)، ابو حاتم(3)، بردیجی اور دار قطنی کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن ابی خیثمہ اور محمد بن ہارون رویانی کی بطریق ابو جعفر باقر روایت کی ہے کہ سواد بن قارب دوسی نامی ایک شخص سیدنا عمر رضی اللہ عنہ کے پاس آیا۔ آپ نے فرمایا: “سواد! میں تمہیں اللہ کا واسطہ دیتا ہوں، کیا تمہیں اب بھی اپنی کہانت اچھی طرح آتی ہے؟” انہوں نے کہا: سبحان اللہ! اللہ کی قسم! امیر المومنین! جیسا آپ نے میرا استقبال کیا ایسا آپ کے کسی ہمنشیں نے نہیں کیا۔ آپ نے فرمایا: سواد! سبحان اللہ! ہم تمہاری کہانت سے زیادہ اپنے شرک پر اعتماد نہ کرتے تھے۔ ہمیں اپنی بات سناؤ! وہ کہنے لگے: وہ تو بڑی عجیب ہے۔ ایک دفعہ جاہلیت میں میں سویا ہوا تھا کہ اچانک میرے پاس سرگوشی کرنے والا جن آ کر کہنے لگا: اس نے مجھے پاؤں سے ٹھوکر لگا کر جگایا۔ سواد بن قارب! جو کچھ میں کہہ رہا ہوں اسے سنو! میں نے کہا: بتاؤ! “مجھے جنوں اور ان کی نجاستوں پر تعجب ہوتا ہے جب وہ بھورے رنگ کے اونٹوں پر ٹاٹ ڈالے جا رہے تھے۔ وہ مکہ ہدایت تلاش کرنے گئے۔ ان کے مسلمان ان کے مشرکوں کی طرح نجس نہیں۔ ہاشم کے برگزیدہ کا رخ کر اور اپنی آنکھیں اس کی طرف اٹھا”۔(4) پھر لمبی حدیث ذکر کی۔ اس کا ایک اور طریق ہے جو ابن شاہین نے بحوالہ انس بن مالک رضی اللہ عنہ نقل کیا ہے کہ دوسی کا ایک شخص جسے سواد بن قارب نبی صلی اللہ علیہ وسلم کے پاس آیا، پھر لمبا واقعہ نقل کیا جس کے آخر میں ہے۔ میرے لیے اس دن کے واسطے سفارشی بن جا، جو سواد بن قارب کو تمہارے علاوہ فائدہ دینے والا نہیں۔ اس کا ایک تیسرا طریق بھی ہے جسے حسن بن سفیان نے بطریق حسن بن عمارہ بحوالہ عبد اللہ بن عبد الرحمن نقل کیا ہے کہ سواد بن قارب سیدنا عمر رضی اللہ عنہ کے پاس آئے، پھر طویل حدیث روایت کی۔ اس کا چوتھا طریق امام بخاری رحمہ اللہ نے اپنی تاریخ میں، بغوی اور طبرانی نے بطریق عباد بن عبد الصمد نقل کیا ہے کہ میں نے سعید بن جبیر کو فرماتے سنا: مجھے سواد بن قارب نے بتایا: ایک دفعہ میں سویا ہوا تھا.... پھر لمبا واقعہ بیان کیا۔ اور دوسرا واقعہ نہیں نقل کیا۔ اس کا پانچواں طریق حسن بن سفیان، ابو یعلیٰ، حاکم، بیہقی اور طبرانی نے بطریق عثمان بن عبد الرحمن الوقاصی بواسطہ محمد بن کعب قرظی نقل کیا ہے۔ ایک دفعہ سیدنا عمر رضی اللہ عنہ مسجد میں تشریف فرما تھے۔ اس کا چھٹا طریق بیہقی نے دلائل میں بطریق ابو اسحاق بحوالہ براء بن عازب نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ لوگوں سے خطاب کرتے ہوئے فرمانے لگے: لوگو! کیا تم میں سواد بن قارب ہے، پھر لمبا واقعہ ذکر کیا۔ اس واقعہ کی اصل صحیح بخاری میں بطریق سالم بحوالہ ان کے والد مروی ہے کہ میں نے سیدنا عمر رضی اللہ عنہ کو جس چیز کے بارے یہ کہتے سنا کہ میرا اس کے متعلق یہ خیال ہے تو وہ ایسی ہی ہوتی، چنانچہ ایک دفعہ سیدنا عمر رضی اللہ عنہ بیٹھے تھے ایک حسین و جمیل شخص گزرا، آپ نے فرمایا: میرا خیال ہے کہ یہ شخص اپنے مذہب پر ہے یا یہ پہلے کاہن (نجومی) تھا، اس شخص کو میرے پاس لایا جائے۔ پھر آپ نے اسے بلا بھیجا(5) اور مختصر واقعہ نقل کیا۔ بیہقی فرماتے ہیں: لگتا ہے وہ سواد بن قارب ہی تھے۔ ابو علی القالی کا قول ہے: قبیلہ طے کے پانچ آدمی جن کا تعلق ذو الخلصہ سے تھا، جن میں برج بن مسہر (جنہوں نے لمبی عمر پائی تھی) انیف بن حارثہ بن لام، عبد اللہ بن سعد حاتم کے والد، عارف شاعر، اور مرہ بن عبد رضا شامل تھے۔ یہ سب حضرات سواد بن قارب کے علم کا امتحان لینے ان کے پاس پہنچے۔ آپس میں کہنے لگے: ہر شخص کوئی خفیہ بات سوچ لے جس کا اپنے ساتھیوں کو پتہ نہ لگنے دے۔ اگر اس نے صحیح بتایا تو ہمیں اس کے علم کا حال معلوم ہو جائے گا۔ اور اگر غلط بتایا تو ہم واپس آ جائیں گے۔ جب یہ لوگ وہاں پہنچے تو انہیں اونٹ اور دوسری چیزوں کا ہدیہ پیش کیا۔ انہوں نے ان کے لیے خیمہ لگوایا اور ان کی ضیافت کے لیے اونٹ ذبح کیا۔ جب تین دن گزر گئے تو انہیں اپنے ہاں بلایا۔ سب سے پہلے برج نے بات کی جو سب سے زیادہ عمر رسیدہ تھا۔ پھر وہ واقعہ ذکر کیا جس میں ان کی چھپائی ہوئی باتوں کی پہچان و اطلاع تھی، اسی طرح ان کی ذاتوں اور نسبوں کا علم بھی تھا۔ جس پر عارف شاعر نے کہا: “خبردار! اللہ کے لیے علم ہے جسے کتابوں میں نہیں چھپایا جاتا جو سواد کے محلہ میں ہے جب ہم نے اپنی منتخب چیزوں کو چھپایا تو وہ اس کے سامنے ایسے عیاں تھیں جیسے وہ واضح کر رہا ہے یا آواز دے رہا ہے”۔","",{"fn":"(1) اسد الغابہ (۲۳۳۳) استیعاب (۱۱۴) تجرید (۱/۲۴۸)\n(2) التاریخ الکبیر (۲/۲۰۲)\n(3) الجرح والتعدیل (۴/۳۰۳)\n(4) المعجم الکبیر (۷/۹۲)\n(5) بخاری، کتاب المناقب (۳۸۶۶)"}],[3579,"§۳۵۸۵ ۔ سواد بن قصبہ(1)\nحمزہ بن یوسف سہمی نے جرجان آنے والے صحابہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۳۴)"}],[3580,"§۳۵۸۶ ۔ سواد بن مالک(1)\nبن سواد الداری۔ بقول ابن کلبی: نبی صلی اللہ علیہ وسلم نے ان کا نام تبدیل کر کے عبد الرحمن رکھا تھا۔","",{"fn":"(1) اسد الغابہ (۲۳۳۵)"}],[3581,"§۳۵۸۷ ۔ سواد بن مالک بن تمیمی\nسیف نے “الفتوح” میں لکھا ہے کہ سیدنا سعد بن ابی وقاص نے انہیں اپنے پہلے سریے کا امیر بنایا تھا اور دوسری بار انہیں پہلے دستوں کا امیر مقرر کیا۔ اس کے بعد ذکر کیا کہ انہوں نے قادسیہ کے محاصرہ کے دوران حملہ کیا اور ان کے تین سو(۳۰۰) جانور لوٹ لیے جنہیں گھی سے لاد کر لے آئے اور مسلمانوں میں تقسیم کر دیے گئے۔"],[3582,"§۳۵۸۸ ۔ سواد بن مقرن المزنی\nبھائیوں میں سے ایک ہیں۔ فتوح میں ان کا ذکر ملتا ہے، ان کے بھائی نعیم بن مقرن نے انہیں “قومس” کی مہم پر روانہ کیا جسے یہ صلح سے فتح کر لائے اور جرجان کے حاکم نے ان سے خط و کتاب کی اور جزیہ دینے پر صلح کر لی۔ بقول بعض: یہ سوید ہیں جن کا ذکر عنقریب ہوگا، شاید تصغیر ان کا لقب ہے۔"],[3583,"§۳۵۸۹ ۔ سوادہ ابن الربیع الجرمی(1)\nبقول امام بخاری رحمہ اللہ(2): انہیں شرف صحابیت حاصل ہے، بصریوں میں شمار ہوتے ہیں۔ امام احمد رحمہ اللہ کی روایت ہے سوادہ بن الربیع نے فرمایا: میں نے آ کر نبی صلی اللہ علیہ وسلم سے ضرورت کا جانور مانگا تو آپ صلی اللہ علیہ وسلم نے مجھے دینے کے لیے اونٹوں کا فرمان جاری کیا۔ پھر فرمایا: “جب تم اپنے بیٹوں کے پاس پہنچنا تو ان سے کہنا وہ ان کی غذا اور چارے کا اچھے طریقے سے بندوبست کریں اور (دودھ دوہنے کے لیے) اپنے ناخن کاٹ کر رکھیں”۔ (حدیث)۔ بغوی کی دوسری سند سے روایت ہے کہ سوادہ نے فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس اپنی والدہ کو لایا آپ نے ان کے لیے ایک بکری دینے کا حکم دیا اور فرمایا: “اپنے بیٹوں سے کہنا وہ اپنے ناخن لیں”۔ (حدیث)(3) طبرانی اور ابن شاہین کی بحوالہ سوادہ بن الربیع مرفوع روایت ہے: “گھوڑوں کی پیشانیوں میں خیر و بھلائی باندھ دی گئی ہے”۔ بغوی(4) اور حسن بن سفیان نے اسی سند سے روایت کرتے ہیں، انہوں نے نبی صلی اللہ علیہ وسلم کے ہاتھ میں انگوٹھی دیکھی۔ ابن ابی حاتم(5) بحوالہ اپنے والد روایت کرتے ہیں، بقول بعض: سواد بن قارب ایک قول ہے، ابن الربیع یعنی تخفیف کے ساتھ تشدید ان کے والد کے نام میں ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۳۷) استیعاب (۱۱۱۶) تجرید (۱/۲۴۸)\n(2) التاریخ الکبیر (۲/۱۶۷)\n(3) المعجم الکبیر (۵/۶۴)\n(4) مسلم کتاب الزکاۃ باب اثم مانع الزکاۃ (۲۲۸۹) ترمذی کتاب فضائل الجہاد باب ما جاء فی فضل من ارتبط فرسا (۱۶۳۶)\n(5) الجرح والتعدیل (۴/۲۹۲)"}],[3584,"§۳۵۹۰ ۔ سوادہ بن عمرو\nاور سوادہ بن غزیہ۔ قریب ہی ان کا تذکرہ ہوا ہے۔"],[3585,"§۳۵۹۱ ۔ سوار بن ہمام\nاز بنی مرہ بن ہمام۔ رشاطی نے بحوالہ مدائنی ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم کے پاس آئے پھر عراق کی فتوحات میں شریک ہوئے۔ اس میں ان کا ذکر ہے، ان کے بیٹے عبد اللہ کو امیر معاویہ ہندوستان کے کسی علاقے کا گورنر بنایا تھا۔ جہاں وہ شہید ہوئے۔"],[3586,"§۳۵۹۲ ۔ سویبط بن حرملہ(1)\nبقول بعض: ابن سعد بن حرملہ۔ ایک قول ہے: خوئیملہ بن مالک بن عمیلہ بن السباق بن عبد الدار قرشی عبدی۔ موسیٰ بن عقبہ، ابن اسحاق اور عروہ نے مہاجرین حبشہ اور شرکاء بدر میں ان کا ذکر کیا ہے۔ امام احمد رحمہ اللہ نے بحوالہ ام سلمہ روایت کی ہے کہ سیدنا ابو بکر بصری تجارت کی غرض سے گئے، آپ کے ساتھ نعیمان، سویبط بن حرملہ بھی تھے، یہ دونوں بدری ہیں۔ سویبط کے ذمہ توشہ اور زاد راہ کا بندوبست تھا، تو نعیمان نے ان سے کہا: مجھے کھانا دو، انہوں نے کہا: ابو بکر کو آنے دو، نعیمان بڑے خوش طبع اور مزاحی آدمی تھے۔ یہ ان لوگوں کے پاس گئے جو اونٹ لائے تھے۔ ان سے کہا: مجھ سے ایک عقلمند غلام خرید لو جو عربی ہے۔ انہوں نے کہا: ٹھیک ہے۔ پھر یہ کہنے لگے: وہ زبان کا بڑا تیز ہے، کہیں یہ کہہ دے میں آزاد ہوں۔ اگر تم اس وجہ سے اسے چھوڑنے والے ہو تو رہنے دو، اسے خراب نہ کرو۔ وہ کہنے لگے: کیوں نہیں۔ ہم اسے خریدیں گے۔ چنانچہ انہوں نے دس اونٹنیوں کے بدلے یہ غلام خرید لیا۔ اب یہ اونٹنیاں ہانکے چل پڑے، اور کہنے لگے: لو وہ غلام یہ ہے۔ سویبط نے کہا: یہ جھوٹا ہے، میں آزاد آدمی ہوں۔ وہ کہنے لگے: ہمیں تمہارے بارے پتہ ہے اور ان کی گردن میں رسی ڈال کر چل پڑے۔ اتنے میں ابو بکر رضی اللہ عنہ آئے، انہیں سارا معاملہ معلوم ہوا تو وہ آپ کے ساتھ ان کے پاس گئے، اونٹنیاں واپس کر دیں اور انہیں واپس لیا۔ پھر نبی صلی اللہ علیہ وسلم کو اس سے آگاہ کیا تو آپ اور آپ صلی اللہ علیہ وسلم کے صحابہ رضی اللہ عنہم اس بات پر سال تک ہنستے رہتے (کہ کتنا عجیب مزاح ہے)۔ اسے ابو داؤد طیالسی اور رویانی نے نقل کیا ہے، ابن ماجہ نے یہ روایت نقل کی ہے لیکن الٹ دی ہے انہوں نے مزاح کرنے والا سویبط اور بیچنے والا نعیمان قرار دیا ہے۔ زبیر بن بکار نے یہی واقعہ کتاب الفکاہہ میں ایک اور طریق سے بحوالہ ام سلمہ نقل کیا ہے۔ البتہ انہوں نے ان کا نام “سلیط بن حرملہ” لیا ہے۔ میرے خیال میں یہ لفظی غلطی ہے۔ ابن عبد البر(2) وغیرہ نے ان کا تعاقب کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۴۰) استیعاب (۱۱۵۴)\n(2) استیعاب (۲/۲۴۷)"}],[3587,"§۳۵۹۳ ۔ سویبط بن عمرو\nمہاجرین اولین سے ہیں۔ ابن ابی حاتم(1) نے بحوالہ اپنے والد ان کا ذکر کیا ہے۔ ابو عمر کا قول ہے: ابو حاتم نے سویبط بن عمرو اور سویبط بن حرملہ میں اور اس واقعہ والے سویبط جو نعیمان کے ساتھ زادِ راہ میں تھے میں فرق کیا ہے۔ حالانکہ تینوں ایک ہیں۔ میں کہتا ہوں: سویبط بن حرملہ جن کا واقعہ نعیمان کے ساتھ ہے جیسا کہ پہلے تذکرہ ہوا ہے اور سویبط بن عمرو کوئی اور ہیں۔","",{"fn":"(1) الجرح والتعدیل (۴/۳۱۹)"}],[3588,"§۳۵۹۴ ۔ سویبط بن حاطب(1)\nبن حارث بن ہیشہ انصاری۔ اُحد میں شہید ہوئے۔ ضرار بن خطاب نے انہیں قتل کیا۔ ابو عمر(2) نے ان کا ذکر کیا ہے۔ وہی سنیج ہیں جن کا تذکرہ پہلے ہوا ہے اور اس پر متنبہ نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۲۳۴۱) استیعاب (۱۱۵۵)\n(2) استیعاب (۲/۲۴۸)"}],[3589,"§۳۵۹۵ ۔ سوید بن ثابت(1)\nاوس بن ثابت کے حالات میں ان کا ذکر کیا ہے جو ثعلبی کی طرف منسوب ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۴۲) تجرید (۱/۲۴۹)"}],[3590,"§۳۵۹۶ ۔ سوید بن حارث ازدی\nابو احمد العسکری کی بطریق احمد بن ابی الحواری سے روایت ہے میں نے ابو سلیمان الدارانی سے سنا، میں نے دمشق کے ساحل پر ایک شیخ سے سنا جن کا نام علقمہ بن یزید بن سوید ازدی تھا، فرماتے ہیں مجھے میرے والد نے بحوالہ میرے دادا سوید بن حارث روایت کی ہے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنی قوم کے ساتھ ساتواں آدمی بن کر پہنچا۔ آپ صلی اللہ علیہ وسلم کو ہماری چال ڈھال اچھی لگی، آپ نے فرمایا: تم کون لوگ ہو؟ ہم نے عرض کی: مومن ہیں۔ آپ نے فرمایا: تمہارے ایمان کی کیا حقیقت ہے؟ ہم نے عرض کیا: پندرہ علامتیں ہیں۔ پانچ کا آپ صلی اللہ علیہ وسلم نے ہمارے پاس آنے والے قاصدوں کو حکم دیا ہے، اور پانچ کا آپ نے ہمیں عمل کرنے کا حکم دیا ہے اور پانچ ہماری جاہلیت میں پیچھے رہ گئی ہیں۔ پھر لمبی حدیث ذکر کی۔ یہی حدیث رشاطی(1) اور ابن عساکر نے دوسری دو سندوں سے بحوالہ احمد بن ابی الحواری روایت کی ہے، جبکہ ابو سعید نیشاپوری نے “شرف المصطفیٰ” میں ایک اور سند سے بحوالہ احمد بن ابی الحواری روایت کی کہ علقمہ بن سوید بن علقمہ بن حارث نے فرمایا اور ابو موسیٰ نے “ذیل” میں علقمہ بن حارث کا اسی وجہ سے ذکر کیا ہے، بہر کیف پہلا زیادہ مشہور ہے۔","",{"fn":"(1) اتحاف السادۃ المتقین (۹/۳۲۷) کنز العمال (۳۶۹۸۹) جامع المسانید (۵/۹۴)"}],[3591,"§۳۵۹۷ ۔ سوید بن حارثہ\nبن نضلہ بن عوف بن عبید بن عوج بن عدی بن کعب قرشی عدوی زبیر بن بکار کا بیان ہے، مسعود کے والد جن کی بیٹی امۃ اللہ سے عباس بن ربیعہ بن حارث بن عبد المطلب نے شادی کی تھی جس سے جعفر اور عون پیدا ہوئے۔"],[3592,"§۳۵۹۸ ۔ سوید بن حنظلہ(1)\nبقول ابو عمر(2): مجھے ان کی اس حدیث کے علاوہ کوئی روایت معلوم نہیں۔ میں کہتا ہوں: یہ حدیث ابو داؤد(3) اور ابن ماجہ(4) نے نقل کی ہے جس کے الفاظ یہ ہیں: مسلمان، مسلمان کا بھائی ہے، اس میں ان کا ایک واقعہ بھی ہے جو وائل بن حجر کے ساتھ پیش آیا جس میں انہوں نے نبی صلی اللہ علیہ وسلم سے فتویٰ پوچھا تھا۔ جس کا انہوں نے ذکر کیا۔ ازدی لکھتے ہیں: ان سے صرف ان کی بیٹی نے روایت کی ہے۔ ابن عبد البر(5) فرماتے ہیں: مجھے ان کے نسب کا علم نہیں۔ میں کہتا ہوں: ابن حبان کا گمان ہے: یہ جعفی نہیں۔ ثوری نے بواسطہ عباس عامری بحوالہ سوید بن حنظلہ اس کے علاوہ ایک اور حدیث روایت کی ہے۔ مجھے معلوم نہیں یہ صحابی ہیں یا تابعی؟","",{"fn":"(1) اسد الغابہ (۲۳۴۴) استیعاب (۱۱۲۰)\n(2) استیعاب (۲/۲۳۵)\n(3) ابو داؤد کتاب الایمان والنذور باب المعاریض فی الایمان (۳۲۵۶)\n(4) ابن ماجہ کتاب التجارات باب من باع عیبا فلیبینہ (۲۲۴۶)\n(5) استیعاب (۲/۲۳۵)"}],[3593,"§۳۵۹۹ ۔ سوید بن زید(1)\nالجذامی، رفاعہ کے بھائی۔ موسیٰ بن سہل رملی نے فلسطین فروکش ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ ابن حبان(2) کا قول ہے: صحابی ہیں اور بیت جبرین میں فوت ہوئے۔ بقول ابن مندہ: اپنے بھائیوں کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابن ہشام نے، اموی نے مغازی میں، واقدی اور طبرانی کی روایت ہے: جب زید بن حارثہ رضی اللہ عنہ نے بنی جذام پر حملہ کیا تو قیدیوں میں یہ بھی شامل تھے۔ اسلام لے آئے تو نبی صلی اللہ علیہ وسلم نے انہیں آزاد کر دیا۔","",{"fn":"(1) اسد الغابہ (۲۳۴۵) تجرید (۱/۲۴۹)\n(2) الثقات (۳/۱۷۷)"}],[3594,"§۳۶۰۰ ۔ سوید بن الصامت(1)\nبن حارثہ بن عدی بن قیس بن زید بن مالک بن ثعلبہ بن کعب بن الخزرج انصاری۔ بقول ابن سعد و طبری: اُحد میں شریک ہوئے اور دخیل نے طبقات الشعراء میں ان کے اشعار بھی نقل کیے ہیں۔ انہوں نے اتنا قرض لے لیا تھا جس کا مطالبہ شروع ہو گیا، اپنی قوم سے مدد لی تو وہ بھی اس کی ادائیگی سے عاجز آ گئے۔ جس پر انہوں نے کہا: “مجھے اپنی قوم اجنبی لگنے لگی۔ ایسا محسوس ہوتا ہے میں نے قرض کے ذریعہ ان کے لیے ایک ذلت مول لے لی ہے۔ کیا ساری پریشانی قرض کی وجہ سے ہے تو میرا قرض ان پر کوئی تاوان اور چٹی نہیں، لیکن دودھ دینے والی اونٹنیوں اور بکریوں پر ہے۔ میں درختوں اور ان کے پھلوں کے قرض لیتا ہوں جو قریبی مولا کے لیے یا دوسرے پانی ڈھونے والے اونٹ کے لیے ہے”۔","",{"fn":"(1) اسد الغابہ (۲۳۴۷) استیعاب (۱۱۲۱)"}],[3595,"§۳۶۰۱ ۔ سوید بن صخر الجہنی(1)\nطبری کا بیان ہے یہ ان چار افراد میں سے ایک تھے جنہوں نے جہینہ(2) کے علم اٹھائے ہوئے تھے اور حدیبیہ میں شریک ہوئے۔ واقدی نے ان میں افراد میں ان کا ذکر کیا ہے جو عرنین کی طرف غالب بن عبید اللہ لیشی کے سریہ میں نکلے۔","",{"fn":"(1) اسد الغابہ (۲۳۴۸) تجرید (۱/۲۴۹)\n(2) اسد الغابہ (۲/۴۰۳)"}],[3596,"§۳۶۰۲ ۔ سوید بن طارق\nطارق بن سوید میں ان کا ذکر ہوگا۔"],[3597,"§۳۶۰۳ ۔ سوید بن عامر\nابن فتحون نے اپنے استدراک میں اور بطریق باوردی بروایت عبد العزیز بن کیسان بحوالہ سوید بن عامر ان کی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “قیامت کے روز میں اپنے حوض سے پانی پیوں گا”۔ (حدیث)(1) ابو عمر نے استیعاب میں سوید بن عامر کا مختصر تذکرہ کیا ہے، وہ اگر یہ نہیں تو میں نے قسم اخیر میں ان کا بیان کر دیا ہے کہ وہ صحابی نہیں۔ ان کی حدیث مرسل ہے۔ ابن ابی خیثمہ نے صحابہ میں ان کا ذکر کیا ہے کہ مجھے معلوم نہیں۔ سوید بن عامر انصاری عقبہ کے والد ہیں یا نہیں۔ ابن مندہ فرماتے ہیں: سوید بن عامر بن خارجہ سے مجمع بن خارجہ روایت کرتے ہیں ان کا صحابی ہونا مشہور نہیں، پھر انہی کے حالات میں وہ حدیث درج کی جو سوید بن عمرو کے حالات میں ہے۔","",{"fn":"(1) کنز العمال (۳۹۱۷۹) اتحاف السادۃ المتقین (۱۰/۵۰۷) مختصر تاریخ دمشق (۳/۳۱۳)"}],[3598,"§۳۶۰۴ ۔ سوید بن علقمہ(1)\nبن معاذ انصاری۔ ابن مندہ نے ان کا مختصر تذکرہ کیا ہے کہ یہ مشہور نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۵۳)"}],[3599,"§۳۶۰۵ ۔ سوید بن عمرو انصاری(1)\nبقول ابن سعد: نبی صلی اللہ علیہ وسلم نے ان میں اور وہب بن سعد بن ابی سرح میں بھائی چارہ قائم فرمایا۔ دونوں غزوہ موتہ میں شہید ہوئے۔ ابن مندہ نے ان کی ایک حدیث نقل کی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اپنی رشتہ داریوں کو تروتازہ رکھو، اگرچہ سلام کرنے سے ہو”۔ ابن عساکر(2) فرماتے ہیں: اگر یہ وہی ہیں جو موتہ میں شہید ہوئے تو حدیث مرسل ہے۔ میں کہتا ہوں: حدیث مرسل کیسے ہو سکتی ہے جبکہ مجمع کہہ رہے ہیں ہم سے انہوں نے حدیث بیان کی، بلکہ اس میں درست روایت یوں ہے “سوید بن عامر” جیسا کہ پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۵۰) استیعاب (۱۱۲۴)\n(2) المطالب العالیہ (۲۴۸۷) کشف الخفاء (۱/۳۴۱) الأمالی (۲/۱۲۶)"}],[3600,"§۳۶۰۶ ۔ سوید بن عیاش انصاری(1)\nان لوگوں میں تھے جنہیں مسجد ضرار کو منہدم کرنے کے لیے بھیجا گیا تھا، یہ ابن مندہ کی روایت ہے اور ابن اسحاق اپنی اسناد سے بیان کرتے ہیں: جن لوگوں نے مسجد ضرار گرائی ان میں معن بن عدی اور مالک بن الدخشم شامل تھے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۲۳۵۵)"}],[3601,"§۳۶۰۷ ۔ سوید بن غفلہ(1)\nابن عساکر کی روایت ہے کہ اسامہ بن عطاء نے فرمایا: میں نعمان بن بشیر کے پاس تھا، اتنے میں سوید بن غفلہ آ گئے، نعمان نے ان سے فرمایا: کیا یہی بات ہے کہ آپ نے ایک بار رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی ہے؟ فرمایا: نہیں بلکہ کئی بار۔ نبی صلی اللہ علیہ وسلم کی عادت تھی جب اذان کی آواز سنتے تو پھر کسی کی پرواہ نہ کرتے۔ ابن مندہ کی روایت ہے سوید بن غفلہ نے فرمایا: “میں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم کی پلکیں دراز اور ابرویں ملی ہوئی تھیں”۔ (حدیث)۔ میں کہتا ہوں: سوید بن غفلہ بڑے تابعی ہیں البتہ یہ بتایا جاتا ہے انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے، قسم ثالث میں ان کا تذکرہ ہوگا کہ انہوں نے ہجرت کی اور اس روز مدینہ میں داخل ہوئے جب رسول اللہ صلی اللہ علیہ وسلم کی تدفین ہوئی۔ اگر پہلی سند ثابت ہو جائے تو شاید یہ اور ہیں۔ رہے دوسرے تو ان کے بارے میں یہ احتمال ہے کہ شاید انہوں نے اسلام لانے سے پہلے آپ صلی اللہ علیہ وسلم کو دیکھا ہو، اس لیے ان کا صحابی ہونا معلوم نہیں ہوتا۔","",{"fn":"(1) اسد الغابہ (۲۳۵۶) استیعاب (۱۱۲۵)"}],[3602,"§۳۶۰۸ ۔ سوید بن قیس العبدی(1)(2)\nابو مرحب۔ مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ان سے ایک پاجامہ خریدا تھا۔ یہ روایت امام احمد اور سنن کے مصنفین نے نقل کی ہے، اس میں سماک سے آگے اختلاف ہے۔ بقول بعض: ان سے بحوالہ ابو صفوان بن مالک بن عمیرہ مروی ہے۔ ان کے حالات میں بیان ہوگی۔ مزی کے کلام سے پتہ چلتا ہے کہ سوید کی کنیت “ابو صفوان” تھی، حالانکہ ایسا نہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۵۷) استیعاب (۱۱۲۶) تجرید (۱/۲۵۰)\n(2) مسند احمد (۶/۳۵۲)"}],[3603,"§۳۶۰۹ ۔ سوید بن کلثوم\nبن قیس بن خالد بن وہب بن ثعلبہ بن واکمہ بن عمرو بن سفیان بن حارث بن فہر الفہری۔ بقول زبیر بن بکار: دمشق کے والی رہے۔ ان کا محمد نامی ایک بیٹا تھا جسے ابو عبیدہ رضی اللہ عنہ نے دمشق کا گورنر بنایا تھا۔ ابو حذیفہ نے الفتوح میں ان کا ذکر کیا ہے۔ فتح حمص میں ان کا ایک واقعہ ہے، ازدی نے “فتوح الشام” میں ان کا تذکرہ کیا ہے۔ ابو حذیفہ بخاری فرماتے ہیں: خالد ہزار کی نفری میں دمشق پہنچے، وہاں سوید بن کلثوم بن فہری تھے، جنہیں ابو عبیدہ نے دمشق میں پانچ سو کی فوج کا نائب مقرر کیا تھا۔ جب خالد دمشق آ گئے اور اپنا لشکر جما لیا تو سوید بن کلثوم کو حکم دیا کہ وہ اس کے درمیان میں قیام کریں۔ پھر فتح حمص کا واقعہ نقل کیا۔"],[3604,"§۳۶۱۰ ۔ سوید بن مخشی الطائی(1)(2)\nبقول ابو عمر: ابو معشر نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ایک قول ہے: مرتد ہو گئے تھے۔ “ابو مخشی” کنیتوں میں ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۳۵۸) استیعاب (۱۱۲۷)\n(2) استیعاب (۲/۲۳۹)"}],[3605,"§۳۶۱۱ ۔ سوید بن مقرن(1)\nبن عائذ مزنی۔ ابو عائذ کنیت تھی۔ بھائیوں میں سے ایک ہیں۔ امام مسلم اور اصحاب السنن نے ان کی حدیث نقل کی ہے۔ ان سے ان کا بیٹا معاویہ مولا ابو شعبہ اور ہلال بن یساف روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۵۹) استیعاب (۱۱۲۸) تجرید (۱/۲۵۰)"}],[3606,"§۳۶۱۲ ۔ سوید بن نعمان(1)\nبن مالک بن عامر بن مجدعہ بن جشم بن حارثہ بن حارث بن خزرج بن عمرو بن مالک بن اوس انصاری۔ کنیت ابو عقبہ تھی۔ امام بخاری رحمہ اللہ(2) نے “ستو پی کر کلی کرنے کے بارے میں” ان کی حدیث روایت کی ہے۔ اس میں ہے کہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ خیبر کی طرف روانہ ہوئے، اور بیعت رضوان میں شریک تھے۔ ابن سعد(3) کا بیان ہے اُحد میں شریک ہوئے۔ عسکری فرماتے ہیں: قادسیہ میں شہید ہوئے۔ جبکہ اس میں تامل ہے اس لیے کہ بشیر بن یسار نے ان سے سماع کیا ہے اور وہ اس دور کے نہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۶۰) استیعاب (۱۱۲۹) تجرید (۱/۲۵۰)\n(2) بخاری کتاب الوضوء باب من مضمن من السویق (۲۰۹)\n(3) الطبقات (۶/۱۱)"}],[3607,"§۳۶۱۳ ۔ سوید بن ہبیرہ(1)(7)\nبن عبد الحارث دیلی۔ بقول بعض: العبدی، یہ ابو عمر(2) کا قول ہے۔ ابن الاثیر(3) دیلی اور عبدی لکھتے ہیں اس واسطے کہ ان کا تعلق بنی دیل بن عمرو سے ہے جو عبد القیس کا بطن ہے اور فرماتے ہیں ابو احمد کا قول ہے: یہ عدوی ہیں جن کا تعلق عدی بن عبد مناۃ سے ہے۔ یہی نسب ابن قانع نے بیان کیا ہے۔ ابو عمر(4) فرماتے ہیں: بصرہ کے رہائشی تھے۔ امام احمد اور طبرانی نے ان کی حدیث نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “بہترین مال کام میں لگایا ہوا بچھیرا یا تابیر کی (گابھا لگی) ہوئی صف میں لگی کھجوریں ہیں”۔ ابن مندہ(5) فرماتے ہیں: سوائے روح بن عبادہ کے بواسطہ ابو نعامہ بحوالہ مسلم کی روایت میں نہیں کہا: “میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا”۔ یہی روایت مروان بن معاویہ نے بحوالہ ابو نعامہ مرفوع نقل کی ہے۔ میں کہتا ہوں: طبرانی نے یہ روایت بطریق عبد الوارث بواسطہ ابو نعامہ بحوالہ مسلم اسی طرح نقل کی ہے۔ اور مروان بن معاویہ نے بھی اسی طرح نقل کی۔ معاذ بن معاذ کی ابو نعامہ سے روایت ہے جس کی سند سوید تک ہے، فرمایا: مجھے نبی صلی اللہ علیہ وسلم کے حوالہ سے یہ روایت پہنچی ہے۔ امام بخاری رحمہ اللہ(6) نے اپنی تاریخ میں ان کا ذکر کیا ہے۔ ابن ابی حاتم بحوالہ اپنے والد نقل کرتے ہیں، اس میں روح سے غلطی ہوئی، یہ تو تابعی ہیں۔ ابن حبان ثقات التابعین میں لکھتے ہیں: مرسل روایات کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۲۳۶۱) استیعاب (۱۱۳۰)\n(2) استیعاب (۲/۲۴۰)\n(3) اسد الغابہ (۲/۴۰۷)\n(4) استیعاب (۲/۲۴۰)\n(5) مسند احمد (۳/۴۶۸) المعجم الکبیر (۷/۶۴۷۰) (۷/۶۴۷۱)\n(6) التاریخ الکبیر (۲/۱۴۴)\n(7) المعجم الکبیر (۶۴۷۲)"}],[3608,"§۳۶۱۴ ۔ سوید بن ہشام التمیمی(1)\nمقاتل نے اپنی تفسیر میں ان بنی تمیم میں ان کا ذکر کیا ہے جن کے بارے میں یہ آیت نازل ہوئی: “جو لوگ آپ (صلی اللہ علیہ وسلم) کو حجروں کے باہر سے بلاتے ہیں...”(2)۔","",{"fn":"(1) الثقات (۴/۳۲۳)\n(2) سورۃ الحجرات (۴)"}],[3609,"§۳۶۱۵ ۔ سوید\nبقول بعض: ابو سوید کنیتوں میں تذکرہ ہوگا۔"],[3610,"§۳۶۱۶ ۔ سوید الاہلی ثم العکی\nطبرانی نے مسند شامیین میں بحوالہ سوید اہلی روایت کی ہے میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “اللہ تعالیٰ نے نجم اور جذام کے اس قبیلے کو شام میں اہل یمن کی مدد کے لیے بنایا ہے”۔ کبیر میں اسی سند سے نقل کیا ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا یا آپ سے سننے والے نے مجھ سے بیان کیا۔ ایسا ہی باوردی، ابن السکن اور ابن شاہین نے روایت کی ہے۔ ابو نعیم لکھتے ہیں: کنیت ابو عبد اللہ تھی، ایک قول ہے: باہلی ہیں۔ ایک قول ہے: ھانی ہیں۔ جو اشعریین کی فخذ ہے۔ ابن مندہ کے ہاں آخری بات ہی ہے کہ اس میں لفظی غلطی ہوئی ہے۔ درست آہلی جیسا کہ پہلے گزر چکا ہے، اسی پر رشاطی کا اعتماد ہے۔"],[3611,"§۳۶۱۷ ۔ سوید(1)\nسلمان فارسی کے مولا۔ امام بخاری(2) نے بحوالہ ابن فہد اور نقل کیا ہے، انہیں شرف صحابیت حاصل ہے، اسے ابن مندہ اور ابن ابی شیبہ نے “اوائل” میں بحوالہ سلمان فارسی کے غلام جنہیں سوید کہا جاتا تھا، جن کی تعریف بھی کی، روایت نقل کی ہے۔ جب مدائن فتح ہوا تو مجھے ایک تھیلہ ملا۔ سلمان مجھ سے کہنے لگے: تمہارے پاس کچھ ہے؟ میں نے کہا: ایک تھیلہ ہے، فرمایا: لاؤ! اگر کھانا ہوا تو کھالیں گے اور مال و زر ہوا تو ان کی طرف بھیج دیں گے، فرماتے ہیں: جب ہم نے اسے کھولا تو اس میں میدے کی روٹیاں اور پنیر تھا، پہلی مرتبہ عرب نے میدے کی روٹی دیکھی تھی۔","",{"fn":"(1) اسد الغابہ (۲۳۴۶)\n(2) التاریخ الکبیر (۴/۱۴۴)"}],[3612,"§۳۶۱۸ ۔ سوید انصاری\nثابت بن قیس یا سعد بن الربیع کے چچا زاد بھائی اوس بن ثابت میں ان کا تذکرہ ہوا ہے۔ ام کچھ خواتین کی کنیتوں میں بھی ان شاء اللہ تعالیٰ ان کا ذکر ہونا ہے۔"],[3613,"§۳۶۱۹ ۔ سوید الجہنی یا المزنی\nبقول بعض انصاری عقبہ کے والد۔ ابن حبان(1): سوید الجہنی صحابی ہیں۔ ابو عمر: زہری اور ربیعہ کے ہاں ان کے بیٹے کی روایت سے لقطہ اور احد کے بارے “یہ ہم سے اور ہم اس سے محبت کرتے ہیں” میں ان کی حدیث ہے۔ دونوں صحیحین میں ہیں۔ میں کہتا ہوں: زہری کی حدیث تو یہ ہے، رسول اللہ صلی اللہ علیہ وسلم جب خیبر سے واپس آئے اور اُحد پر نظر پڑی تو فرمایا: “اللہ اکبر یہ پہاڑ ہم سے اور ہم اس سے محبت کرتے ہیں”۔ یہ روایت امام احمد، بخاری نے تاریخ میں، بغوی(2)، ابن ابی عاصم، ابن شاہین اور ابو نعیم نے بطریق زہری نقل کی ہے جس کی سند میں لکھا ہے: سوید بن عقبہ انصاری مروی ہے، انہوں نے اپنے والد سے سنا جو صحابی تھے۔ امام بخاری(3) فرماتے ہیں: یونس بن زید کی بواسطہ اسحاق بن راشد بحوالہ الزہری والی روایت میں عقبہ ہے۔ رہی ربیعہ والی حدیث تو اسے ابو داؤد نے تعلیقا اور باوردی، طبرانی، اور مطین نے موصولا بحوالہ عقبہ بن سوید روایت کیا وہ اپنے والد سے نقل کرتے ہیں۔ فرمایا: میں نبی صلی اللہ علیہ وسلم سے بکری کے بارے میں پوچھا، ادھر بغوی نے ان سوید میں جن کی حدیث زہری نقل کرتے ہیں اور ان سوید میں جن کی حدیث ربیعہ نقل کرتے ہیں فرق کیا ہے، کیونکہ دونوں کا نسب مختلف ہے، چنانچہ زہری کی روایت میں جہنی اور ربیعہ کی روایت میں انصاری لکھا ہے۔ یہ بھی احتمال ہے دونوں ایک ہوں جن کی صورت یہ ہے کہ جہنی ہو کر انصار کے حلیف بن گئے ہو۔ مجھے وہ روایت نہیں ملی جس میں ہے کہ وہ مزنی ہیں۔","",{"fn":"(1) الثقات (۳/۱۷۸)\n(2) مسند احمد (۳/۴۴۳) المعجم الکبیر (۶۰۶۷)\n(3) التاریخ الکبیر (۲/۱۴۶)"}],[3614,"§۳۶۲۰ ۔ سوید (بے نسبت)(1)\nابن قانع نے ان کا ذکر کیا اور بطریق ابو بکر الکفنی بحوالہ سوید روایت کی ہے مجھے یاد ہے ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ کی ایک نماز پڑھی جسے تم لوگ اگر آج پڑھتے تو دہراتے۔ اور فرمایا: ہمارے امیر یعنی عمر بن عبد العزیز جو اس وقت مدینہ کے گورنر تھے ان سے اس کا ذکر نہ کرنا۔","",{"fn":"(1) اسد الغابہ (۲۳۶۲)"}],[3615,"§۳۶۲۱ ۔ سوید\nمسلم بن یسار کے دادا۔ خطیب نے المتفق میں مسلم بن یسار جہنی کے حالات میں لکھا ہے کہ ابن شاہین نے حدیث سوید جو مسلم بن یسار کے دادا ہیں، بحوالہ نبی صلی اللہ علیہ وسلم ذکر کی۔"],[3616,"§۳۶۲۲ ۔ سیابہ\nبن عاصم بن شیبان بن خزاعی بن محارب بن مرہ بن ہلال بن فالح بن ذکوان بن ثعلبہ بن بھیشہ بن سلیم بن سلمیٰ۔ بقول عبد الغنی بن سعید: صحابی ہیں اور وفد میں آئے۔ سعید بن منصور بحوالہ سیابہ بن عاصم سلمی روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے حنین کے دن فرمایا: “میں عواتک کا بیٹا ہوں”۔ ابن عبد البر(1)(2) نے تعجب خیز کام کیا وہ فرماتے ہیں ہشیم نے بواسطہ یحییٰ بن سعید بن عمرو بن عاص انہوں نے اپنے والد سے بحوالہ دادا انہوں نے سیابہ سے حدیث نقل کی ہے۔ مجھے ہشیم سے مروی یہی روایت نہیں ملی، صرف ان سے آگے اختلاف ہے۔ چنانچہ فرمایا، ان سے مروی ہے: سعید بن منصور جیسا کہ پہلے گزرا ہے، اسحاق بن ادریس نے ان کی متابعت کی ہے۔ ابو حاتم(3) فرماتے ہیں: ہمیں ہشیم کے حوالہ سے ان کے کسی شاگرد نے اسی طرح بتایا، اور محمد بن الصباح نے ان سے نقل کیا کہ یحییٰ بن سعید بواسطہ عمرو بن سعید بحوالہ سیابہ نقل کرتے ہیں۔ ابو حاتم فرماتے ہیں: پہلا زیادہ مناسب ہے۔ میں کہتا ہوں: اسحاق ضعیف ہے محمد بن صباح نے عمرو بن عوف کی متابعت کی ہے۔ (طبرانی) میں کہتا ہوں: بغوی نے لؤین سے بواسطہ ہشیم، یحییٰ بن سعید بن عمرو بن سعید بحوالہ سیابہ روایت کی ہے۔ لؤین فرماتے ہیں: مجھے معلوم نہیں۔ شاید ان دونوں میں ایک شخص اور ہے۔ امام بخاری رحمہ اللہ(4) نے ہشیم سے آگے واسطے میں اختلاف ذکر کیا ہے اور اس پر اعتماد ظاہر کیا ہے کہ یہ حدیث مرسل ہے۔ یہی روایت یعقوب بن سفیان نے اپنی تاریخ میں نقل کی کہ سیابہ بن عاصم حجاج کے دور میں تھے، وہ عبد الملک کی جانب سے قاصد بن کر آیا تھا۔","",{"fn":"(1) اسد الغابہ (۲۳۶۳) استیعاب (۱۱۵۶)\n(2) المعجم الکبیر (۷/۶۷۲۴) مجمع الزوائد (۸/۲۱۹)\n(3) الجرح والتعدیل (۴/۳۲۲)\n(4) التاریخ الکبیر (۲/۲۰۹)"}],[3617,"§۳۶۲۳ ۔ سیار بن بلز\nابو الشراء کے والد بقول شخصے مبہمات میں ان کا ذکر ہوگا۔"],[3618,"§۳۶۲۴ ۔ سیار بن سوید الجہنی\nشان کے حالات میں ان کا ذکر ہے۔"],[3619,"§۳۶۲۵ ۔ سیار سنبر\nسنبر کے حالات میں۔"],[3620,"§۳۶۲۶ ۔ سیار بن روح سیاری\nروح بن سیار میں۔"],[3621,"§۳۶۲۷ ۔ سیار بن طلق الیمانی\nجابر کے بیٹے محمد اور ایوب کے دادا۔ میں نے نہیں دیکھا کہ کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہو۔ البتہ ابن عدی نے “الکامل” میں محمد بن جابر کے حالات میں ان کی حدیث نقل کی ہے کہ وہ اپنے دادا کے حوالہ سے بیان کرتے ہیں کہ بنی حنیفہ کے وہ پہلے شخص ہیں جو رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے۔ فرماتے ہیں: میں گیا تو آپ صلی اللہ علیہ وسلم اپنا سر دھو رہے تھے۔ فرمانے لگے: اے یمامی! اپنا سر دھولو۔ چنانچہ میں نے آپ صلی اللہ علیہ وسلم کے بچے ہوئے پانی سے اپنا سر دھویا، پھر میں نے شہادتین پڑھیں اس کے بعد آپ صلی اللہ علیہ وسلم نے میرے لیے تحریر لکھوائی۔ میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم مجھے دل بہلانے کے لیے اپنی قمیص کا گوشہ دے دیجئے۔ آپ صلی اللہ علیہ وسلم نے مجھے وہ ٹکڑا دے دیا۔ محمد بن جابر فرماتے ہیں: مجھے میرے والد نے بتایا وہ ٹکڑا اب تک ہمارے پاس ہے، جسے دھو کر ہم مریض کو پلاتے ہیں جس سے وہ صحت یاب ہو جاتا ہے۔"],[3622,"§۳۶۲۸ ۔ سیار بن عبد اللہ\nعسکری نے صحابہ میں ان کا ذکر کیا ہے۔"],[3623,"§۳۶۲۹ ۔ سیار (عبد اللہ کے والد)\nان سے ان کا بیٹا ایک حدیث نقل کرتا ہے۔ ایسا ہی تجرید میں ہے، مجھے معلوم نہیں آیا یہ وہی ہیں جن کا عسکری نے ذکر کیا ہے یا اور ہیں؟"],[3624,"§۳۶۳۰ ۔ سیان الکوفی\nدعبل بن علی الخزاعی نے طبقات الشعراء میں ان کا ذکر کیا ہے۔ خلافت عثمانی میں وہ جیل کے ذمہ دار تھے۔ دعبل ان کے والد ازدی کے حالات میں لکھتے ہیں: جب جندب بن زہیر ازدی نے ولید بن عقبہ کے سامنے جادوگر کو مار دیا تو ولید نے انہیں قید میں ڈال دیا جس کے متعلق انہوں نے مندرجہ ذیل اشعار کہے: “کیا جادوگر کو قتل کرنے کی وجہ سے جندب کو قید کیا جا رہا ہے اور نبی صلی اللہ علیہ وسلم کے پہلے صحابہ کو قتل کیا جا رہا ہے”۔ فرماتے ہیں: جندب کو جب جادوگر کے کرتب کا پتہ چلا آپ نے اپنی تلوار اٹھائی اور ولید کے پاس جا پہنچے۔ جادوگر سے کہا: کیا تم آدمی کو قتل کر کے پھر زندہ کر لیتے ہو؟ اس نے کہا: ہاں۔ تلوار مار کر اس کا کام تمام کر دیا۔ تو ولید نے انہیں قید میں ڈالنے کا حکم دیا تو وہ قید میں ڈال دیے گئے۔ حوالدار نے ان سے پوچھا: آپ کس وجہ سے جیل آئے؟ تو انہوں نے سارا واقعہ سنایا، تو حوالدار نے انہیں چھوڑ دیا، پھر وہ مدینہ آ گئے۔ سیدنا عثمان رضی اللہ عنہ کو آگاہ کیا، آپ نے ولید کو لکھا: تم انہیں کچھ نہ کہو۔ چنانچہ وہ اپنے ارادہ سے باز رہا، اور حوالدار کو قتل کر دیا گیا۔ اس کا نام سیان تھا جسے شرف صحابیت حاصل تھا۔ اسی وجہ سے شاعر نے یہ اشعار کہے تھے۔"],[3625,"§۳۶۳۱ ۔ سیحان بن صوحان العبدی\nبھائیوں میں سے ایک ہیں۔ سیف بن عمر نے بحوالہ قاسم بن محمد روایت کی ہے کہ مرتدوں کے خلاف جنگ میں وہ امیر تھے اور پہلے سے معلوم ہے کہ صحابہ رضی اللہ عنہم ہی امیر بنائے جاتے تھے۔ بقول بعض: سیحان جنگ جمل میں شہید ہوئے۔"],[3626,"§۳۶۳۲ ۔ سیدان (عبد اللہ کے والد)(1)\nطبرانی(2) کی روایت ہے کہ سیدان نے فرمایا: نبی صلی اللہ علیہ وسلم قلیب کے مردوں سے مخاطب ہو کر فرمانے لگے: “اے اہل قلیب! تمہارے رب نے تم سے جو (سزا و عذاب کا) وعدہ کیا تھا اسے تم نے پایا کہ وہ برحق ہے؟” لوگوں نے عرض کی: اللہ کے رسول! کیا یہ لوگ سن رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “ایسے ہی سن رہے ہیں جیسے تم سنتے ہو لیکن جواب نہیں دیتے”۔","",{"fn":"(1) اسد الغابہ (۲۳۶۶)\n(2) المعجم الکبیر (۷/۶۷۱۵)"}],[3627,"§۳۶۳۳ ۔ السید بن بشر بن عضد\nعصمہ عامری بن عبد القیس پھر بنی عامر بن حارث بن انمار سے، رشاطی کا قول ہے: اپنے والد کے بعد بنی عامر کے سردار تھے، بے حد شریف اور سخی آدمی تھے جس کے متعلق ان کے کئی واقعات اور جاہلیت میں کئی حملے مشہور ہیں۔ اسلام کا دور پایا اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ اس کے بعد مرتدوں کے خلاف جنگ میں جارود عبدی کے ساتھ اپنی قوم کے سردار رہے۔"],[3628,"§۳۶۳۴ ۔ السید النجرانی\nابن سعد اور مدائنی کا بیان ہے نبی صلی اللہ علیہ وسلم کے پاس آ کر اسلام قبول کیا۔ علی بن محمد قرشی کی حدیث میں وفود کے تذکرہ میں وفد نجران کے ذیل میں فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اہل نجران کی طرف خط بھیجا تو ان کے شرفاء میں سے چودہ شخص جو نصاریٰ تھے آئے۔ جن میں عاقب جو عبد المسیح کے نام سے مشہور تھے جن کا تعلق کندہ سے تھا ابو الحارث بن علقمہ جو بنی ربیعہ سے تھے ان کا بھائی کرز اور السید، پھر ان کے مناظرے کا دین نصرانیت کے بارے میں واقعہ ذکر کیا جس میں آپ صلی اللہ علیہ وسلم نے ان سے فرمایا تھا: “اگر تم میری بات کا انکار کرتے ہو تو آؤ میں تم سے مباہلہ کروں گا”(1) اور وہ لوگ اس سے باز رہے اور آپ صلی اللہ علیہ وسلم نے ان سے جزیہ لینے پر صلح کی۔ پھر یہ لوگ اپنے علاقے میں لوٹ آئے۔ پھر ایسا ہوا کہ سید اور عاقب کچھ دن رہ کر نبی صلی اللہ علیہ وسلم کے پاس آ گئے، اسلام قبول کر لیا، آپ صلی اللہ علیہ وسلم نے ان دونوں کو ابو ایوب انصاری رضی اللہ عنہ کے گھر ٹھہرایا۔ الف میں بیان ہوا ہے کہ السید کا نام ایہم بروزن جعفر تھا۔ پھر تذکرہ ہوتا ہے، عاقب کے حالات میں بھی ان کا تذکرہ ہوا ہے۔","",{"fn":"(1) فتح الباری (۸/۹۴) الطبقات الکبریٰ (۱/۲۸۵)"}],[3629,"§۳۶۳۵ ۔ سیف بن قیس(1)\nبن معدیکرب۔ اشعث بن قیس کے بھائی۔ ابن شاہین نے ان کا ذکر کیا اور بحوالہ ابن کلبی لکھا ہے: اپنے بھائی کے ساتھ آئے، نبی صلی اللہ علیہ وسلم نے انہیں اذان دینے کا حکم دیا تو آخری دم تک اذان دیتے رہے۔ بقول ابو عمر(2): سیف، قیس بن معدیکرب کی اولاد میں سے ہیں اور صحابی ہیں۔ بغوی کی روایت ہے کہ سیف جو قیس بن معدیکرب کی اولاد سے ہیں، فرمایا: میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے اپنی قوم میں اذان دینے کی خدمت سونپ دیجئے۔ چنانچہ آپ نے انہیں یہ ذمہ داری بخش دی۔ ابن مندہ کے ہاں سیف بن معدیکرب اپنے دادا کے حوالہ سے لکھے ہوئے ہیں۔ جس کی وجہ سے ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کر دیا اور ابن الاثیر نے ان کا تعاقب کیا ہے۔ ابن کلبی(3) فرماتے ہیں: ان سیف کی والدہ تھی قینہ (سخافتہ) حضرموت کی ایک کھاتے پیتے گھرانے کی خاتون تھیں۔","",{"fn":"(1) اسد الغابہ (۲۳۶۴) استیعاب (۱۱۵۸)\n(2) اسد الغابہ (۲/۲۴۹)\n(3) اسد الغابہ (۲۳۷۰) استیعاب (۱۱۵۹)"}],[3630,"§۳۶۳۶ ۔ سیمویہ(1)\nبقول بعض: سیماہ بلقاوی، پہلے نصرانی تھے، مدینہ تجارت کی غرض سے آئے تو مسلمان ہو گئے۔ طبرانی، ابن قانع اور ابن مندہ کی روایت ہے، سیمویہ نے بیان کیا، جبکہ ابن قانع کی روایت میں سیماہ ہے۔ فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو دیکھا اور آپ صلی اللہ علیہ وسلم کی زبان کی بات سنی اور بلقاء سے مدینہ گندم لے کر گیا، جسے بیچ کر ہم نے کھجور خریدنا چاہی تو لوگوں نے منع کیا۔ ہم نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم لوگوں کے لیے اس کھجور کی گراں بہاری کے عوض جسے تم ہٹائے پھر رہے ہو اس اناج کے بھاؤ (ریٹ) کافی نہیں۔ چھوڑو انہیں اٹھانے دو۔ سیمویہ نصرانی تھے، پھر اسلام قبول کیا اور ان کا اسلام سنور گیا۔ ایک سو بیس(۱۲۰) تک زندہ رہے، المؤتلف میں ان کی حدیث کے سیاق سے معلوم ہوتا ہے کہ نبی صلی اللہ علیہ وسلم کے بعد مسلمان ہوئے۔","",{"fn":"(1) المعجم الکبیر (۷/۶۷۲۵)"}],[3631,"§۳۶۳۷ ۔ ساعدہ بن حرام(1)(2)\nبن محیصہ انصاری اوسی۔ بقول ابن مندہ: امام بخاری رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے، لیکن ان کی کوئی روایت نہیں نقل کی۔ پھر مجھے تاریخ بخاری میں بطریق ابن اسحاق بحوالہ بشیر بن یسار یہ روایت مل گئی کہ ساعدہ بن حرام بن محیصہ نے ان سے بیان کیا کہ محیصہ کا ایک حجام تھا۔ جس کا نام ابو طیبہ تھا۔ (حدیث) اس میں “اس کمائی سے اپنے اونٹ کے لیے چارہ خرید لو”(3)۔ ابن عبد البر(4) فرماتے ہیں: میرے نزدیک یہ حدیث مرسل ہے۔ میں کہتا ہوں: محیصہ بلاشبہ صحابی ہیں اور ان کے بیٹے حرام بن محیصہ کا تذکرہ ہو چکا ہے۔ رہے ساعدہ تو ان کے بارے احتمال ہے انہیں دیدار نبوی نصیب ہوا ہو کیونکہ ابن حبان(5) نے انہیں ثقات التابعین میں ذکر کیا ہے کہ مراسیل روایت کرتے ہیں، امام مالک نے “موطا” میں بواسطہ ابن شہاب بحوالہ ابن محیصہ، جو بنی حارثہ کے ایک فرد ہیں، روایت نقل کی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سینگھی لگانے کی اجرت کی اجازت چاہی تو آپ صلی اللہ علیہ وسلم نے انہیں منع فرمایا۔ (حدیث) ایسا ہی ابن قاسم اور یحییٰ بن یحییٰ نے کہا ہے، جبکہ جمہور راویوں کا کہنا ہے: ابن شہاب، ابن محیصہ سے وہ اپنے والد سے روایت کرتے ہیں۔ ابو عمر(6) لکھتے ہیں: اس میں تو اختلاف نہیں کہ زہری کے شیخ حرام بن سعد بن محیصہ ہیں، یعنی پھر حدیث مسند سعد بن محیصہ کی ہے۔","",{"fn":"(1) اسد الغابہ (۱۸۸۷) استیعاب (۸۸۰) تجرید (۱/۲۰۳)\n(2) التاریخ الکبیر (۱/۲۱۰)\n(3) مسند احمد (۵/۴۳۶)\n(4) استیعاب (۲/۱۲۴)\n(5) الثقات (۴/۳۵۰)\n(6) استیعاب (۲/۱۲۴)"}],[3632,"§۳۶۳۸ ۔ سائب بن ابی لبابہ(1)\nبن عبد المنذر انصاری۔ ابن سعد کا بیان ہے: عہد نبوی میں پیدا ہوئے۔ ابن حبان(2) ثقات التابعین میں لکھتے ہیں: انہوں نے سیدنا عمر رضی اللہ عنہ سے روایت کی: ایک قول ہے انہیں دیدار حاصل ہے، اسے ابن مندہ نے صحیح سے بیان کیا ہے، صدی کے بعد فوت ہوئے۔ ابو داؤد نے ان کی ایک حدیث بطریق حسین بن سائب بن ابی لبابہ انہوں نے اپنے والد سے تعلیقا نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۲۱) استیعاب (۹۰۳)\n(2) الثقات (۴/۳۲۵)"}],[3633,"§۳۶۳۹ ۔ سائب بن ہشام(1)\nبن عمرو بن ربیعہ قرشی عامری۔ بقول ابن ماکولا(2): فتح مصر میں شریک تھے، ایک قول ہے: انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے۔ اور مصر میں مسلمہ بن مخلد کی پولیس کے سربراہ تھے، جو قریش کے بزدل آدمی تھے۔ ابن یونس کے کلام سے معلوم ہوتا ہے: وہ مصر میں عہدہ قضاء اور پولیس کے نگران تھے۔ ابن ماکولا کے علاوہ کسی نے ذکر کیا ہے کہ مسلمہ نے سلیم بن عتر کے بعد انہیں مقرر کیا اور کچھ ہی عرصہ بعد معزول کر دیا تھا، کیونکہ مسلمہ کو ان کی یہ بات پہنچی تھی کہ قاضی کے لیے امیر گورنر کے پاس جانا مناسب نہیں، بلکہ امیر کو قاضی کے پاس آنا چاہیے، اس لیے انہیں معزول کر دیا اور عابس کو نامزد کر دیا۔ کندی نے مصر کے قاضیوں میں سلیم اور عابس کے درمیان کسی کا ذکر نہیں کیا۔ یہ بھی ذکر کیا جاتا ہے کہ جب مصر میں خارجہ بن حذافہ قتل ہوئے تو ان کی خبر یہی لائے۔","",{"fn":"(1) اسد الغابہ (۱۹۲۴)\n(2) الاکمال (۷/۱۷۲)"}],[3634,"§۳۶۴۰ ۔ سعد بن زید انصاری(1)\nاز بنی عمرو بن عوف۔ ابن سعد کا بیان ہے: عہد نبوی میں پیدا ہوئے۔ سیدنا عمر رضی اللہ عنہ سے روایت کی ہے عبد الملک کی خلافت کے اخیر میں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۲۰۰۱) استیعاب (۹۴۱)"}],[3635,"§۳۶۴۱ ۔ سعد بن ابی العادیہ\nیار بن سبع المزنی۔ بقول بعض: الجہنی۔ ابن عساکر فرماتے ہیں: عہد نبوی میں پیدا ہوئے، اور پھر ان کے حوالہ سے ایک حدیث نقل کی کہ نبی صلی اللہ علیہ وسلم نے ابو العادیہ کو نماز میں نہ پایا، اتنے میں آگئے تو فرمایا: “کس وجہ سے پیچھے رہ گئے؟” عرض کی: گھر میں بچے کی ولادت تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اس کا کوئی نام رکھا ہے؟” عرض کی: نہیں۔ فرمایا: “جاؤ اسے لے آؤ”۔ وہ لے کر آئے،(1) آپ صلی اللہ علیہ وسلم نے اس کے سر پر ہاتھ پھیرا اور اس کا نام سعد رکھا۔","",{"fn":"(1) تہذیب تاریخ دمشق (۶/۱۱۶)"}],[3636,"§۳۶۴۲ ۔ سعید بن ثابت\nبن الجدع۔ ان کے والد طائف میں شہید ہوئے۔ سیف نے الفتوح میں عبد اللہ بن سعید بن ثابت بن الجدع سے ایک حدیث نقل کی ہے۔"],[3637,"§۳۶۴۳ ۔ سعید بن حارث\nبن نوفل بن عبد المطلب ہاشمی۔ ان کے والد پندرہ (۱۵ھ) میں فوت ہوئے، جیسا کہ پہلے بیان ہو چکا ہے۔ سعید فقیہ تھے۔ زبیر بن بکار کا قول ہے: یہ یزید بن عبد الملک نوفلی کے نانا ہیں، ان کی والدہ کا نام اُم عبد اللہ ہے۔"],[3638,"§۳۶۴۴ ۔ سفیان بن عبد شمس\nابن ابی وقاص زہری۔ سیدنا علی رضی اللہ عنہ کی جنگ میں ان کا ذکر ہے۔ انہوں نے ہی حجاز آپ کی وفات کی اطلاع دی۔ طبرانی(1) کی روایت ہے کہ یہ وہی ہیں جنہوں نے امیر معاویہ سے عمرو بن عاص تک سیدنا علی رضی اللہ عنہ کی وفات کی خبر پہنچائی تھی۔ میں کہتا ہوں: میں نے ان کا اس قسم میں اس لیے ذکر کیا ہے کہ ان کے والد کفر پر مرے، شاید وہ فتح سے پہلے مرے ہیں۔ اس لیے کہ مجھے انساب تاریخ اور مغازی کی کتابوں میں ان کا ذکر نہیں ملا۔ تو اگر یہ صحابی نہیں تو اس قسم میں شامل ہیں۔ واللہ اعلم۔","",{"fn":"(1) المعجم الکبیر (۱/۱۶۸)"}],[3639,"§۳۶۴۵ ۔ سلمہ بن طریف\nبن ابان بن سلمہ بن حارثہ بن فہم فہمی۔ ان کے والد صحابی ہیں اور انہیں دیدار حاصل ہے۔ ان کا بیٹا حنیفہ (حذیفہ) بن قیس بن سلمہ بن طریف سیدنا حسین بن علی رضی اللہ عنہ کے ساتھ الطف کے روز شہید ہوا۔"],[3640,"§۳۶۴۶ ۔ سلیم بن احمر\nاحمر بن سلیم میں ذکر ہوا ہے۔"],[3641,"§۳۶۴۷ ۔ سلیمان بن ابی حثمہ(1)\nبن غانم بن عامر بن عبد اللہ بن عوف بن کعب قرشی عدوی۔ بقول ابن حبان(2): صحابی ہیں۔ ابو عمر(3) فرماتے ہیں: اپنی والدہ کے ہمراہ مدینہ گئے۔ صاحب فضیلت اور نیک انسان تھے۔ سیدنا عمر رضی اللہ عنہ نے بازار کی نگرانی انہیں سونپی اور رمضان(4) میں لوگوں کو ان کی اقتداء میں تراویح پڑھنے کا حکم دیا۔ میں کہتا ہوں: یہ سارا مصعب زبیری کا کلام تھا، جو ان سے زبیر بن بکار نے نقل کیا ہے۔ ابن سعد نے انہیں ان لوگوں میں شمار کیا ہے جنہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا لیکن آپ کی کوئی بات نہ یاد رکھ سکے۔ اور ان کے والد کو فتح مکہ کے مسلمانوں میں ذکر کیا ہے اور اہل مدینہ کے تابعین کے پہلے طبقے میں لکھتے ہیں: نبی صلی اللہ علیہ وسلم کے دور میں پیدا ہوئے۔ اور خلیفہ نے اہل مدینہ کے پہلے طبقہ میں ان کا ذکر کیا ہے، ابن مندہ فرماتے ہیں: سلیمان بن ابی حثمہ انصاری کا صحابہ میں ذکر تو ملتا ہے لیکن صحیح ثابت نہیں۔ پھر ایک روایت کی “رسول اللہ صلی اللہ علیہ وسلم ہمارے (مردوں کے) جنازوں میں چار یا پانچ تکبیریں کہتے تھے”۔ میں کہتا ہوں: ان کا ”انصاری“ کہنا وہم ہے۔ عبد الرزاق نے معمر، زہری، سلیمان بن ابی حثمہ بحوالہ ان کے والد شفاء روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ ہمارے گھر تشریف لائے جہاں میرا خاوند ابو حثمہ اور بیٹا سلیمان سوئے ہوئے تھے، فرمانے لگے: کیا انہوں نے فجر کی نماز پڑھی؟ میں نے بتایا کہ یہ دونوں رات بھر نماز پڑھتے رہے، پھر فجر کی نماز جلدی پڑھ کر سو گئے۔ فرمایا: میں فجر کی نماز باجماعت پڑھوں یہ مجھے پوری رات قیام کرنے سے زیادہ پسند ہے۔ یہی روایت ابن جریج نے نقل کی ہے۔ شفاء سیدنا عمر رضی اللہ عنہ کے ہاں آئیں۔ آپ نے فرمایا: کیا بات ہے؟ مجھے ابو حثمہ نہیں نظر آیا۔ کہنے لگیں ان کی وہی رات کی عبادت والی عادت ہے، تھکاوٹ کی وجہ سے نہ نکل سکے اس لیے فجر کی نماز پڑھ کر سو گئے۔ پھر اسی کا مفہوم نقل کیا۔ یہی روایت امام مالک نے بواسطہ ابن شہاب بحوالہ ابو بکر بن سلیمان بن ابی حثمہ نقل کی ہے کہ سیدنا عمر رضی اللہ عنہ نے نماز فجر میں سلیمان بن ابی حثمہ کو نہ پا کر ان کے گھر کا رخ کیا، شفاء کے ہاں گئے، ان سے پوچھا۔ زبیر بن بکار کا قول ہے: اذرح میں تحکیم کے دور میں لوگوں نے سلیمان بن ابی حثمہ کی امامت نماز پر اتفاق کر لیا جو عمر رسیدہ قاری تھے۔","",{"fn":"(1) اسد الغابہ (۲۲۲۸) استیعاب (۱۰۶۰) (۲/۲۱۰) تجرید (۱/۲۲۷)\n(2) الثقات (۳/۱۶۱)\n(3) استیعاب (۲/۲۱۰)\n(4) السنن الکبریٰ (۲/۴۴۱) (۳/۲۹۰) (۴/۳۵) اتحاف السادۃ المتقین (۴۰۱۳) جامع المسانید (۵/۵۱۰)"}],[3642,"§۳۶۴۸ ۔ سلیمان بن خالد\nبن ولید بن مغیرہ مخزومی۔ یہی کنیت تھی۔ ان کے سب سے بڑے صاحبزادے تھے۔ زہیر بن بکار کا قول ہے: ان کی والدہ کا نام کبشہ بنت ہوذہ بن ابی عمرو عذر یہ ہے۔"],[3643,"§۳۶۴۹ ۔ سلیمان بن ہاشم(1)\nبن عقبہ بن ابی وقاص زہری۔ ان کے والد صحابی ہیں۔ ابن مندہ کی روایت ہے: سلیمان بن ہاشم کو رسول اللہ صلی اللہ علیہ وسلم کے پاس لا کر آپ صلی اللہ علیہ وسلم کی گود میں رکھا گیا۔ انہوں نے اسی وقت پیشاب کر دیا پانی کا برتن لا کر اس پیشاب پر پانی بہایا۔ ابن الاثیر(2) کا گمان ہے: “مذکورہ عقبہ کے والد کا نام ربیعہ بن عبد شمس ہے”۔ جس میں تامل ہے، کیونکہ امام بخاری رحمہ اللہ نے محمد بن اسماعیل بن سعد بن ابی وقاص کے حالات میں لکھا ہے کہ نبی صلی اللہ علیہ وسلم کے پاس سلیمان بن ہاشم بن ابی وقاص کو لایا گیا، انہوں نے پیشاب کر دیا تھا، اس لیے آپ صلی اللہ علیہ وسلم نے ان کے پیشاب پر پانی بہایا۔(3) اگرچہ اس روایت میں کچھ خلاف ہے لیکن اس کا ایک شاہد ہے، کیونکہ یہ واقعہ آل ابی وقاص کے کسی شخص کے ساتھ پیش آیا، نہ کہ آل ربیعہ بن عبد شمس کے ساتھ۔ نیز اہل نسب نے آل عتبہ بن ربیعہ میں سلیمان بن ہاشم نامی کسی شخص کا تذکرہ نہیں کیا۔ جبکہ آل ابی وقاص میں ان کا ذکر کیا ہے۔ اس واسطے میری بات ثابت ہوئی۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۲۲۳۳) تجرید (۱/۲۵۲۲)\n(2) اسد الغابہ (۲۳۷۴)\n(3) التاریخ الکبیر (۱/۳۵، ۳۶) اسد الغابہ (۲/۳۷۴)"}],[3644,"§۳۶۵۰ ۔ سنان بن سلمہ(1)\nبن المحبق الہذلی۔ ان کے والد صحابی ہیں۔ ابن ابی حاتم مراسیل میں لکھتے ہیں: ابو زرعہ سے سنان بن سلمہ کے بارے میں پوچھا گیا آیا یہ صحابی ہیں؟ تو انہوں نے فرمایا نہیں، البتہ عہد نبوی میں پیدا ہوئے ہیں۔ ابن الاعرابی کا قول ہے حنین کے روز پیدا ہوئے کسی نے ان کے والد کو ولادت کی خوشخبری دی تو وہ فرمانے لگے: جو تیر میں اللہ کی راہ میں چلا رہا ہوں وہ مجھے اس خوشخبری سے کہیں زیادہ محبوب ہے۔ تو نبی صلی اللہ علیہ وسلم نے ان کا نام ہی سنان“ رکھ دیا۔ وکیع نے بواسطہ اپنے والد بحوالہ سنان بن سلمہ روایت کی ہے کہ میں نبی صلی اللہ علیہ وسلم کی جنگ کے روز پیدا ہوا، آپ صلی اللہ علیہ وسلم نے میرا نام سنان رکھا۔ عسکری کا قول ہے: سنان فتح مکہ کے بعد پیدا ہوئے، نبی صلی اللہ علیہ وسلم نے ان کا نام رکھا، وہ بڑے بہادر اور قوی انسان تھے۔(2) میں کہتا ہوں: سنان نے اپنے والد، سیدنا عمر اور ابن عباس رضی اللہ عنہم سے روایت کی ہے اور نبی صلی اللہ علیہ وسلم سے مرسل روایت کرتے ہیں۔ بحوالہ نبی صلی اللہ علیہ وسلم کی ان کی حدیث طبرانی میں ہے، جس کے الفاظ یہ ہیں: آپ صلی اللہ علیہ وسلم نے اپنے ساتھ ہدی کے جانور روانہ فرمائے۔ (حدیث) یہ روایت بطریق فریابی نقل کی ہے جس میں ثوری اور ان کے شیخ سے آگے اختلاف ہے۔ چنانچہ ابن جریج نے عبد الکریم سے انہوں نے معاذ سے بواسطہ سنان بن سلمہ انہوں نے بحوالہ اپنے والد نقل کی ہے جسے امام احمد رحمہ اللہ نے محمد بن بکر سے بحوالہ ان کے نقل کیا ہے۔ ابو عاصم نے ابن جریج اور دار قطنی(3) نے ایک اور طریق سے بحوالہ ابو عاصم روایت کی ہے ان سے قتادہ مسلم بن جنادہ وغیرہ روایت لیتے ہیں۔ بصرہ فروکش ہوئے تھے، خلیفہ کا قول ہے زیاد نے ہندوستان کی جنگ کا انہیں پچاس (۵۰ھ) میں ذمہ دار بنایا تھا، جس میں ان کا عجیب واقعہ ہے۔ عمر بن شبہ کا قول ہے جب مصعب بہتر (۷۲ھ) میں عبد الملک بن مروان سے جنگ کرنے نکلے تو انہیں بصرہ کا والی بنایا۔ ابن سعد نے اہل بصرہ کے تابعین میں پہلے طبقے میں ان کا ذکر کیا ہے۔ عجلی کا قول ہے: ثقہ تابعی ہیں۔ ابن حبان کتاب الصحابہ میں لکھتے ہیں: حجاج کی گورنری کے آخری ایام میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۲۶۰) استیعاب (۱۰۷۶) تجرید (۱/۲۵۲۲)\n(2) الطبقات (۷/۱۲۴) التاریخ الکبیر (۴/۱۶۲) استیعاب (۲/۲۱۷)\n(3) السنن الدارقطنی (۴/۲۰۰) المستدرک (۴/۳۴۸) المعجم الکبیر (۶۴۹۳) کنز العمال (۳۷۴۵۳)"}],[3645,"§۳۶۵۱ ۔ ساریہ بن عمرو الحنفی\nابن ماکولا(1) نے ان کا ذکر کیا ہے کہ انہوں نے ہی سیدنا خالد بن ولید رضی اللہ عنہ سے کہا تھا: اگر آپ کو اہل یمامہ سے کوئی کام ہے تو اسے (یعنی مجاعہ بن مرارہ کو) باقی رہنے دو۔","",{"fn":"(1) الثقات (۳/۱۷۸)"}],[3646,"§۳۶۵۲ ۔ ساعدہ بن جوین\nبقول بعض: ابن جوینہ۔ مخضرمی شاعر ہیں۔ مرزبانی نے ان کا ذکر کیا ہے اور ان کے اشعار نقل کئے ہیں۔ ابو القاسم حسن بن بشر آمدی کا قول ہے: ساعدہ بن جوین بنی کعب بن کاہل بن حارث بن سعد کے ایک فرد ہیں۔ جاہلی دور کے اچھے شاعر ہیں۔ ان کے اشعار زیادہ تر غریب الفاظ پر مشتمل ہوتے ہیں۔ جن میں گہرے معانی پائے جاتے ہیں۔ چنانچہ تلوار کی تعریف میں کہتے ہیں: “تو اس کا اثر اس کی دونوں جانبوں میں دیکھے گا، گویا وہ مکڑی کے رستے ہیں جن میں وہ آہستہ آہستہ چلتی ہے۔”"],[3647,"§۳۶۵۳ ۔ ساعدہ بن عجلان ہذلی(1)\nان کا بھی مرزبانی نے ذکر کیا ہے۔ مخضرمی شاعر ہیں۔ پیدل غارت گری کرتے تھے۔","",{"fn":"(1) الاکمال (۲/۱۶)"}],[3648,"§۳۶۵۴ ۔ سالم بن دارہ(1)\nوہی ابن مسافع، تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۱۸۸۸) استیعاب (۸۸۱)"}],[3649,"§۳۶۵۵ ۔ سالم بن ربیعہ\nانہیں دور نبوت نصیب ہوا۔ قدامی کا بیان ہے وہ خلافت صدیقی میں جنگ محل میں شریک ہوئے۔ نضر بن صالح نے ان سے روایت کی، فرماتے ہیں: مصعب بن زبیر کے دور میں میری ان سے ملاقات ہوئی تھی۔"],[3650,"§۳۶۵۶ ۔ سالم بن سالم عبسی(1)\nابو شداد۔ کنیتوں میں تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۱۸۹۵) استیعاب (۸۸۲)"}],[3651,"§۳۶۵۷ ۔ سالم بن ستہ\nابن الاشیم، ابن ظفر بن مالک بن عثمان بن طریف طائی۔ انہیں سالم صفار بھی کہا جاتا ہے۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے۔ بلاذری نے ان کا ذکر کیا ہے، ان کا بیٹا نفیح بن سالم شاعر تھا جو اخطل سے عبد الملک کی خلافت میں ہجو کا مقابلہ کرتا تھا۔"],[3652,"§۳۶۵۸ ۔ سالم (مولا قدامہ بن مظعون)\nانہیں دور نبوی صلی اللہ علیہ وسلم نصیب ہوا۔ “التمہید” میں ابو عمر لکھتے ہیں: عبد الملک بن ماجشون نے فرمایا: ہمیں یہ بات معلوم ہوئی کہ سیدنا عمر رضی اللہ عنہ نے قدامہ بن مظعون کے مولا، جنہیں سالم کہا جاتا تھا، سے فرمایا: تم جس شخص کو مدینہ کا سمر نامی درخت کاٹتے دیکھو اس کا کلہاڑا لے لو۔ انہوں نے کہا: امیر المومنین اس کا کپڑا بھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں۔"],[3653,"§۳۶۵۹ ۔ سالم بن مسافع بن دارہ، مشہور شاعر\nبقول ابو الفرج اصبہانی: دور جاہلیت اور اسلام پایا ہے۔ دارہ ان کے دادا کا لقب ہے، ان کا نام مربوع بن کعب بن عدی بن جشم بن بھٹہ بن عبد اللہ بن غطفان ہے۔ ابو عبیدہ نے ان کا ذکر کیا ہے کہ ان کا بھائی عبد الرحمن بن دارہ بھی اسلام کا شاعر ہے۔ مرزبانی لکھتے ہیں: سالم بن مسافع بن عقبہ بن شریح بن مربوع، پھر ان کا نسب بیان کر کے فرمایا: بقول بعض دارہ خود سالم کی والدہ ہیں۔ ایک قول ہے: ان کی دادی ہیں۔ تیسرا قول ہے: مسافع کے دادا شریح کا لقب ہے۔ میں نے “کلیاتِ سالم” میں پڑھا ہے کہ وہ خلافت عثمانی میں قتل ہوئے۔ زمیل بن ام دینار فزاری نے انہیں قتل کیا، کیونکہ انہوں نے اشعار کے ذریعہ اس کی ہجو کی تھی: “جب تو کسی فزاری کے ساتھ تنہا ہو تو ہرگز اس پر اپنی اونٹنیوں کے ہارے بھروسا نہ کرنا، بلکہ انہیں تسموں کے ساتھ باندھ لینا۔” اسی میں کہتے ہیں: “میں دارہ کا بیٹا ہوں جس سے میرا نسب ملا ہوا ہے۔ تو کیا لوگو! تم ہی بتاؤ دارہ کے ساتھ کوئی جنگ و عار ہے”۔ میں کہتا ہوں: اس سے معلوم ہوتا ہے ان کے دادا کا لقب دارہ تھا، جیسا کہ ابو عبیدہ کا قول ہے جس کے متعلق کہا گیا ہے: “اس کے متعلق زیادہ شور نہ کرو کیونکہ جو کچھ ابن دارہ نے کہا اس سب کو تلوار مٹا دے گی”۔ طبقات الشعراء میں دعبل بن علی لکھتے ہیں: انہوں نے عیینہ بن حصن کو مخاطب کر کے کہا جب وہ مرتد ہو کر پھر سے مسلمان ہو گئے تھے، عیینہ نے سیدنا ابو بکر رضی اللہ عنہ سے کہا: میرا اور اشعث کا ایک جیسا واقعہ ہے، پھر کیا وجہ ہے کہ آپ اس کی عزت کریں اور اس سے اپنی بہن کا نکاح کر دیں اور مجھ سے ایسا سلوک روا نہ رکھیں؟ سیدنا ابو بکر رضی اللہ عنہ نے اشعث کو اپنی بہن کا رشتہ دیا تھا تو سالم بن دارہ نے عیینہ کو اس کا یوں جواب دیا: “اے عیینہ بن حصن! جس کا تعلق آل عدی سے ہے، تو اپنی سخت قوم میں سے خالص ہے تو اشعث کی طرح نہیں جسے تاج پہنایا گیا جب وہ لڑکا ہی تھا اور ابھی اس کا دودھ نہیں چھوٹا تھا تو وہ سردار بن گیا تھا۔ اس کا دادا آکل المرار ہے۔ اور نہیں جس کا مرتبہ بادشاہوں میں بہت بڑا تھا، اگرچہ تم دونوں نے غداری کی تو برابر ہے جیسے یہ چھڑا کاٹا جاتا ہے۔ تو اسے بادشاہوں کا سا دبدبہ حاصل ہے یہی مقام اشعث کا ہے خواہ پرانا ہو خواہ نیا۔ اشعث بن قیس بن معدی کرب کو جو عزت و مقام حاصل ہے جبکہ تم میں اس کا شائبہ تک نہیں”۔"],[3654,"§۳۶۶۰ ۔ سالم بن ہبیرہ الحضرمی\nنبی صلی اللہ علیہ وسلم کے عہد میں مسلمان ہوئے اور اشعار میں آپ صلی اللہ علیہ وسلم کا مرثیہ کہا۔ سعید بن یحییٰ اموی نے اپنے “مغازی” میں ان کا ذکر کیا ہے۔"],[3655,"§۳۶۶۱ ۔ سائب بن حارث بن حزن ہلالی\nمیمونہ بنت حارث ام المومنین کے بھائی، ان کا نسب ان کے بھائی قطن کے حالات میں بیان ہوگا۔"],[3656,"§۳۶۶۲ ۔ سائب بن مہجان(1)\nانہیں دور نبوی نصیب ہوا۔ ابن وہب کی سعید بن عبد الرحمن سے بحوالہ سائب بن مہجان جو ایلیاء کے ایک شخص ہیں جنہوں نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے، فرماتے ہیں: جب سیدنا عمر رضی اللہ عنہ داخل ہوئے تو اللہ تعالیٰ کی حمد و ثناء کے بعد فرمایا: “رسول اللہ صلی اللہ علیہ وسلم بھی ہم میں اس طرح کھڑے ہوئے تھے جیسے تم لوگوں کے درمیان میں کھڑے ہو کر خطاب کر رہے ہو۔ آپ صلی اللہ علیہ وسلم نے اللہ تعالیٰ سے ڈرنے کا حکم دیا۔ (حدیث) یہ روایت ابن عساکر(2) نے بطریق جعفر بن احمد بن سنان بواسطہ عباس دوری، ہارون بن معروف سے بحوالہ ابن مصعب نقل کی ہے۔ ایک اور طریق سے بحوالہ ابن عباس رضی اللہ عنہما مروی ہے لیکن اس میں فرماتے ہیں: انہوں نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ ایسا ہی امام بخاری رحمہ اللہ نے یحییٰ بن سلیمان سے بحوالہ ابن وہب نقل کیا ہے۔ ابو زرعہ دمشقی نے اہل شام کے تابعین میں سے اونچے طبقے میں ان کا ذکر کیا ہے۔ یہی طرز ابن سمیع نے اختیار کی ہے۔ ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے(3) کہ انہوں نے سیدنا عمر رضی اللہ عنہ کا دور پایا ہے۔","",{"fn":"(1) مختصر تاریخ دمشق (۲۰/۱۰۲)\n(2) حوالہ گزر چکا ہے۔\n(3) التاریخ الکبیر (۲/۱۵۵)"}],[3657,"§۳۶۶۳ ۔ سبیع بن قتادہ حنفی یمامی\nانہیں دور نبوی نصیب ہوا۔ کتاب الردہ میں واقدی لکھتے ہیں: یمامہ کے روز گرفتار ہوئے۔ عمر بہت زیادہ تھی۔ ان کے حوالہ سے ایسا کلام نقل کیا ہے جس سے پتہ چلتا ہے وہ اپنے اسلام پر ثابت قدم رہے۔ مسلمہ اور اس کی قوم کو مرتد ہونے سے روکا جس کی بناء پر خالد بن ولید رضی اللہ عنہ نے انہیں معذور سمجھا۔ واللہ اعلم"],[3658,"§۳۶۶۴ ۔ سخف\nایک بزرگ ہیں جنہوں نے دور جاہلیت پایا اور معاذ بن جبل رضی اللہ عنہ سے سماع کیا۔ امام بخاری رحمہ اللہ(1) نے اپنی تاریخ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۲/۲۱۴)"}],[3659,"§۳۶۶۵ ۔ سحبان وائل\nجن کا نام بطور مثال فصاحت و بلاغت میں بیان کیا جاتا ہے۔ ابن عساکر(1) نے اپنی تاریخ میں لکھا ہے: مجھے یہ روایت پہنچی ہے کہ وہ سیدنا امیر معاویہ رضی اللہ عنہ کے پاس آئے تھے۔ میں کہتا ہوں: اگر یہ بات ثابت ہو جائے تو وہ اسی قسم میں شامل ہوتے ہیں۔ جبکہ مشہور یہ ہے کہ وہ دور جاہلیت کے ہیں۔ ابو نعیم نے طبقات الخطباء میں لکھا ہے: سحبان عرب کے بلا مقابلہ خطیب تھے وہ جب ایک بار خطاب کرتے تو دوبارہ وہ جملہ نہ دہراتے نہ بات کو دوبارہ شروع کرتے نہ رکتے، اور نہ سوچتے، بلکہ ان کی زبان ایسے چلتی جیسے پانی جاری ہو۔","",{"fn":"(1) مختصر تاریخ دمشق (۲۰/۱۴۳)"}],[3660,"§۳۶۶۶ ۔ سحیم (بنی حسحاس کے غلام)\nمشہور مخضرمی شاعر ہیں۔ ابو الفرج اصبہانی کی روایت ہے: سحیم سیاہ فام غلام تھے جنہوں نے دور نبوی پایا ہے۔ آپ صلی اللہ علیہ وسلم نے ایک دفعہ ان کا کوئی شعر بھی دہرایا۔ مرزبانی ان کے حالات میں اور دینوری مجالسہ میں لکھتے ہیں: علی بن زید بحوالہ حسن روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آدمی کو اسلام اور بڑھاپا روکنے کے لیے کافی ہے۔“ جس پر سیدنا ابو بکر رضی اللہ عنہ بولے: یہ بات ایک شاعر نے کہی ہے: بڑھاپا اور اسلام آدمی کو روکنے کے لیے کافی ہے۔ محملا تو نبی علیہ السلام(1) نے جیسا پہلے فرمایا تھا پھر اسی طرح اعادہ کیا۔ جس پر صدیق اکبر رضی اللہ عنہ بولے: میں گواہی دیتا ہوں کہ آپ صلی اللہ علیہ وسلم واقعی اللہ کے رسول ہیں۔ ”ہم نے انہیں شعر و شاعری سکھائی اور نہ ان کے لیے موزوں ہے”۔(2) عمر بن شبہ کا قول ہے: اس کے بعد سحیم سیدنا عمر رضی اللہ عنہ کے پاس آئے اور ان کے سامنے یہ قصیدہ پڑھا: “اگر تو نے کل تیاری کرنی ہے تو سلیمی کو الوداع کہہ دے۔ بڑھاپا اور اسلام آدمی کو روکنے کے لیے کافی ہیں۔” آپ نے فرمایا: اتنا کافی ہے۔ تم نے سچ کہا، تم نے سچ کہا۔ ابن سیرین سے مروی ہے کہ آپ نے ان سے فرمایا: اگر تم شبیب سے پہلے اسلام کا ذکر کرتے تو تمہارے لیے بہتر تھا۔ “الادب المفرد” میں امام بخاری رحمہ اللہ نے بحوالہ سیدنا عمر رضی اللہ عنہ روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ کی عادت تھی کہ دو پہر ڈھلنے کے بعد جس کے پاس سے گزرتے اسے ٹھہرا لیتے، اسی طرح ایک دن مولا بنی حساس شعر کہتا ہوا آیا، آپ نے اسے بلایا فرمایا: تم کیسے اشعار کہہ رہے تھے؟ تو انہوں نے یہ شعر سنایا: ودّع سلیمی ان تجہزت غادیا کفی الشیب والاسلام للمرء ناہیا بقول بعض: سحیم خلافت عثمانی میں قتل ہو گئے تھے۔ ایک قول ہے کہ ان کے قتل کا سبب یہ بنا کہ بنی حسحاس کی کسی خاتون کو یہودیوں کے کسی آدمی نے قید کر کے اپنے لیے مخصوص کر لیا اور اپنے خاص قلعہ میں ٹھہرا لیا۔ سحیم کو پتہ چلا اُسے غیرت آئی تو وہ وہاں تک پہنچنے کا حیلہ تلاش کرتا رہا، بالآخر دیوار پھلانگ کر یہودی کے پاس جا پہنچا، اسے قتل کر کے عورت کو چھڑا لیا اور اسے اپنی قوم کے پاس پہنچا دیا۔ پھر کسی دن اس عورت کی ملاقات سحیم سے ہوئی تو کہنے لگی: سحیم! میرا دل چاہتا ہے کاش میں تمہیں اس کا بدلہ دینے کی قدرت رکھتی جو تم نے مجھے یہودی کے ہاتھ سے آزاد کیا ہے۔ سحیم نے کہا: اللہ کی قسم! تمہیں اس کی قدرت ہے، اور اس کا اشارہ اسی کی طرف تھا۔ لیکن وہ شرما کر چلی گئی۔ پھر دوسری بار ملی تو پھر اس نے پیشکش کی تو وہ رضامند ہو گئی اور یہ اس پر عاشق ہو گیا اور اس کے متعلق غزلیں کہنے لگا۔ اس عورت کا نام سمیہ تھا۔ لوگوں نے بھانپ لیا اور اپنے لیے سمیہ کی وجہ سے ذلت و عار کے خوف سے سحیم کو قتل کر دیا۔ ابن حبیب کا قول ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے سحیم بنی حسحاس کے غلام کا یہ شعر سنایا: الحمد للہ حمدا لا انقطاع لہ فلیس احسانہ عنا بمقطوع “اللہ تعالیٰ کے لیے نہ ختم ہونے والی تعریف ہو کیونکہ ہم سے اس کا احسان کبھی ختم نہیں ہوتا”۔ آپ علیہ السلام نے فرمایا: ”بہتر، بہتر اور اس نے سچ کہا، اللہ تعالیٰ کا شکر اسی طرح کرنا چاہیے اگر (راہ حق پر) سیدھا رہا اور (حق کے) قریب رہا تو وہ جنتی ہے”۔","",{"fn":"(1) کنز العمال (۱۸۴۵۲) الطبقات (۱/۱۲۱۲) تفسیر القرطبی (۱۵/۵۲) زاد المسیر (۷/۳۴)\n(2) سورہ یس (۶۹)"}],[3661,"§۳۶۶۷ ۔ سحیم بن وثیل الریاحی\nمخضرمی شاعر ہیں۔ بقول ابن درید: جاہلیت میں چالیس(۴۰) اور اسلام میں ساٹھ(۶۰) سال زندہ رہے۔ زیاد ابن بابیہ کے ساتھ ان کے کئی واقعات ہیں۔ سمرہ بن عمر عنبری کے ساتھ ان کا واقعہ گزر چکا ہے۔ مرزبانی کا بیان ہے کہ انہوں نے اور غالب بن صعصعہ فرزدق کے والد نے فخر میں مقابلہ کیا دونوں نے اونٹ ذبح کیے، سیدنا علی رضی اللہ عنہ کو معلوم ہوا تو آپ نے فرمایا: اس میں سے کوئی نہ کھائے کیونکہ یہ غیر اللہ کے لیے ذبح ہوا ہے۔ یہی قصہ سعید بن منصور نے بحوالہ جارود بن ابی سمرہ نقل کیا ہے۔ واقعہ کا حاصل یہ ہے جو اہل تاریخ نے لکھا ہے کہ غالب اور سحیم چند دوستوں کے ساتھ سفر پر نکلے۔ ان لوگوں کے شہر خلافت عثمانی میں ویران ہو گئے تھے۔ قحط سالی تھی غالب نے ایک اونٹنی ذبح کی اور لوگوں کو کھانا کھلایا، سحیم نے بھی ایک اونٹنی ذبح کر ڈالی کسی نے غالب سے کہا: وہ تمہارا مقابلہ کرنا چاہتا ہے۔ غالب نے کہا: نہیں وہ بھی آدمی ہے۔ پھر غالب نے دو اونٹنیاں ذبح کیں۔ تو سحیم نے بھی دو اونٹنیاں ذبح کر ڈالیں۔ اس کے بعد غالب نے دس تو سحیم نے بھی دس ذبح کیں اس وقت غالب نے کہا: مجھے اب معلوم ہوا کہ وہ میرا مقابلہ کرنا چاہتا ہے، اس کے بعد غالب خاموش رہا یہاں تک کہ اس کے اونٹ گھاٹ پر اترے جن کی تعداد دو سو(۲۰۰) تھی۔ بقول بعض: چار سو(۴۰۰) تھے۔ جن میں سے میں کو ذبح کر دیا۔ لیکن سحیم نے کچھ بھی ذبح نہ کیا۔ جس کا تدارک خلافت علوی میں یوں کیا کہ کناسہ میں اتنی تعداد میں اونٹ ذبح کیے جس پر سیدنا علی رضی اللہ عنہ نے فرمایا: کوئی انہیں نہ کھائے۔ مرزبانی لکھتے ہیں: سحیم ہی نے یہ اشعار کہے ہیں: “میں چک کا بیٹا اور ٹیلوں پر چڑھنے والا ہوں، میں جب عمامہ (گڑی) اتارتا ہوں لوگ مجھے پہچان لیتے ہیں، شعراء کو مجھ سے کیا ملے گا جبکہ میں چالیس سے گزر چکا ہوں۔ پچاس سالہ ہوں اپنی کمر کس کر بیٹھا ہوں، حالات کی تبدیلی مجھے پھر سے بہتر بنا دیتی ہے۔”"],[3662,"§۳۶۶۸ ۔ سحیم مولا عتبہ بن فرقد\nانہیں دور نبوی صلی اللہ علیہ وسلم نصیب ہوا، ان کے مولا نے انہیں سیدنا عمر رضی اللہ عنہ کے پاس بھیجا تھا۔ بطریق ابو عثمان نہدی مروی ہے کہ میں عتبہ بن فرقد کے ساتھ آذربائیجان میں تھا۔ تو انہوں نے اپنا ایک مولا سحیم اور دوسرا تین میل کے فاصلے سے سیدنا عمر رضی اللہ عنہ کے پاس بھیجا۔ یہ آئے اور اپنا واقعہ بیان کیا اس کی سند صحیح ہے۔"],[3663,"§۳۶۶۹ ۔ سدیس العدوی\nانہیں دور نبوی صلی اللہ علیہ وسلم نصیب ہوا۔ ابو بکر بن ابی شیبہ بحوالہ سدیس عدوی روایت کرتے ہیں، فرمایا: ہم نے اللہ کا غزوہ کیا جس میں ہمیں فتح نصیب ہوئی۔ اس کے بعد ہم اھواز پہنچے، وہاں بھی کامیابی سے ہمکنار ہوئے اور وہاں کے بہت سے لوگ قیدی بنائے۔ باندیاں ملیں تو ہم ان سے ہم آغوش ہوئے۔ ہمارے امیر نے امیر المومنین عمر رضی اللہ عنہ کو لکھا پھر ایک واقعہ نقل کیا۔ شاید یہ سدیس ہیں جن کا تذکرہ شین میں ہوتا ہے، اس لیے لکھ لیا جائے۔"],[3664,"§۳۶۷۰ ۔ سراقہ (عبد الاعلیٰ کے والد)\nبقول ابن عساکر انہیں دور نبوی نصیب ہوا اور جنگ یرموک میں شریک ہوئے۔ پھر ان کی ایک روایت نقل کی: یرموک کے روز ہم سیدنا ابو ہریرہ رضی اللہ عنہ کے پاس آئے، آپ صلی اللہ علیہ وسلم فرما رہے تھے: ”حور عین کے لیے بن سنور کر رہو۔”"],[3665,"§۳۶۷۱ ۔ سرج الیرموکی\nکتابی ہیں، دور نبوی پایا ہے، آپ صلی اللہ علیہ وسلم کے بعد مسلمان ہوئے۔ الکنی میں دولابی لکھتے ہیں کہ سرج یرموکی نے فرمایا: میں سابقہ کتابوں میں یہ نشانی لکھی ہوئی پاتا ہوں کہ بارہ سردار ہوں گے ان میں سے ایک ان کا نبی ہوگا جب یہ تعداد پوری ہو جائے گی تو پھر سرکشی اور بغاوت سر اٹھائے گی، خانہ جنگی ہوگی۔ فرماتے ہیں: عبد اللہ بن عمر رضی اللہ عنہما بھی ان سرج سے تعلیم حاصل کرتے تھے۔(1)","",{"fn":"(1) مختصر تاریخ دمشق (۹/۲۱۴)"}],[3666,"§۳۶۷۲ ۔ سعد بن ایاس(1)\nبن ابی ایاس ابو عمرو شیبانی۔ دور نبوی پایا ہے۔ آپ علیہ السلام کی وفات کے بعد مدینہ آئے، پھر کوفہ فروکش ہوئے۔ ناقدین کا ان کے ثقہ ہونے پر اتفاق ہے۔ طبرانی(2) کی روایت ہے کہ ابو عمرو شیبانی نے فرمایا: ہمیں نبی صلی اللہ علیہ وسلم کے مبعوث ہونے کی اطلاع ملی، میں اس وقت اپنے خاندان کے اونٹ کا ظمہ میں چرا رہا تھا۔ بقول بعض: انہوں نے نبی علیہ السلام کی زندگی کے چالیس سال پائے ہیں، جبکہ دوسرا قول زیادہ صحیح ہے۔ انہوں نے ابو مسعود علی اور حذیفہ وغیرہ صحابہ کرام رضی اللہ عنہم سے روایت کی ہے، جبکہ ان سے روایت کرنے والوں میں ابو اسحاق شیبانی، حارث بن شبل ولید بن عیزار اور اعمش وغیرہ شامل ہیں۔ اسماعیل بن خالد کا قول ہے: ایک سو بیس(۱۲۰) سال زندہ رہے۔ میں کہتا ہوں: لگتا ہے چھیانوے (۹۶ھ) میں ان کا انتقال ہوا ہے۔ ابن عبد البر نے ان کی تاریخ وفات پچانوے (۹۵ھ) لکھی ہے، جو اس کے قریب ہے۔ ادھر ابن حبان کا گمان ہے کہ جنگ قادسیہ اکیس (۲۱ھ) میں ہوئی اس لیے ان کا انتقال ایک سو ایک (۱۰۱ھ) میں ہوا ہو گا۔ ابن حبان نے ان کا نام سعید بتایا ہے۔ ابو نعیم لکھتے ہیں: سعد یا سعید، سعد زیادہ صحیح ہے، کنیت سے مشہور ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۶۹) استیعاب (۹۲۴) تجرید (۱/۲۱۱)\n(2) المعجم الکبیر (۶/۵۵۳۲) استیعاب (۲/۱۵۰)"}],[3667,"§۳۶۷۳ ۔ سعد بن بالویہ فارسی\nجن لوگوں نے اسود عنسی کے قتل میں مدد پہنچائی تھی ان میں شامل ہیں۔ واقدی نے الردہ میں بیان کیا ہے جب اسود قتل ہو گیا تو یہی سعد چند مسلمانوں کے ساتھ کھڑے ہو گئے، وہاں سے جو بھی اسود کا ساتھی گزرتا، جو کہتا: وہ کذاب تھا اسے چھوڑ دیتے ورنہ قتل کر دیتے تھے۔"],[3668,"§۳۶۷۴ ۔ سعد بن بکر\nانہیں شرف صحابیت حاصل ہے۔ امام احمد رحمہ اللہ نے کتاب الایمان میں ان کی روایت نقل کی ہے۔ میں کہتا ہوں: امام احمد رحمہ اللہ کی کتاب الایمان میں وہ روایت بطریق ابن اسحاق بحوالہ سعد بن بکر مروی ہے جنہیں شرف صحابیت حاصل ہے پھر سابقہ اثر (قول صحابی) سعید بن عمارہ جو بنی سعد بن عمارہ کے فرد ہیں۔ ان کے حالات میں ذکر کیا پہلے بتایا جا چکا ہے کہ انہیں سعد اور سعید کہا جاتا ہے، لگتا ہے جو نسخہ ذہبی کے پاس تھا اس میں لفظی غلطی ہوئی ہے۔ ‘اخی بنی’ ‘اخبرنی’ بن گیا جس سے یہ نتیجہ نکلا کہ سعد بن بکر صحابی ہیں۔ واقعہ یہ ہے کہ ان کا یہ کہنا کہ انہیں شرف صحابیت حاصل ہے سے مراد سعید بن عمارہ ہیں۔ ہے سعد بن بکر تو وہ ان کے پردادے ہیں، جو صحابہ کی ایک جماعت کی اولاد کا بہت بڑا بطن ہے، ان میں اور اُن میں بے شمار پشتیں ہیں۔ واللہ المستعان۔"],[3669,"§۳۶۷۵ ۔ سعد بن عمیلہ الفزاری\nانہیں دور نبوی میسر ہوا۔ سیف نے الفتوح میں لکھا ہے کہ سیدنا سعد بن ابی وقاص نے انہیں فتح قادسیہ کی خوشخبری دینے کے لیے سیدنا عمر رضی اللہ عنہ کے پاس بھیجا تھا۔"],[3670,"§۳۶۷۶ ۔ سعد بن مالک الاعرج\nبقول بعض: الاقرع بمعنی۔ دور نبوی پایا ہے اور سیدنا عمر رضی اللہ عنہ کے پاس آئے۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں بحوالہ سعد الاعرج روایت کی ہے کہ وہ مدینہ آئے تو سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: کہاں کا ارادہ ہے؟ عرض کی: جہاد۔ فرمایا: اپنے دوست یعنی یعلی بن امیہ کے پاس لوٹ جاؤ۔ یعلی ان دنوں یمن کے گورنر تھے۔ کیونکہ کوئی کام اس کے حق کے ساتھ کرنا بہترین جہاد ہے۔ عبد الرزاق نے یہ روایت طویل نقل کی ہے اور محمد بن حسن نے کتاب الآثار میں امام ابو حنیفہ، عطاء بن سائب بحوالہ حسن روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے سعد بن مالک یا سعید کو زکوۃ وصول کرنے بھیجا۔"],[3671,"§۳۶۷۷ ۔ سعد بن نوفل\nانہیں دور نبوی نصیب ہوا۔ سیدنا عمر رضی اللہ عنہ کی طرف سے جار کے گورنر تھے۔ ان سے ان کا بیٹا عبد اللہ(1) روایت کرتا ہے، ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔ قسم اول میں سعید بن نوفل کا ذکر ہوا ہے کہ ان کے صحابی ہونے میں اختلاف ہے، شاید وہ یہی ہیں۔","",{"fn":"(1) التاریخ الکبیر (۲/۶۶)\n(2) الثقات (۴/۱۹۷)"}],[3672,"§۳۶۷۸ ۔ سعد السبائی\nواقدی نے عہد نبوی صلی اللہ علیہ وسلم میں اہل سباء کے مسلمان ہونے والے لوگوں میں ان کا ذکر کیا ہے۔"],[3673,"§۳۶۷۹ ۔ سعد (مولا اسود بن سفیان)\nدور نبوی نصیب ہوا اور سیدنا عمر رضی اللہ عنہ سے سماع کیا ہے۔ ان سے ان کا بیٹا عبد الرحمن روایت کرتا ہے۔ امام بخاری(1) نے اپنی تاریخ میں اور ابن ابی حاتم نے ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۲/۵۳)"}],[3674,"§۳۶۸۰ ۔ سعد المعطل ہذلی\nمخضرمی ہیں۔ مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے، لیکن کسی شعر کا تذکرہ نہیں کیا۔"],[3675,"§۳۶۸۱ ۔ سفر بن مالک عبسی\nدور نبوی پایا اور سیدنا عمر رضی اللہ عنہ سے سماع کیا ہے۔ ان سے حلام بن صالح روایت کرتے ہیں۔ امام بخاری(1) اور ابن حبان(2) نے تابعین میں ان کا ذکر کیا ہے۔ قسم اول میں سعر بن سوادہ کا تذکرہ ہوا ہے جنہیں عسکری نے مخضرمین میں شامل کیا ہے، وہ ان کے علاوہ ہیں۔","",{"fn":"(1) التاریخ الکبیر (۲/۲۰۰)\n(2) الثقات (۴/۳۴۵)"}],[3676,"§۳۶۸۲ ۔ سعید بن حیدہ\nقسم اول میں ذکر ہوا ہے، میں نے تنبیہ کی تھی کہ یہ اس قسم کے ہیں۔"],[3677,"§۳۶۸۳ ۔ سعید بن ساریہ\nبن مرہ بن عمران بن رباح بن سالم بن غاضرہ بن حبشیہ بن کعب خزاعی۔ دور نبوی پایا ہے۔ سیدنا علی رضی اللہ عنہ کے باڈی گارڈوں میں سے تھے، آپ نے انہیں آذربائیجان کا والی بنا دیا تھا، ابن کلبی نے ان کا ذکر کیا ہے۔"],[3678,"§۳۶۸۴ ۔ سعید بن البارد و ورود\nان پانچوں میں سے ایک ہیں جنہیں صدیق اکبر رضی اللہ عنہ نے اسود عنسی کے خلاف فیروز کی مدد و امداد کا خط لکھا تھا۔ سیف وغیرہ نے ان کا ذکر کیا ہے۔"],[3679,"§۳۶۸۵ ۔ سعید بن نعمان عدوی\nسیف اور طبرانی کا بیان ہے سیدنا خالد بن ولید رضی اللہ عنہ نے فوج میں تقسیم کے بعد خمس کا جو حصہ بچ گیا وہ دے کر اور فتح کی خوشخبری پہنچانے کے لیے صدیق اکبر رضی اللہ عنہ کے پاس بھیجا تھا۔"],[3680,"§۳۶۸۶ ۔ سعید بن نمران ہمدانی\nبقول خلیفہ: دور نبوی پایا ہے، جنگ یرموک میں بھی شریک ہوئے اور صدیق اکبر و عمر رضی اللہ عنہما سے سماع کیا ہے اور سیدنا علی رضی اللہ عنہ کے کاتب رہے۔ حمزہ بن یوسف تاریخ جرجان میں لکھتے ہیں: ان لوگوں میں سے تھے جو حجر بن عدی کے ساتھ روانہ کیے، ان کے طرفدار تھے۔ پھر رہا کر دیئے گئے تو جرجان منتقل ہو گئے، وہیں اپنی حویلی بنائی۔ سیف کا بیان ہے: ہاشم بن عتبہ جب یرموک کے بعد واپس آئے تو ستر کی نفری میں سعید بن نمران کو مقرر کیا۔ ابن ابی خیثمہ کی روایت ہے، مصعب نے انہیں قاضی بنانا چاہا تو اُن کے بھائی نے انہیں منع کیا کہ یہ سیدنا علی رضی اللہ عنہ کے ساتھیوں میں سے ہیں۔ مسدد نے اپنی مسند میں اور ابن المبارک نے ”کتاب الزہد“ میں بطریق عامر بجلی بواسطہ سعید بن نمران بحوالہ صدیق اکبر رضی اللہ تعالیٰ کے ارشاد: ”پھر وہ ڈٹ گئے،“(1) کی تفسیر نقل کی ہے۔ فرمایا: وہ لوگ ہیں جنہوں نے اللہ تعالیٰ کے ساتھ کسی چیز کو شریک نہیں کیا۔ معاویہ بن صالح بواسطہ یحیی بن معین اہل کوفہ کے ناموں میں فرماتے ہیں: سعید بن نمران نے صدیق اکبر رضی اللہ عنہ سے سماع کیا ہے اور ستر (۷۰ھ) کی دہائی میں فوت ہوئے۔","",{"fn":"(1) سورۃ فصلت (۳۰)"}],[3681,"§۳۶۸۷ ۔ سعید بن وہب خیوانی(1)\nدور نبوی پایا ہے، اور یمن میں نبی صلی اللہ علیہ وسلم کی حیات میں معاذ بن جبل رضی اللہ عنہ سے سماع کیا ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ سیدنا علی، ابن مسعود، سلمان اور حذیفہ وغیرہ صحابہ کرام رضی اللہ عنہم سے روایت کی ہے جبکہ ان سے روایت کرنے والوں میں ان کا بیٹا عبد الرحمن، ابو اسحاق اور عمارہ بن عمیر شامل ہیں۔ بقول ابن حبان(2) یہ وہی ہیں جنہیں سعید بن ابی جزہ کہا جاتا ہے، ابن سعید کا قول ہے: سیدنا علی رضی اللہ عنہ کے ساتھ ہو گئے تھے، لقب قراد (چیچڑی) اسی وجہ سے ملا ہے، پچانوے یا چھیانوے (۹۵، ۹۶ھ) میں انتقال ہوا۔ امام بخاری(3)، ابن سعد اور بجلی نے انہیں تابعین میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۰۰) تجرید (۱/۲۲۵)\n(2) الثقات (۴/۲۹۱)\n(3) التاریخ الکبیر (۱/۵۱۷)"}],[3682,"§۳۶۸۸ ۔ سعیہ بن غریض\nبن عاد یا تیمادی۔ تیماء جو حجاز و شام کا درمیانی علاقہ ہے اس کی طرف نسبت ہے، یہ سموال بن عادیا کے بھتیجے ہیں جو وفا میں بطور مثل مشہور ہیں۔ دور جاہلیت اور اسلام پایا ہے۔ ابو الفرج اصبہانی کا قول ہے: انہوں نے لمبی عمر پائی، اسلام کا دور پایا تو مسلمان ہو گئے خلافت معاویہ کے آخری دور میں فوت ہوئے۔ پھر ہشیم بن عدی کی سند سے روایت کی ہے۔ امیر معاویہ نے حج کیا تو مسجد میں ایک شیخ (بزرگ) کو نماز پڑھتے دیکھا۔ پوچھا: یہ کون ہیں؟ لوگوں نے بتایا: سعیہ بن عریض ہیں۔ آپ نے بلاوا بھیجا تو وہ آ گئے۔ پھر ایک لمبا واقعہ ذکر کیا جس کے آخر میں ہے، امیر معاویہ نے فرمایا: بابا جی کا ذہنی توازن ٹھیک نہیں، انہیں اٹھا کر لے جاؤ۔ ان کے نام میں عین کے بعد یا سعیہ رائج ہے جس کی طرف قسم اول میں اشارہ ہو چکا ہے۔"],[3683,"§۳۶۸۹ ۔ سفیان بن سفیان جذامی\nان کے بھائی حسن اور حسین کے ساتھ ان کا ذکر ہوا ہے کہ یہ ارتداد کے فتنہ میں اسلام پر ثابت قدم رہے۔"],[3684,"§۳۶۹۰ ۔ سفیان بن عمرو سلمی\nوٹیمہ کا بیان ہے اپنے اسلام پر قائم رہنے والوں میں سے ایک ہیں، اپنی قوم کو مرتد ہونے پر ملامت کی اور ان سے بڑا والہانہ خطاب کیا تو انہوں نے انہیں برا بھلا کہا، جس کے متعلق ان کے اشعار نقل کیے ہیں۔ جب ہر طرح سے ان سے مایوس ہو گئے تو مدینہ چلے گئے اور وہیں کے ہو رہے۔"],[3685,"§۳۶۹۱ ۔ سفیان بن ہانئ\nبن جبیر ابن عمرو بن سعید بن ناخر ابو سالم حیشانی معافر کے حلیف، مصر فروکش ہوئے۔ بقول ابن مندہ: ان کے صحابی ہونے میں اختلاف ہے۔ میں کہتا ہوں: امام بخاری(1)، مسلم، ابو حاتم(2)، عجلی اور ابن حبان(3) رحمہم اللہ کا اس پہ اتفاق ہے یہ تابعی ہیں۔ ابن یونس کا قول ہے: فتح مصر میں شریک ہوئے، سیدنا علی رضی اللہ عنہ سے ان کی روایت ہے، ان کے پاس گئے اور ان سے کسب فیض کیا۔ اسی طرح ابو ذر، عقبہ بن عامر اور عبد اللہ بن عمرو بن عاص رضی اللہ عنہم سے روایت کی ہے جبکہ ان سے ان کا بیٹا سالم، پوتا سعید بن سالم، یزید بن ابی حبیب اور بکر بن سوادہ وغیرہ روایت کرتے ہیں۔ بقول ابن یونس: اسکندریہ عبد العزیز بن مروان کے دور حکومت میں فوت ہوئے۔","",{"fn":"(1) التاریخ الکبیر (۲/۸۷)\n(2) الجرح والتعدیل (۴/۲۱۹)\n(3) الثقات (۴/۳۱۹)"}],[3686,"§۳۶۹۲ ۔ سفیان الہذلی نضر کے والد\nدور نبوت پایا ہے۔ ابو نعیم نے دلائل میں بطریق نضر بن سفیان بحوالہ ان کے والد روایت کی ہے، فرمایا: ہم اپنے قافلے کے ساتھ شام گئے۔ جب ہم معاویہ کے نزدیک پہنچے تو ہم نے وہیں رات بسیرا کیا، اچانک فضاء میں ایک گھڑ سوار نظر آیا جو کہہ رہا تھا۔ لوگو! بیدار ہو جاؤ یہ سونے کا وقت نہیں، احمد صلی اللہ علیہ وسلم نام کا ظہور ہو چکا ہے، شیاطین بری طرح دھتکار دیئے گئے، ہم اپنے گھر واپس آئے تو لوگوں میں یہ بات مشہور ہو چکی تھی کہ مکہ میں قریش میں سے احمد نامی نبی مبعوث ہو چکے ہیں۔"],[3687,"§۳۶۹۳ ۔ سلمہ بن حبیش\nبن کثیف بن سنان بن بدر بن ثعلبہ بن حبال بن نصر بن غاضرہ اسدی - اسد خزیمہ مرزبانی نے ان کا ذکر کیا ہے۔ یمامہ میں خالد بن ولید رضی اللہ عنہ کے لشکر میں تھے، جس کے متعلق لکھتے ہیں: ”میں اور میری خاکستری رنگ کی اونٹنی ہر ایک مختلف خواہشیں لیے ہوئے ہیں، جب ہم جدا ہونے کی جگہ پہنچے۔”"],[3688,"§۳۶۹۴ ۔ سلمہ بن سبرہ(1)(2)(3)\nانہیں دور نبوی نصیب ہوا۔ اور سیدنا عمر، معاذ اور سلمان رضی اللہ عنہم سے سماع کیا ہے۔ ان سے ابو وائل روایت کرتے ہیں۔ مسدد، بغوی نے جعدیات میں روایت کی ہے کہ سلمہ بن سبرہ نے فرمایا: معاذ بن جبل رضی اللہ عنہ نے ہم سے خطاب کیا۔ پھر ایک واقعہ لکھا۔ ابن سعد نے اہل کوفہ کے پہلے طبقہ تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۲۵) استیعاب (۱۰۱۵)\n(2) مختصر تاریخ دمشق (۱۰/۲۷)\n(3) تجرید (۱/۲۳۰)"}],[3689,"§۳۶۹۵ ۔ سلمہ بن سلم الجہنی\nبقول ابن عساکر: دور نبوی پایا ہے اور شام کے جہاد میں شریک ہوئے اور مرج صفر تیرہ (۱۳ھ) میں شہید ہوئے۔ پھر ابو حسان زیادی سے سندا اس کا ذکر کیا۔"],[3690,"§۳۶۹۶ ۔ سلیک الفزاری\nدور نبوت پایا ہے اور جنگ جلولاء میں شریک ہوئے۔ ثوری کی روایت ہے کہ سلیک فزاری نے فرمایا: جب سعد بن ابی وقاص جلولاء بھیجے گئے تو میں ان لوگوں میں تھا۔ ابن ابی حاتم(1) نے ان کا ذکر کیا ہے اور یہ ان سلیک بن سلکہ کے علاوہ ہیں جو عرب کے مشہور فقراء میں سے ہیں، جو دور جاہلیت میں فوت ہوئے۔","",{"fn":"(1) الجرح والتعدیل (۴/۳۰۹)"}],[3691,"§۳۶۹۷ ۔ سلیک العقیلی الاقطع\nدور نبوت پایا ہے اور جنگ یمامہ میں شریک ہوئے۔ مرتدوں کے خلاف جنگ میں ان کی ہتھیلی کٹ گئی تھی، جس کے متعلق وہ کہتے ہیں: ”تو مجھے اور میرے بھائی عطارد کو کیسے دیکھتا ہے، ہم بنی حنیفہ کا ہر طرح دفاع کر رہے ہیں۔ میں ہتھیلی اور بازو کو تلاش کر رہا ہوں۔ میں اسے تلاش کر رہا ہوں لیکن مجھے کوئی غم نہیں“۔"],[3692,"§۳۶۹۸ ۔ سلیل بن زید بن مالک بن الہمعلی طائی تم سنی\nدور نبوی پایا ہے اور فتوحات عراق میں شریک ہوئے جس روز مسلمانوں نے مدائن پہنچنے کے لیے دریائے دجلہ عبور کیا تو یہ ڈوب گئے، ان کے علاوہ کوئی نہیں ڈوبا، ابن کلبی نے ان کا ذکر کیا ہے۔"],[3693,"§۳۶۹۹ ۔ سلیم بن عتر\nابن سلمہ بن مالک تھی ابو سلمہ، دور نبوی پایا ہے اور فتح مصر میں شریک ہوئے۔ یہ سعید بن عفیر کا قول ہے اور ابن عائذ کی روایت ہے: جابیہ میں سیدنا عمر رضی اللہ عنہ کے خطاب میں شریک ہوئے۔ امام بخاری(1) نے تاریخ میں لکھا ہے: ابو درداء رضی اللہ عنہ سے سماع کیا ہے۔ ابن یونس کا قول ہے انہیں زیادہ عبادت کی وجہ سے ناسک (عبادت گزار) کہا جاتا تھا۔ ابن ابی حاتم کی روایت ہے سلیم بن عتر بہترین تابعین میں سے ہیں۔ ابن یونس کا قول ہے: خلافت فاروقی میں ہجرت کی اور جابیہ میں آپ کا خطبہ سنا۔ سیدنا امیر معاویہ نے قضاء و قصص کے عہدے ایک ساتھ عطا کیے۔ عہدہ قضاء پر چالیس سال تک برقرار رہے۔ اور دمیاط میں پچھتر (۷۵ھ) میں فوت ہوئے۔ صلہ بن حارث غفاری کے حالات میں ان کا ذکر ہوگا۔ عبد الرحمن بن زیاد بن انعم کی بحوالہ سلیم بن عتر روایت ہے فرمایا: سیدنا عمر رضی اللہ عنہ نے سورہ حج کے دوران ہمیں سجدہ کرایا۔ ابن لہیعہ بواسطہ حارث بن یزید روایت کرتے ہیں کہ میں نے حنش بن عبد اللہ سے پوچھا، اللہ تعالیٰ کا ارشاد ہے: ”وہ لوگ رات بہت تھوڑا سوتے ہیں“۔(2) فرمایا: اللہ کی قسم! یہ سلیم بن عتر اور ابو عبد الرحمن الجبلی کی صفت ہے۔ حارث بن یزید سے ہی مروی ہے کہ ہر تین دن پہ ایک ختم کیا کرتے تھے، ایک قول ہے: وہ رات میں بکثرت نماز پڑھتے اور اپنی اہلیہ سے ہم بستر ہوتے، جب ان کا انتقال ہوا تو ان کی اہلیہ کہنے لگی: اللہ تعالیٰ آپ پر رحم کرے، آپ اپنے رب کو راضی اور اپنے گھرانے کو خوش کرتے تھے۔ یہ روایت ابو عبیدہ نے فضائل القرآن میں نقل کی ہے، ان کے مکمل حالات ”قضاۃ مصر“ میں موجود ہیں۔","",{"fn":"(1) التاریخ الکبیر (۲/۱۲۵)\n(2) سورۃ الذاریات (۱۷)"}],[3694,"§۳۷۰۰ ۔ سلیم انصاری(1)\nیا مخزومی ان کے مولا ہیں۔ ابو عامر کنیت ہے۔ دور نبوت پایا ہے۔ ابن ابی خیثمہ، ابو زرعہ دمشقی اور ابو حاتم رازی کا قول ہے: انہوں نے صدیق اکبر رضی اللہ عنہ کی اقتداء میں نماز پڑھی۔ ابو عمر(2) لکھتے ہیں: سلیم بن عامر اور ابو عامر خبائری نہیں۔ طبرانی کی روایت ہے کہ سلیم بن عامر ان لوگوں میں سے ہیں جنہیں خالد بن ولید رضی اللہ عنہ نے حلب کے محاصرے کے دوران قید کیا تھا، فرماتے ہیں: جب ہم لوگ صدیق اکبر رضی اللہ عنہ کے پاس پہنچے تو مجھے مکتب بھیج دیا۔ انہی سے مروی ہے، فرمایا: میں نے ابو بکر، عمر اور عثمان رضی اللہ عنہم کو دیکھا، ان لوگوں نے آگ پر پکی ہوئی چیز کھا کر بغیر نیا وضو کے نماز پڑھی ہے۔ رحیم کی روایت ہے کہ انہوں نے فرمایا: میں نے سات ماہ صدیق اکبر رضی اللہ عنہ کے پیچھے نمازیں پڑھیں۔ یہی روایت امام بخاری رحمہ اللہ نے اپنی تاریخ صغیر میں باضافہ نقل کی ہے، سیدنا ابو بکر رضی اللہ عنہ نے انہیں عمار بن یاسر رضی اللہ عنہ کے لیے بطور خادم دے دیا تھا، یہ خالد بن ولید رضی اللہ عنہ کو مال غنیمت میں ملے تھے۔ پھر فتح دمشق اور قادسیہ میں شریک ہوئے۔ تاریخ حمصیین میں ابو بکر بغدادی لکھتے ہیں: ”حلب کے محاصرہ کے دوران خالد بن ولید رضی اللہ عنہ نے انہیں گرفتار کیا تھا،”(2)","",{"fn":"(1) اسد الغابہ (ت: ۲۲۱۷) استیعاب (ت: ۱۰۵۱) تجرید اسماء الصحابۃ (۱/۲۳۶)\n(2) الاستیعاب (۲/۲۰۷)"}],[3695,"§۳۷۰۱ ۔ سمرہ بن جعونہ(2)\nدور نبوی پایا ہے اور جنگ جلولاء میں شریک ہوئے۔ سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں، ان سے ابو اسحاق سبیعی نے روایت کی ہے۔ ابن ابی حاتم(1) اور ابن حبان نے ان کا ذکر کیا ہے۔","",{"fn":"(1) مختصر تاریخ دمشق (۱۰/۲۰۰)\n(2) الثقات (۴/۳۴۰)"}],[3696,"§۳۷۰۲ ۔ سمط بن اسود کندی\nشرحبیل کے والد۔ جنگ یرموک میں شریک ہوئے۔ الردہ میں مذکور ہے، وہ اور ان کا بیٹا اس وقت بھی اسلام پر برقرار ہے جب کندہ مرتد ہو گئے تھے۔ یہ دونوں زیاد بن لبید سے جاملے۔ لیکن تاریخ مظفری میں میں نے دیکھا ہے کہ جب اہل یمن مرتد ہوئے تو کندہ سارے کا سارا مرتد ہو گیا۔ صرف شرحبیل اور ان کا بیٹا اس فتنے سے محفوظ رہا۔ واللہ اعلم۔ پھر مجھے معلوم ہوا کہ پہلا قول درست ہے جس کا میں شرحبیل کے حالات میں ذکر کروں گا۔ سنن میں بیہقی نے بحوالہ شعبی روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے شرحبیل بن سمط کو مدائن میں اور ان کے والد سمط کو شام میں تعینات کیا۔ انہوں نے سیدنا عمر رضی اللہ عنہ کو لکھا: آپ یہ حکم تو دیتے ہیں کہ (رشتہ دار) قیدیوں کو جدا جدا نہ کیا جائے، جبکہ آپ نے مجھے اور میرے بیٹے کو (باوجودیکہ ہم آزاد ہیں) جدا کر رکھا ہے، تو انہوں نے ان کی طرف لکھا اور ان سے ان کا بیٹا ملا دیا۔(1)","",{"fn":"(1) مختصر تاریخ دمشق (۱۰/۲۰۳)"}],[3697,"§۳۷۰۳ ۔ سمعان بن ہبیرہ(1)(2)\nبن ساحق بن بجیر بن اسامہ بن نصر بن معین بن حارث بن ثعلبہ بن دوران بن اسد بن خزیمہ اسدی۔ ابو السمال شاعر جنہیں دور نبوت میسر ہوا۔ کوفہ فروکش ہوئے۔ ابو حاتم بحبانی کتاب ”المعمرین“ میں لکھتے ہیں: ہمارے مشائخ نے ہمیں بتایا کہ سمعان بن ہبیرہ ابو السمال اسدی ایک سو سرسٹھ(۱۶۷) برس زندہ رہے۔ ”المؤتلف“ میں دار قطنی لکھتے ہیں: فتنہ ارتداد میں طلیحہ کے ساتھ تھے جب سیدنا خالد رضی اللہ عنہ نے اسے قابو کر لیا تو انہیں نے طلیحہ سے پوچھا۔ اب کیا رائے ہے؟... پھر ایک واقعہ نقل کیا۔ کتاب النسب میں زبیر بن بکار بحوالہ ابو صالح فقعی اور ابو فقس جو دونوں اسدی ہیں، روایت کی ہے کہ وہ عرب کے علماء میں سے تھے فرماتے ہیں: اسد بن خزیمہ کے ہاں عمرہ پیدا ہوا اور عمرو سے م، جذام اور عاملہ پیدا ہوئے۔ جس کے متعلق ابو السمال اسدی کہتے ہیں: پھر ان کا ایسا ہی نسب ذکر کیا ہے، جیسا یہاں ہے: ”جذام اور تم کو ایک ساتھ پیام پہنچا دو جو سالوں والی اونٹنیوں پر سوار ہیں۔ اور عاملہ جو رشتہ دار ہیں، گویا یہ لوگ نسب والے ہیں۔ یہ ہمارے قبائل ہیں جن کے گھرانے ہم سے دور ہیں جبکہ رشتہ داری میں وہ زیادہ قریب ہیں ہمارے پاس آؤ، ہم معتف کے بھائی اور کھلی جگہ میں تنہا بیٹھیں“۔ مغیرہ بن مقسم کا قول ہے: ابو السمال، اپنے گھر کا دروازہ کھلا رکھتے، ان کا ایک شخص اعلان کرتا: جس کی کوئی جگہ نہیں اس کا ٹھکانہ ابو السمال کے ذمہ ہے۔ فرماتے ہیں: یہ بات سیدنا عثمان رضی اللہ عنہ کو معلوم ہوئی تو آپ نے اپنے مہمانوں کے لیے ایک مہمان خانہ بنا لیا۔ مرزبانی نے اپنے معجم میں لکھا ہے: انہوں نے ہی رمضان میں نجاشی حارثی کے ساتھ شراب پی لی تھی تو نجاشی پر حد لگی اور ابو السمال بھاگ نکلے جس کے متعلق انہوں نے اشعار کہے۔(3)","",{"fn":"(1) التاریخ الکبیر (۲/۱۲۶)\n(2) المعمرین (۶۵)\n(3) مختصر تاریخ (۱۰/۲۰۷)"}],[3698,"§۳۷۰۴ ۔ سمیر بن عبد اللہ\nبن نہار ابن غانم بن سعد بن جبل بن کنانہ بن ناجیہ بن مراد المرادی۔ انہیں دور نبوت حاصل ہے، ان کا زائدہ نامی ایک بیٹا تھا جو سیدنا علی رضی اللہ عنہ کے ساتھ نہروان میں شہید ہوئے۔ ابن کلبی نے ان کا ذکر کیا ہے، ان کے بھائی عمرو بن عبد اللہ بن نہار کا تذکرہ ہوتا ہے۔"],[3699,"§۳۷۰۵ ۔ سمیط بن عمیر\nدور نبوی پایا ہے اور ان کی جو جنگ ہوئی اس کا حال سیدنا عمر رضی اللہ عنہ کو لکھا۔ عمران بن حصین سے روایت کرتے ہیں۔ ان سے عمران بن حدیر اور عاصم الاحول روایت کرتے ہیں ابن حبان(1) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) الثقات (۴/۳۴۸)"}],[3700,"§۳۷۰۶ ۔ سمیفع(1)\nابن درید کا قول ہے۔ سمیفع کا معنی ہے جرات و پیش قدمی۔ جس نے یہ نام قاف سے لکھا ہے اسے وہم ہوا ہے، اسی طرح جس نے سین پر پیش لکھ کر اسے تصغیر دی، اسے بھی وہم ہوا ہے۔ ذوالکلاع میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۲۲۵۶) تجرید (۱/۲۴۰)"}],[3701,"§۳۷۰۷ ۔ سناس\nبقول بعض: مہلب کے والد۔"],[3702,"§۳۷۰۸ ۔ سنان وداعی\nدور نبوی پایا ہے۔ دار قطنی نے سنن میں بحوالہ سعید بن المسیب روایت کی ہے کہ جب سیدنا عمر رضی اللہ عنہ نے اپنا آخری حج کیا تو اچانک بنی وداعہ کا ایک شخص قتل ہو گیا، آپ نے ان لوگوں سے پوچھا، وہ کہنے لگے: ہمیں قاتل کی کوئی خبر نہیں۔ آپ نے حکم دیا تو ان کے پچاس بوڑھے باہر لائے گئے، آپ انہیں حطیم لے گئے اور ان سے یہ قسم کھلوائی: ”اس عزت والے گھر، عزت والے شہر اور حرمت کی نشانیوں کے رب اللہ کی قسم نہ انہوں نے اسے قتل کیا ہے اور نہ اس کے قاتل کی خبر ہے۔ انہوں نے یہ قسم کھائی تو آپ نے فرمایا: ”مقتول کی دیت (خون بہا) ادا کرو۔ تو ان کے سنان نامی شخص بولے: کیا میری قسم میرے مال کی جگہ کافی نہیں؟ آپ رضی اللہ عنہ نے فرمایا: نہیں! میں نے تم لوگوں کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کے مطابق کیا ہے۔ اس کی سند میں عمر بن صبح متروک راوی ہے۔"],[3703,"§۳۷۰۹ ۔ سنان بن کعب ازدی\nدور نبوی پایا ہے، ان کا بیٹا عبد اللہ شہسواروں اور بہادروں میں سے ایک تھا جو مہلب کے ساتھ تھا۔ مہلب کا کہنا ہے: میں جس بڑی مصیبت میں مبتلا ہوا تو عبد اللہ بن سنان نے میرا خوف دور کر دیا۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[3704,"§۳۷۱۰ ۔ سہم بن حنظلہ غنوی\nبقول مرزبانی: شام کے مخضرمی شاعر ہیں۔"],[3705,"§۳۷۱۱ ۔ سہم بن مسافر\nبن ہرمہ۔ بقول بعض: جرم۔ بقول ابن عساکر: دور نبوی پایا ہے اور فتح دمشق میں شرکت کی، پھر خالد اور عبادہ کے حوالہ سے روایت کی ہے کہ یرموک کے بعد یزید بن ابی سفیان رضی اللہ عنہ کے ساتھ رہنے والے یمنی ہیں اور انہی میں شمار ہوتے ہیں۔(1)","",{"fn":"(1) تجرید (۱/۲۴۳)"}],[3706,"§۳۷۱۲ ۔ سہیل بن ابی جندل\nمسند حارث بن معاویہ دیکھ لی جائے اور وہیں سے نسب وغیرہ لکھا جائے۔"],[3707,"§۳۷۱۳ ۔ سہیل بن حنظلہ(1)\nبن طفیل عامری۔ مشہور شہسوار عامر بن طفیل کے بھتیجے ہیں۔ صحیح میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک شخص چھینکا اور الحمد للہ کہا، جس پر آپ صلی اللہ علیہ وسلم نے اسے یرحمک اللہ سے جواب دیا۔ دوسرا چھینکا لیکن اس نے الحمد للہ نہیں کہا تو آپ صلی اللہ علیہ وسلم نے اسے جواب نہیں دیا۔ (حدیث)(2) جس کی وضاحت میں بتایا گیا ہے کہ وہ دونوں عامر بن طفیل جنہوں نے الحمد للہ نہیں کہا اور ان کے بھتیجے تھے۔ جنہوں نے الحمد للہ کہا اور آپ صلی اللہ علیہ وسلم نے انہیں جواب دیا۔ طبرانی نے مسند سہیل بن سعد میں اپنی معجم کبیر میں اپنی سند سے اس کا ذکر کیا ہے، لیکن مجھے انساب میں طفیل کی اولاد میں کوئی شخص ان کے علاوہ نہیں ملا جس نے دور نبوی پایا ہو۔ بظاہر وہ یہی ہیں، نبی صلی اللہ علیہ وسلم کے بعد بھی عرصہ دراز زندہ رہے۔ حضرت عبدالعزیز بن مروان نے ان کی بیٹی سے شادی کی تھی، جس سے ام البنین پیدا ہوئیں۔ جن سے ولید بن عبدالملک نے شادی کی۔ سہیل اگر اپنے چچا کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوئے تو اس وقت اسلام نہیں لائے تھے۔ بلکہ بعد میں مسلمان ہوئے۔ اس لیے وہ اس قسم میں شامل ہیں۔ یہ بھی احتمال ہے کہ جب آپ صلی اللہ علیہ وسلم نے انہیں چھینک کا جواب دیا تھا اس وقت مسلمان ہوئے ہوں اگرچہ ظاہر یہی ہے کہ وہ اپنے چچا کی پیروی میں اسلام نہیں لائے تھے۔ واللہ اعلم","",{"fn":"(1) تجرید (۲۴۳/۱)\n(2) بخاری کتاب الادب باب الحمد للعاطس (۶۲۲۱) مسلم کتاب الزهد والرقائق باب تشمیت العاطس و کراہیۃ التثاؤب (۵۳) ترمذی کتاب الادب باب ما جاء فی ایجاب التشمیث بحمد اللہ (۲۷۴۲)"}],[3708,"§۳۷۱۴ ۔ سوّار بن اوفی قشیری\nبقول مرزبانی: مخضرمی ہیں اور نابغہ سے ہجو کا مقابلہ کرتے تھے۔ انہی کا یہ شعر ہے: ؎\n”جب نیزے ٹکرا کر اکھڑا کے سرخ ہو جاتے ہیں تو لوگ سوار کو بلاتے ہیں، ہر سخت دن کے لیے سوار ہی ہوتا ہے۔“\nبقول ابن کلبی: ان کی والدہ کا نام حیا بنت خالد بن رباح جرمی ہے۔ نابغہ ان سے مخاطب ہو کے کہتا ہے: ؎\n”حیا کے بیٹے! تو مجھ پر غالب آ کر مجھ پر ظلم کرتا ہے تو نے دوزخی بات جس سے گمراہی ہو جمع کر رکھی ہے۔“\nسوّار کے فخریہ اشعار میں سے چند اشعار ملاحظہ ہوں: ؎\n”میرا چچا ابو الجمل ربیعہ ہمیشہ جوان رہا یہاں تک کہ عزت و شرف تلاش کرتے مر گیا، ہمیں میں سے ابن عتاب اور اپنا پاؤں تلاش کرنے والا ہے اور وہ شخص بھی ہم میں سے ہے جس نے قبیلہ کو حاجب دربان ادا کر دیا۔\nابن عتاب کا تذکرہ قیس میں بیان ہوگا اور پاؤں تلاش کرنے والے کا واقعہ حیاض میں گزر چکا ہے۔"]])